/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"총칙과 적용범위":{"묶음":[{"머리":"목적(제1조)","줄":[{"t":"목적 문장: 시장지배적지위의 남용과 과도한 경제력집중을 방지하고 부당한 공동행위와 불공정거래행위를 규제한다. 이를 통해 공정하고 자유로운 경쟁을 촉진한다.","src":"공정거래법 제1조"},{"t":"목적에 명시된 것: 공정하고 자유로운 경쟁 촉진, 창의적인 기업활동 조성, 소비자 보호, 국민경제의 균형 있는 발전 도모.","src":"공정거래법 제1조 | 기출 2022-3 | 기출 2023-5 | 기출 2024-1 | 기출 2025-3 | 기출 2026-1"},{"t":"목적에 없는 것: 경제의 민주화, 중소기업의 보호와 육성, 완전경쟁의 실현, 경제규제의 완화, 사회복지(사회복리) 증진, 적정한 소득의 분배, 정의로운 시장경제.","src":"공정거래법 제1조 | 기출 2022-3 | 기출 2023-5 | 기출 2024-1 | 기출 2025-3 | 기출 2026-1"}]},{"머리":"사업자·사업자단체 정의(제2조 제1호·제2호)","줄":[{"t":"사업자: 제조업, 서비스업 또는 그 밖의 사업을 하는 자.","src":"공정거래법 제2조 제1호"},{"t":"사업자단체에 관한 규정을 적용할 때는 사업자의 이익을 위한 행위를 하는 임원, 종업원, 대리인, 그 밖의 자를 사업자로 본다.","src":"공정거래법 제2조 제1호 | 기출 2021-1 | 기출 2022-1 | 기출 2023-1 | 기출 2025-1 | 기출 2026-2"},{"t":"종업원: 계속하여 회사의 업무에 종사하는 사람으로서 임원 외의 사람.","src":"공정거래법 제2조 제1호"},{"t":"사업자단체: 형태가 무엇이든 상관없이 둘 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 그 연합체.","src":"공정거래법 제2조 제2호"},{"t":"예술을 목적으로 하는 비영리단체도 사업자에 해당할 수 있다.","src":"기출 2022-1"},{"t":"농업, 어업 등 제1차 산업을 하는 자도 사업자에 해당할 수 있다.","src":"기출 2022-1"},{"t":"국가나 지방자치단체는 사경제의 주체로서 거래행위를 하는 범위에서만 사업자로 본다. 공행정관계에서는 사업자가 아니다.","src":"기출 2022-1 | 기출 2023-1 | 기출 2026-3"},{"t":"대법원은 서울특별시가 전동차 제작납품·구매계약의 주체인 경우 사업자성을 인정했다.","src":"기출 2022-2 | 기출 2023-1"},{"t":"변호사·의사 같은 전문인이 하는 사업에는 이 법이 적용된다.","src":"기출 2022-2"},{"t":"노동조합의 쟁의행위에는 이 법이 적용되지 않는다.","src":"기출 2022-2"}]},{"머리":"시장지배적사업자·일정한 거래분야·경쟁의 실질적 제한(제2조 제3호~제5호)","줄":[{"t":"시장지배적사업자: 일정한 거래분야의 공급자나 수요자로서 단독으로 또는 다른 사업자와 함께 상품·용역의 가격, 수량, 품질, 그 밖의 거래조건을 결정·유지·변경할 수 있는 시장지위를 가진 사업자.","src":"공정거래법 제2조 제3호"},{"t":"시장지배적사업자 판단 요소: 시장점유율, 진입장벽의 존재 및 정도, 경쟁사업자의 상대적 규모 등을 종합 고려한다.","src":"공정거래법 제2조 제3호"},{"t":"일정한 거래분야: 거래의 객체별·단계별 또는 지역별로 경쟁관계에 있거나 경쟁관계가 성립될 수 있는 분야.","src":"공정거래법 제2조 제4호 | 기출 2021-1 | 기출 2023-1 | 기출 2025-1"},{"t":"경쟁을 실질적으로 제한하는 행위: 일정한 거래분야의 경쟁이 감소하여 특정 사업자 또는 사업자단체의 의사에 따라 어느 정도 자유로이 가격, 수량, 품질, 그 밖의 거래조건 등의 결정에 영향을 미치거나 미칠 우려가 있는 상태를 초래하는 행위.","src":"공정거래법 제2조 제5호"}]},{"머리":"임원·계열회사·여신 등 용어 정의(제2조)","줄":[{"t":"임원: 이사, 대표이사, 업무집행을 하는 무한책임사원, 감사, 이들에 준하는 사람, 지배인 등 본점이나 지점의 영업 전반을 총괄적으로 처리할 수 있는 상업사용인.","src":"공정거래법 제2조 제6호 | 기출 2021-1 | 기출 2025-1 | 기출 2026-2"},{"t":"감사와 지배인 등 영업 전반을 총괄하는 상업사용인은 임원에 포함된다. 영업 전반을 총괄할 권한이 없는 상업사용인은 임원이 아니다.","src":"공정거래법 제2조 제6호 | 기출 2026-2"},{"t":"계열회사: 둘 이상의 회사가 동일한 기업집단에 속하는 경우 이들 각각의 회사를 서로 상대방의 계열회사라 한다.","src":"공정거래법 제2조 제12호 | 기출 2021-1 | 기출 2025-1"},{"t":"기업집단: 동일인이 대통령령으로 정하는 기준에 따라 사실상 그 사업내용을 지배하는 회사의 집단. 동일인이 회사이면 동일인과 지배하는 하나 이상의 회사, 회사가 아니면 지배하는 둘 이상의 회사.","src":"공정거래법 제2조 제11호"},{"t":"여신: 국내 금융기관이 하는 대출 및 회사채무의 보증 또는 인수. 국외 금융기관은 포함하지 않는다.","src":"공정거래법 제2조 제19호 | 기출 2021-1 | 기출 2025-1"},{"t":"채무보증: 기업집단에 속하는 회사가 국내 금융기관(은행, 산업은행, 수출입은행, 중소기업은행, 보험회사, 투자매매업자·투자중개업자·종합금융회사, 그 밖에 대통령령이 정하는 금융기관)의 여신과 관련하여 국내 계열회사에 하는 보증.","src":"공정거래법 제2조 제18호"},{"t":"계열출자: 기업집단 소속 회사가 계열회사의 주식을 취득·소유하는 행위. 순환출자: 세 개 이상의 계열출자로 연결된 계열회사 모두가 계열출자회사 및 계열출자대상회사가 되는 관계.","src":"공정거래법 제2조 제13호·제16호"},{"t":"지주회사: 주식 소유를 통해 국내 회사의 사업내용을 지배하는 것을 주된 사업으로 하는 회사로서 자산총액이 대통령령으로 정하는 금액 이상인 회사. 자회사는 지주회사의 지배를 받는 국내 회사, 손자회사는 자회사의 지배를 받는 국내 회사.","src":"공정거래법 제2조 제7호~제9호"},{"t":"재판매가격유지행위: 사업자가 상품 또는 용역을 거래할 때 거래상대방인 사업자 또는 그 다음 거래단계별 사업자에 대해 거래가격을 정하여 그 가격대로 판매·제공할 것을 강제하거나 그 밖의 구속조건을 붙여 거래하는 행위.","src":"공정거래법 제2조 제20호 | 기출 2026-15"}]},{"머리":"국외행위에 대한 적용(제3조)","줄":[{"t":"국외에서 이루어진 행위라도 그 행위가 국내 시장에 영향을 미치는 경우에는 이 법을 적용한다.","src":"공정거래법 제3조 | 기출 2021-2 | 기출 2025-2"},{"t":"역외적용 대상: 외국사업자가 국외에서 한 행위가 국내 시장에 영향을 미친 경우.","src":"공정거래법 제3조 | 기출 2024-2"},{"t":"국내 시장에 대한 영향은 직접적이고 상당하며 합리적으로 예측 가능한 영향으로 제한 해석한다. 간접적 영향까지 모두 포함하지 않는다.","src":"기출 2021-2 | 기출 2022-2 | 기출 2024-2 | 기출 2025-2"},{"t":"외국 법률로 허용되는 행위라는 사정만으로 우리 법 적용이 당연히 배제되지 않는다.","src":"기출 2024-2"},{"t":"규제의 요청에 비해 외국 법률 등을 존중해야 할 요청이 현저히 우월한지도 역외적용에서 고려 대상이다.","src":"기출 2025-2"},{"t":"대법원은 흑연전극봉 제조·판매 외국사업자들의 국외 부당한 공동행위에 역외적용을 인정했다.","src":"기출 2021-2 | 기출 2025-2"},{"t":"공정거래위원회는 비타민 국제카르텔 사건에서 외국사업자들이 외국에서 한 가격담합에 시정명령과 과징금 납부명령을 내렸다.","src":"기출 2025-2"},{"t":"역외적용을 명시한 조문이 없던 때에도 공정거래위원회가 역외적용한 사례가 있다. 역외적용 조문은 법 제정 시부터 있던 것이 아니다.","src":"기출 2021-2 | 기출 2024-2"},{"t":"정부는 대한민국의 법률 및 이익에 반하지 않는 범위에서 외국정부와 이 법의 집행을 위한 협정을 체결할 수 있다.","src":"공정거래법 제56조 제1항 | 기출 2021-2 | 기출 2024-2"}]},{"머리":"독과점적 시장구조의 개선(제4조)","줄":[{"t":"공정거래위원회는 독과점적 시장구조가 장기간 유지되는 상품·용역의 공급시장 또는 수요시장에 경쟁을 촉진하기 위한 시책을 수립·시행하여야 한다.","src":"공정거래법 제4조 제1항"},{"t":"공정거래위원회가 관계 행정기관의 장에게 경쟁 도입 등 시장구조 개선에 관한 의견을 제시할 수 있다. 의견을 받은 관계 행정기관의 장은 검토 후 결과를 공정거래위원회에 송부하여야 한다.","src":"공정거래법 제4조 제2항"},{"t":"공정거래위원회가 수행할 수 있는 업무: 시장구조의 조사 및 공표, 특정 산업의 경쟁상황 분석·규제현황 분석·경쟁촉진 방안 마련. 시장구조의 혁신은 규정에 없다.","src":"공정거래법 제4조 제3항 | 기출 2024-3"},{"t":"공정거래위원회는 사업자와 사업자단체에 제3항 업무에 필요한 자료의 제출을 요청할 수 있다. 제3항·제4항의 사무는 대통령령으로 정하는 바에 따라 다른 기관에 위탁할 수 있다.","src":"공정거래법 제4조 제4항·제5항"}]}],"함정":[{"x":"외국에서 일어난 경쟁제한행위가 국내시장에 미치는 영향은 직접적이거나 간접적인 경우를 모두 포함하여 우리나라의 법을 적용하고 있다.","o":"국외 행위라도 국내 시장에 영향을 미치면 적용한다. 영향은 직접적이고 상당하며 합리적으로 예측 가능한 영향으로 제한 해석한다.","src":"공정거래법 제3조 | 기출 2021-2"},{"x":"국가나 지방자치단체도 공행정관계에서 사업자에 해당할 수 있다.","o":"국가·지방자치단체는 사경제의 주체로서 거래행위를 하는 범위에서만 사업자다. 공행정관계에서는 사업자가 아니다.","src":"기출 2023-1 | 기출 2026-3 | 기출 2022-1"},{"x":"사업자단체에 관한 규정을 적용할 때 임원과는 달리 종업원은 사업자의 이익을 위한 행위를 하더라도 사업자로 보지 않는다.","o":"종업원도 사업자의 이익을 위한 행위를 하면 사업자단체 규정 적용 시 사업자로 본다.","src":"공정거래법 제2조 제1호 | 기출 2023-1"},{"x":"역외적용에 관한 근거 조문은 이 법 제정시부터 존재하였다.","o":"역외적용 조문은 제정 시부터 있던 것이 아니다.","src":"기출 2024-2"},{"x":"이 법의 적용에 의한 규제의 요청에 비하여 외국 법률 등을 존중해야 할 요청이 현저히 우월한 지는 역외적용에 있어서 특별히 고려할 필요는 없다.","o":"외국 법률 등을 존중해야 할 요청이 현저히 우월한지도 역외적용에서 고려한다.","src":"기출 2025-2"},{"x":"사업자의 이익을 위한 행위를 하는 임원은 사업자단체에 관한 규정을 적용할 때에는 사업자로 보지 않는다.","o":"임원도 사업자단체 규정 적용 시 사업자로 본다.","src":"공정거래법 제2조 제1호 | 기출 2026-2"},{"x":"감사는 임원에 해당하지 않는다.","o":"감사는 임원에 해당한다.","src":"공정거래법 제2조 제6호 라목 | 기출 2026-2"},{"x":"이 법은 어느 사업자의 임원이 그 사업자의 업무와 관련하여 금지되는 부당한 공동행위 를 한 경우 그 임원을 벌하는 외에 그 사업자도 처벌하는 양벌 규정을 두고 있지 않다.","o":"양벌규정을 두고 있다.","src":"공정거래법 제128조 | 기출 2026-2"},{"x":"업무감시권만을 갖는 유한책임사원은 임원에 해당한다.","o":"유한책임사원은 임원 목록(이사, 대표이사, 업무집행 무한책임사원, 감사, 준하는 사람, 지배인 등)에 없다.","src":"공정거래법 제2조 제6호 | 기출 2026-2"}]},"시장지배적지위의 남용금지":{"묶음":[{"머리":"시장지배적사업자 판단(제2조 제3호, 시행령 제2조)","줄":[{"t":"공급자뿐 아니라 수요자(용역시장의 수요자 포함)도 시장지배적사업자가 될 수 있다.","src":"공정거래법 제2조 제3호 | 기출 2021-5 | 기출 2023-4 | 기출 2024-4"},{"t":"단독으로 시장지배적지위가 없는 사업자도 다른 사업자와 함께 시장지배적사업자가 될 수 있다.","src":"공정거래법 제2조 제3호 | 기출 2023-4 | 기출 2024-4"},{"t":"가격뿐 아니라 수량, 품질, 그 밖의 거래조건을 결정할 수 있는 시장지위도 해당한다. 상품과 용역 모두 해당한다.","src":"공정거래법 제2조 제3호 | 기출 2024-4"},{"t":"판단 요소: 시장점유율, 진입장벽의 존재 및 정도, 경쟁사업자의 상대적 규모. 지식재산권 행사 수준이나 가격의 남용 정도는 판단 요소로 명시되어 있지 않다.","src":"공정거래법 제2조 제3호 | 기출 2021-5 | 기출 2024-4 | 기출 2025-5"},{"t":"관련 상품의 외국 수입 가능성도 시장지배적지위 판단에서 고려된다.","src":"기출 2021-5"},{"t":"관련시장이 넓게 획정될수록 사업자의 점유율이 낮아져 시장지배적지위를 가질 가능성이 낮아진다.","src":"기출 2021-5"},{"t":"독립된 사업자들이 각자 책임과 계산으로 사업하고 손익분배 등을 함께 하지 않으면 하나의 사업자로 볼 수 없다.","src":"기출 2021-5"},{"t":"시장지배적사업자를 판단할 때는 해당 사업자와 그 계열회사를 하나의 사업자로 본다.","src":"공정거래법 시행령 제2조 제2항 | 기출 2024-5"},{"t":"현재는 추정제도만 있다. 시장지배적사업자의 사전지정·고시제도는 폐지되었다.","src":"기출 2023-4 | 기출 2025-6"}]},{"머리":"시장점유율 산정(시행령 제2조·제11조)","줄":[{"t":"시장점유율: 위반 혐의 행위 종료일이 속하는 사업연도의 직전 1년 동안 국내에서 공급·구매된 상품·용역 금액 중 해당 사업자가 공급·구매한 금액의 비율.","src":"공정거래법 시행령 제2조 제1항 | 기출 2024-5"},{"t":"금액기준으로 산정하기 어려우면 물량기준 또는 생산능력기준으로 산정할 수 있다.","src":"공정거래법 시행령 제2조 제1항 | 기출 2024-5"},{"t":"연간 매출액·구매액: 위반 혐의 행위 종료일(인지일·신고일까지 계속되면 그 일)이 속하는 사업연도의 직전 1년 동안 공급·구매한 상품·용역 금액(간접세 제외).","src":"공정거래법 시행령 제11조 제2항"},{"t":"추정할 때도 해당 사업자와 그 계열회사를 하나의 사업자로 본다.","src":"공정거래법 시행령 제11조 제3항 | 기출 2021-6 | 기출 2022-5"}]},{"머리":"시장지배적사업자의 추정(제6조)","줄":[{"t":"추정 요건 1: 하나의 사업자의 시장점유율이 100분의 50 이상.","src":"공정거래법 제6조 제1호 | 기출 2024-5"},{"t":"추정 요건 2: 셋 이하 사업자의 시장점유율 합계가 100분의 75 이상. 시장점유율 100분의 10 미만인 사업자는 제외한다.","src":"공정거래법 제6조 제2호 | 기출 2025-6 | 기출 2026-6"},{"t":"일정한 거래분야에서 연간 매출액 또는 구매액이 80억원 미만인 사업자는 추정에서 제외한다. (2021 기출 당시 40억원)","src":"공정거래법 제6조 | 기출 2021-4 | 기출 2024-5 | 기출 2025-6"},{"t":"점유율 합계 계산 순서: 계열회사 합산해 한 사업자로 묶기, 상위 3개 사업자 합계 75% 이상인지 확인, 10% 미만 사업자 제외, 사업자별 매출액·구매액 요건 확인.","src":"공정거래법 제6조 | 공정거래법 시행령 제11조 | 기출 2021-6 | 기출 2022-5 | 기출 2026-6"},{"t":"계산 예: A 55%, B 20%, C 10%, D 7%, E 5%, B와 E가 계열회사이면 B·E는 합쳐 25%인 한 사업자. 추정되는 자는 A, B, C, E.","src":"공정거래법 제6조 | 기출 2021-6"},{"t":"계산 예: A 50%, B 20%, C 10%, D 9%, E 5%, 모두 매출액 80억원 이상이면 추정되는 자는 A, B, C. D는 10% 미만이라 제외.","src":"공정거래법 제6조 | 기출 2026-6"},{"t":"계산 예: A 35%(70억원), B 25%(50억원), C 15%(30억원), D 10%(20억원), E 5%, D가 A의 계열회사이면 A·D는 한 사업자(45%, 90억원). 상위 셋 합계 85%로 요건을 충족하고 연매출 요건(2022 기출 당시 40억원)에서 C(30억원)가 빠져 추정되는 자는 A, B, D. 현행 80억원 기준이면 B도 빠진다.","src":"공정거래법 제6조 | 기출 2022-5"},{"t":"점유율 30%인 1위가 가격을 올린 경우에도 다른 상위 사업자와 합쳐 셋 이하 합계 75% 이상이면 추정될 수 있다. 40%여도 합계 요건에 못 미치면 추정되지 않을 수 있다.","src":"공정거래법 제6조 | 기출 2025-6"},{"t":"점유율 10%인 사업자는 50%, 20%인 사업자와 함께 추정된다(합계 80%).","src":"공정거래법 제6조 | 기출 2025-6"}]},{"머리":"남용행위 유형 개관(제5조 제1항)","줄":[{"t":"남용행위 5개 유형: 가격의 부당한 결정·유지·변경, 상품 판매·용역 제공의 부당한 조절, 다른 사업자의 사업활동 부당 방해, 새로운 경쟁사업자의 참가 부당 방해, 부당한 경쟁사업자 배제 거래 또는 소비자 이익을 현저히 해칠 우려가 있는 행위.","src":"공정거래법 제5조 제1항 | 기출 2022-4 | 기출 2023-2"},{"t":"거래지역 또는 거래상대방의 제한은 남용행위가 아니라 불공정거래행위(구속조건부거래)다.","src":"공정거래법 시행령 별표 2 | 기출 2022-4"},{"t":"용역의 제공을 부당하게 조절하는 행위도 남용행위다. 영업의 주요 부문 공동 수행(공동행위)과 거래상대방 사업활동의 부당 구속 거래(불공정거래행위)는 남용행위가 아니다.","src":"공정거래법 제5조 제1항 제2호 | 기출 2023-2"},{"t":"남용행위의 유형 및 기준은 대통령령으로 정한다.","src":"공정거래법 제5조 제2항"}]},{"머리":"가격 남용·출고조절(시행령 제9조 제1항·제2항)","줄":[{"t":"가격 남용: 정당한 이유 없이 가격을 수급 변동이나 공급 비용(같은 종류 또는 유사 업종의 통상 수준) 변동에 비해 현저하게 상승시키거나 근소하게 하락시키는 행위.","src":"공정거래법 시행령 제9조 제1항"},{"t":"부당한 출고조절 1: 정당한 이유 없이 최근의 추세에 비추어 상품·용역의 공급량을 현저히 감소시키는 행위.","src":"공정거래법 시행령 제9조 제2항 제1호 | 기출 2024-6 | 기출 2025-4"},{"t":"부당한 출고조절 2: 정당한 이유 없이 유통단계에서 공급부족이 있음에도 공급량을 감소시키는 행위.","src":"공정거래법 시행령 제9조 제2항 제2호 | 기출 2025-4"},{"t":"출고조절의 부당성은 통상 수준을 현저히 벗어나 가격의 인상·하락 방지에 중대한 영향을 미치거나 수급차질을 초래할 우려가 있는지로 판단한다.","src":"기출 2021-4"}]},{"머리":"사업활동 방해(시행령 제9조 제3항)","줄":[{"t":"사업활동 방해 1: 정당한 이유 없이 다른 사업자의 생산활동에 필요한 원재료 구매를 방해하는 행위.","src":"공정거래법 시행령 제9조 제3항 제1호 | 기출 2024-6 | 기출 2026-5"},{"t":"사업활동 방해 2: 정상적인 관행에 비추어 과도한 경제상 이익을 제공하거나 약속하면서 다른 사업자의 사업활동에 필수적인 인력을 채용하는 행위. 정상적인 관행에 따른 채용은 금지되지 않는다.","src":"공정거래법 시행령 제9조 제3항 제2호 | 기출 2021-4 | 기출 2026-5"},{"t":"사업활동 방해 3: 정당한 이유 없이 다른 사업자의 상품·용역의 생산·공급·판매에 필수적인 요소의 사용 또는 접근을 거절·중단하거나 제한하는 행위.","src":"공정거래법 시행령 제9조 제3항 제3호"},{"t":"사업활동 방해 4: 위 방법 외의 부당한 방법으로 다른 사업자의 사업활동을 어렵게 하는 행위 중 공정거래위원회가 고시하는 행위.","src":"공정거래법 시행령 제9조 제3항 제4호"},{"t":"'다른 사업자'에는 시장지배적사업자의 경쟁사업자뿐 아니라 거래상대방, 판매대리점 등 전·후방관계 사업자도 포함된다.","src":"기출 2021-4 | 기출 2023-4"}]},{"머리":"새로운 경쟁사업자의 참가 방해(시행령 제9조 제4항)","줄":[{"t":"참가 방해 1: 정당한 이유 없이 거래하는 유통사업자와 배타적 거래계약을 체결하는 행위.","src":"공정거래법 시행령 제9조 제4항 제1호 | 기출 2024-6"},{"t":"참가 방해 2: 정당한 이유 없이 기존 사업자의 계속적인 사업활동에 필요한 권리 등을 매입하는 행위.","src":"공정거래법 시행령 제9조 제4항 제2호 | 기출 2024-6 | 기출 2026-5"},{"t":"참가 방해 3: 정당한 이유 없이 새로운 경쟁사업자의 상품·용역의 생산·공급·판매에 필수적인 요소의 사용 또는 접근을 거절하거나 제한하는 행위.","src":"공정거래법 시행령 제9조 제4항 제3호 | 기출 2024-6"},{"t":"참가 방해 4: 위 방법 외의 부당한 방법으로 신규진입을 어렵게 하는 행위 중 고시하는 행위.","src":"공정거래법 시행령 제9조 제4항 제4호"},{"t":"원재료 구매 방해와 인력 채용, 필수요소 접근 거절(기존 사업자 대상)은 사업활동 방해다. 새로운 경쟁사업자에 대한 필수요소 접근 거절만 참가 방해에 해당한다.","src":"공정거래법 시행령 제9조 제3항·제4항 | 기출 2026-5"}]},{"머리":"경쟁사업자 배제(시행령 제9조 제5항)","줄":[{"t":"경쟁사업자 배제 1: 부당하게 통상거래가격에 비해 낮은 가격으로 공급하거나 높은 가격으로 구입하여 경쟁사업자를 배제시킬 우려가 있는 행위.","src":"공정거래법 시행령 제9조 제5항 제1호"},{"t":"경쟁사업자 배제 2: 부당하게 거래상대방이 경쟁사업자와 거래하지 않을 것을 조건으로 그 거래상대방과 거래하는 행위.","src":"공정거래법 시행령 제9조 제5항 제2호 | 기출 2025-4"},{"t":"세부 유형 및 기준은 공정거래위원회가 고시한다.","src":"공정거래법 시행령 제9조 제6항"}]},{"머리":"시정조치(제7조)","줄":[{"t":"공정거래위원회가 시장지배적사업자에게 명할 수 있는 시정조치: 가격의 인하, 해당 행위의 중지, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치.","src":"공정거래법 제7조 제1항 | 기출 2021-3 | 기출 2022-6 | 기출 2023-3 | 기출 2025-7"},{"t":"가격의 인하는 시장지배적지위 남용에서만 명시된 시정조치다.","src":"공정거래법 제7조 제1항 | 기출 2023-3"},{"t":"규정에 없는 것: 주식의 처분·소각, 계약조항의 삭제, 법위반사실의 공표(조문은 시정명령을 받은 사실의 공표), 사죄광고, 이행강제금 부과, 다른 회사와의 합병, 경쟁촉진 방안 마련.","src":"공정거래법 제7조 제1항 | 기출 2021-3 | 기출 2022-6 | 기출 2023-3 | 기출 2025-7"},{"t":"남용행위를 한 회사가 합병으로 소멸한 경우 합병 후 존속하거나 합병으로 설립된 회사의 행위로 보아 시정조치를 명할 수 있다.","src":"공정거래법 제7조 제2항"},{"t":"분할·분할합병된 경우 분할일(분할합병일) 이전의 남용행위를 분할되는 회사, 분할로 설립되는 새로운 회사, 분할되는 회사의 일부를 합병하여 존속하는 다른 회사 중 어느 하나의 행위로 보고 시정조치를 명할 수 있다.","src":"공정거래법 제7조 제3항"},{"t":"채무자회생법 제215조에 따라 새로운 회사를 설립하는 경우 기존 회사 또는 새로운 회사 중 어느 하나의 행위로 보고 시정조치를 명할 수 있다.","src":"공정거래법 제7조 제4항"}]},{"머리":"과징금·벌칙·고발","줄":[{"t":"남용행위 과징금: 대통령령으로 정하는 매출액(관련매출액)에 100분의 6을 곱한 금액을 초과하지 않는 범위. 매출액이 없거나 산정이 곤란하면 20억원을 초과하지 않는 범위.","src":"공정거래법 제8조"},{"t":"관련매출액: 위반사업자가 위반기간 동안 일정한 거래분야에서 판매한 관련 상품·용역의 매출액 또는 이에 준하는 금액. 구매 관련 위반이면 매입액을 관련매출액으로 본다.","src":"공정거래법 시행령 제13조 제1항"},{"t":"매출액이 없는 경우 등: 영업을 개시하지 않았거나 영업중단 등으로 영업실적이 없는 경우, 재해 등으로 매출액 산정자료가 소멸·훼손된 경우, 위반기간 또는 관련 상품·용역의 범위를 확정할 수 없는 경우.","src":"공정거래법 시행령 제13조 제3항"},{"t":"남용행위를 한 자: 3년 이하의 징역 또는 2억원 이하의 벌금. 징역형과 벌금형을 병과할 수 있다.","src":"공정거래법 제124조 제1항 제1호·제2항"},{"t":"남용행위 위반은 공정거래위원회의 고발이 있어야 공소를 제기할 수 있다.","src":"공정거래법 제129조 제1항 | 기출 2021-26 | 기출 2024-30"},{"t":"위반의 정도가 객관적으로 명백하고 중대하여 경쟁질서를 현저히 해친다고 인정하면 공정거래위원회는 고발하여야 한다(현행 고발 상대방은 중대범죄수사청장, 기출 당시 검찰총장).","src":"공정거래법 제129조 제2항 | 기출 2021-26 | 기출 2024-30"}]}],"함정":[{"x":"다른 사업자의 사업활동을 부당하게 방해하는 행위의 경우 ‘다른 사업자’란 당해 시장 지배적 사업자와 경쟁관계에 있는 사업자를 말하며, 판매대리점 등 전ㆍ후방관계에 있는 사업자는 제외된다.","o":"'다른 사업자'에는 경쟁관계 사업자뿐 아니라 거래상대방, 판매대리점 등 전·후방관계 사업자도 포함된다.","src":"기출 2021-4"},{"x":"관련시장이 넓게 획정될수록 사업자가 그 시장에서 시장지배적지위를 가질 가능성은 높아진다.","o":"관련시장이 넓게 획정될수록 점유율이 낮아져 시장지배적지위를 가질 가능성은 낮아진다.","src":"기출 2021-5"},{"x":"다른 사업자의 사업활동을 부당하게 방해하는 행위에서 다른 사업자란 시장지배적 사업자의 전ㆍ후방관계에 있는 사업자는 포함되지 않는다.","o":"전·후방관계 사업자도 '다른 사업자'에 포함된다.","src":"기출 2021-4 | 기출 2023-4"},{"x":"공급자만이 시장지배적사업자가 될 수 있다.","o":"공급자뿐 아니라 수요자도 시장지배적사업자가 될 수 있다.","src":"공정거래법 제2조 제3호 | 기출 2024-4"},{"x":"시장지배적사업자를 판단할 때 진입장벽의 존재는 고려하지 아니한다.","o":"진입장벽의 존재 및 정도를 고려한다.","src":"공정거래법 제2조 제3호 | 기출 2024-4"},{"x":"상품이 아닌 용역의 가격을 결정할 수 있는 시장지위를 가진 사업자는 시장지배적사 업자가 될 수 없다.","o":"용역의 가격을 결정할 수 있는 시장지위를 가진 사업자도 시장지배적사업자가 될 수 있다.","src":"공정거래법 제2조 제3호 | 기출 2024-4"},{"x":"상품의 품질을 결정할 수 있는 시장지위를 가진 사업자는 시장지배적사업자가 될 수 없다.","o":"품질을 결정할 수 있는 시장지위를 가진 사업자도 시장지배적사업자가 될 수 있다.","src":"공정거래법 제2조 제3호 | 기출 2024-4"},{"x":"일정한 거래분야에서 하나의 사업자의 시장점유율이 100분의 30 이상인 경우 시장지 배적사업자로 추정된다.","o":"하나의 사업자의 시장점유율이 100분의 50 이상이어야 추정된다.","src":"공정거래법 제6조 제1호 | 기출 2024-5"},{"x":"시장점유율은 법위반 혐의가 있는 행위의 종료일이 속하는 사업연도의 직전 3년 동안에 국내에서 공급되거나 구매된 상품이나 용역의 금액 중 해당 사업자가 같은 기간 동안 국내에서 공급하거나 구매한 상품이나 용역의 금액의 비율로 한다.","o":"행위 종료일이 속하는 사업연도의 직전 1년 동안의 금액 비율이다.","src":"공정거래법 시행령 제2조 제1항 | 기출 2024-5"},{"x":"시장점유율을 금액기준으로 산정하기 어려운 경우라도, 물량기준 또는 생산능력기준 으로는 산정할 수 없다.","o":"금액기준으로 산정하기 어려우면 물량기준 또는 생산능력기준으로 산정할 수 있다.","src":"공정거래법 시행령 제2조 제1항 | 기출 2024-5"},{"x":"일정한 거래분야에서 연간 매출액 또는 구매액이 100억원 미만인 사업자는 시장지배 적사업자에서 제외된다.","o":"연간 매출액 또는 구매액이 80억원 미만인 사업자가 추정에서 제외된다.","src":"공정거래법 제6조 | 기출 2024-5"},{"x":"일정한 거래분야에서 연간 매출액 또는 구매액이 50억원인 사업자도 시장지배적사업 자로 추정될 수 있다.","o":"연간 매출액·구매액 80억원 미만 사업자는 추정에서 제외되므로 50억원 사업자는 추정될 수 없다.","src":"공정거래법 제6조 | 기출 2025-6"}]},"경제력집중의 억제(특수관계인에 대한 부당한 이익제공 등)":{"묶음":[{"머리":"특수관계인에 대한 부당한 이익제공 금지(제47조 제1항)","줄":[{"t":"금지 주체: 동일인이 자연인인 공시대상기업집단에 속하는 국내 회사.","src":"공정거래법 제47조 제1항 | 기출 2026-16"},{"t":"규제 대상 거래상대방 1: 특수관계인(동일인 및 그 친족으로 한정).","src":"공정거래법 제47조 제1항 | 기출 2026-16"},{"t":"규제 대상 거래상대방 2: 동일인이 단독으로 또는 다른 특수관계인과 합하여 발행주식총수의 100분의 20 이상을 소유한 국내 계열회사.","src":"공정거래법 제47조 제1항 | 기출 2026-16"},{"t":"규제 대상 거래상대방 3: 위 계열회사가 단독으로 발행주식총수의 100분의 50을 초과하여 소유한 국내 계열회사.","src":"공정거래법 제47조 제1항 | 기출 2026-16"},{"t":"제1호: 정상적인 거래에서 적용되거나 적용될 것으로 판단되는 조건보다 상당히 유리한 조건으로 거래하는 행위.","src":"공정거래법 제47조 제1항 제1호 | 기출 2023-12 | 기출 2025-17"},{"t":"제2호: 회사가 직접 또는 자신이 지배하는 회사를 통해 수행하면 회사에 상당한 이익이 될 사업기회를 제공하는 행위.","src":"공정거래법 제47조 제1항 제2호 | 기출 2023-12 | 기출 2025-17"},{"t":"제3호: 특수관계인과 현금이나 그 밖의 금융상품을 상당히 유리한 조건으로 거래하는 행위.","src":"공정거래법 제47조 제1항 제3호 | 기출 2023-12 | 기출 2025-17"},{"t":"제4호: 사업능력, 재무상태, 신용도, 기술력, 품질, 가격 또는 거래조건 등에 대한 합리적 고려나 다른 사업자와의 비교 없이 상당한 규모로 거래하는 행위.","src":"공정거래법 제47조 제1항 제4호 | 기출 2023-12 | 기출 2025-17"},{"t":"거래 또는 사업기회 제공의 상대방은 제1항 각 호에 해당할 우려가 있음에도 해당 거래를 하거나 사업기회를 제공받아서는 안 된다.","src":"공정거래법 제47조 제3항"},{"t":"특수관계인은 누구에게든지 제1항·제3항 행위를 하도록 지시하거나 해당 행위에 관여해서는 안 된다.","src":"공정거래법 제47조 제4항"},{"t":"'거래상 실질적 역할이 없는 특수관계인을 매개로 한 거래'는 제47조가 아니라 불공정거래행위 중 부당한 지원행위(제45조 제1항 제9호 나목)다.","src":"공정거래법 제45조 제1항 제9호 | 기출 2023-12 | 기출 2025-17"}]},{"머리":"상당히 유리한 조건·상당한 규모의 기준(시행령 별표 3)","줄":[{"t":"제1호(유리한 조건 거래) 행위: 상당히 유리한 조건의 자금 거래, 자산·상품·용역 거래, 인력 거래.","src":"공정거래법 시행령 별표 3 제1호"},{"t":"제1호 예외: 정상 거래 조건과의 차이가 100분의 7 미만이고 거래당사자 간 해당 연도 거래총액이 50억원(상품·용역은 200억원) 미만이면 상당히 유리한 조건이 아니다.","src":"공정거래법 시행령 별표 3 제1호"},{"t":"제3호(현금·금융상품 거래) 예외: 정상 거래 조건과의 차이가 100분의 7 미만이고 해당 연도 거래총액이 50억원 미만이면 상당히 유리한 조건이 아니다.","src":"공정거래법 시행령 별표 3 제3호"},{"t":"제2호(사업기회 제공) 제외: 회사가 사업기회를 수행할 능력이 없는 경우, 정당한 대가를 지급받은 경우, 합리적 사유로 거부한 경우.","src":"공정거래법 시행령 별표 3 제2호"},{"t":"제4호(합리적 고려 없는 상당한 규모 거래) 예외: 해당 연도 거래총액이 200억원 미만이고 거래상대방 평균매출액의 100분의 12 미만이면 상당한 규모가 아니다.","src":"공정거래법 시행령 별표 3 제4호 | 기출 2024-11"},{"t":"제4호 거래총액은 둘 이상의 회사가 같은 거래상대방과 거래하면 각 회사 거래금액을 합산한다.","src":"공정거래법 시행령 별표 3 제4호"}]},{"머리":"상당한 규모 거래에서 제외되는 불가피한 거래(제47조 제2항, 시행령 별표 4)","줄":[{"t":"기업의 효율성 증대, 보안성, 긴급성 등 거래 목적을 달성하기 위해 불가피한 거래는 제47조 제1항 제4호를 적용하지 않는다. 불황극복 구조조정과 중소기업 경쟁력 향상은 이에 해당하지 않는다.","src":"공정거래법 제47조 제2항 | 기출 2026-17"},{"t":"효율성 증대 거래: 전후방 연관 계열회사 간 부품·소재 거래, 기획·생산·판매에 필수적인 서비스를 산업연관성 높은 계열회사에서 공급받는 거래, 일부 사업을 전문 계열회사가 전담하는 경우의 거래, 협업체계가 이미 구축된 거래, 전문 지식·인력·연속적 사업과의 밀접한 연관성·신뢰성을 고려한 계열회사 거래.","src":"공정거래법 시행령 별표 4 제1호"},{"t":"보안성 거래: 필수시설(전사적 자원관리시스템, 공장, 연구개발시설, 통신기반시설) 구축·운영·핵심기술 연구·개발·보유 관련, 영업·판매·구매 기밀이나 고객 개인정보 등 핵심 경영정보에 접근 가능한 경우로서 유출 시 회복하기 어려운 피해가 우려되는 거래.","src":"공정거래법 시행령 별표 4 제2호"},{"t":"긴급성 거래: 경기급변, 금융위기, 천재지변, 해킹·컴퓨터바이러스로 인한 전산시스템 장애 등 회사 외적 요인으로 인한 사업상 긴급한 필요에 따른 불가피한 거래.","src":"공정거래법 시행령 별표 4 제3호"}]},{"머리":"제재(과징금·벌칙·시정조치)","줄":[{"t":"과징금: 제47조 제1항·제3항 위반 시 해당 특수관계인 또는 회사에 평균매출액(직전 3개 사업연도 평균)에 100분의 10을 곱한 금액 이하. 매출액이 없는 경우 등은 40억원 이하.","src":"공정거래법 제50조 제2항 | 공정거래법 시행령 제56조 제2항"},{"t":"제47조 제1항·제4항을 위반한 자: 3년 이하의 징역 또는 2억원 이하의 벌금.","src":"공정거래법 제124조 제1항 제10호"},{"t":"시정조치: 특수관계인에 대한 부당한 이익제공행위의 중지 및 재발방지를 위한 조치, 계약조항의 삭제, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치. 제47조 위반은 해당 특수관계인 또는 회사에 명한다.","src":"공정거래법 제49조 제1항"},{"t":"부당한 지원행위(제45조 제1항 제9호)의 과징금도 매출액의 100분의 10, 매출액이 없으면 40억원이다. 사업활동 방해 등 다른 불공정거래행위는 100분의 4와 10억원이다.","src":"공정거래법 제50조 | 기출 2023-17 | 기출 2025-13 | 기출 2026-18"}]},{"머리":"경제력집중 억제 제도(제9조~제31조) 개관","줄":[{"t":"공시대상기업집단: 자산총액 5조원 이상인 기업집단으로 공정거래위원회가 지정.","src":"공정거래법 제31조 제1항"},{"t":"상호출자제한기업집단: 공시대상기업집단 중 자산총액이 국내총생산액의 1천분의 5 이상인 기업집단.","src":"공정거래법 제31조 제1항"},{"t":"공정거래위원회가 지정·통지한 날부터 제21조~제30조 및 제47조를 적용한다. 지정 당시 위반 중이면 상호출자·계열출자 위반은 1년, 채무보증은 2년간 적용하지 않는다.","src":"공정거래법 제31조 제2항·제3항"},{"t":"상호출자 금지: 상호출자제한기업집단 소속 국내 회사는 자기 주식을 취득·소유한 국내 계열회사의 주식을 취득·소유할 수 없다. 예외는 합병 또는 영업 전부의 양수, 담보권 실행 또는 대물변제 수령이며 6개월 이내에 처분하여야 한다.","src":"공정거래법 제21조 제1항·제2항"},{"t":"순환출자 금지: 상호출자제한기업집단 소속 국내 회사는 순환출자를 형성하는 계열출자를 할 수 없고, 기존 순환출자 관계 회사는 계열출자대상회사에 추가 계열출자를 할 수 없다.","src":"공정거래법 제22조 제1항"},{"t":"순환출자 예외 처분기간: 합병·분할·포괄적 교환·이전·영업 전부 양수와 담보권 실행·대물변제는 6개월, 신주배정 등으로 지분율 초과분 생긴 경우 1년, 기업구조조정 촉진법 관련은 3년.","src":"공정거래법 제22조 제2항"},{"t":"채무보증 금지: 상호출자제한기업집단 소속 국내 회사(금융업·보험업 회사 제외)는 채무보증을 할 수 없다. 예외는 조세특례제한법 합리화기준에 따라 인수되는 회사의 채무 관련, 국제경쟁력 강화 등 대통령령으로 정하는 경우.","src":"공정거래법 제24조"},{"t":"대규모내부거래: 공시대상기업집단 소속 국내 회사가 특수관계인(국외 계열회사 제외)을 상대방으로 하거나 위해 대통령령이 정하는 규모 이상의 자금·유가증권·자산 거래 등을 하려면 미리 이사회 의결을 거쳐 공시하여야 한다.","src":"공정거래법 제26조 제1항"},{"t":"기업결합 유형: 주식 취득·소유, 임원겸임, 합병, 영업양수, 새로운 회사설립 참여. 일정한 거래분야에서 경쟁을 실질적으로 제한하는 기업결합은 금지.","src":"공정거래법 제9조 제1항"},{"t":"기업결합 예외: 해당 기업결합 외의 방법으로는 달성하기 어려운 효율성 증대효과가 경쟁제한 폐해보다 큰 경우, 회생이 불가능한 회사와의 기업결합. 요건 충족의 입증은 해당 사업자가 한다.","src":"공정거래법 제9조 제2항"},{"t":"경쟁제한 추정: 당사회사 점유율 합계가 시장지배적사업자 추정요건에 해당하고, 1위이며, 2위와의 차이가 합계의 25% 이상. 또는 대규모회사가 중소기업 점유율 3분의 2 이상인 분야에서 5% 이상 점유하게 되는 경우.","src":"공정거래법 제9조 제3항"},{"t":"기업결합 신고는 기업결합일부터 30일 이내. 대규모회사가 당사회사인 일정 기업결합은 계약 체결일 등부터 기업결합일 전까지 신고하고 심사결과 통지 전에는 이행행위를 하지 못한다. 공정거래위원회는 신고일부터 30일 내 심사하며 90일 범위에서 연장할 수 있다.","src":"공정거래법 제11조 제6항~제8항"},{"t":"기업결합 신고 대상 주식 취득: 발행주식총수의 100분의 20(상장법인은 100분의 15) 이상 소유.","src":"공정거래법 제11조 제1항 제1호"},{"t":"기업결합 시정조치: 해당 행위의 중지, 주식 처분, 임원 사임, 영업 양도, 시정명령을 받은 사실의 공표, 영업방식·범위 제한, 그 밖에 필요한 조치.","src":"공정거래법 제14조 제1항"},{"t":"지주회사 행위제한: 자본총액의 2배 초과 부채 보유 금지, 자회사 주식 100분의 50 미만 소유 금지(상장·국외상장·공동출자법인은 30, 벤처지주회사의 자회사는 20), 계열회사 아닌 국내 회사 주식 5% 초과 소유 금지, 금융지주회사의 비금융 국내 회사 주식 소유 금지, 일반지주회사의 금융·보험 국내 회사 주식 소유 금지.","src":"공정거래법 제18조 제2항"},{"t":"지주회사 설립·전환 시 위 금지 행위에는 설립·전환일부터 2년의 유예기간이 있다.","src":"공정거래법 제18조 제2항 | 제6항"}]}],"함정":[]},"부당한 공동행위의 제한":{"묶음":[{"머리":"금지되는 공동행위와 유형(제40조 제1항)","줄":[{"t":"금지: 사업자가 계약·협정·결의 또는 그 밖의 어떠한 방법으로도 다른 사업자와 공동으로 부당하게 경쟁을 제한하는 행위를 할 것을 합의하는 것, 또는 다른 사업자로 하여금 이를 하도록 하는 것.","src":"공정거래법 제40조 제1항 | 기출 2021-7 | 기출 2026-9"},{"t":"제1호: 가격을 결정·유지 또는 변경하는 행위.","src":"공정거래법 제40조 제1항 제1호 | 기출 2023-8 | 기출 2026-8"},{"t":"제2호: 상품·용역의 거래조건이나 그 대금 또는 대가의 지급조건을 정하는 행위.","src":"공정거래법 제40조 제1항 제2호 | 기출 2022-9 | 기출 2023-8 | 기출 2025-9 | 기출 2026-8"},{"t":"제3호: 상품의 생산·출고·수송 또는 거래의 제한이나 용역의 거래를 제한하는 행위.","src":"공정거래법 제40조 제1항 제3호 | 기출 2022-9 | 기출 2023-8 | 기출 2025-9"},{"t":"제4호: 거래지역 또는 거래상대방을 제한하는 행위.","src":"공정거래법 제40조 제1항 제4호 | 기출 2021-8 | 기출 2023-8 | 기출 2025-9 | 기출 2026-8"},{"t":"제5호: 생산 또는 용역의 거래를 위한 설비의 신설·증설이나 장비의 도입을 방해하거나 제한하는 행위.","src":"공정거래법 제40조 제1항 제5호 | 기출 2026-8"},{"t":"제6호: 상품·용역의 생산·거래 시 종류·규격을 제한하는 행위.","src":"공정거래법 제40조 제1항 제6호 | 기출 2024-21 | 기출 2025-9"},{"t":"제7호: 영업의 주요 부문을 공동으로 수행·관리하거나 이를 위한 회사 등을 설립하는 행위.","src":"공정거래법 제40조 제1항 제7호 | 기출 2021-8 | 기출 2022-9 | 기출 2024-21"},{"t":"제8호(입찰담합): 입찰 또는 경매에서 낙찰자, 경락자, 입찰가격, 낙찰가격 또는 경락가격, 그 밖에 대통령령으로 정하는 사항을 결정하는 행위. 대통령령 사항은 낙찰·경락 비율, 설계·시공 방법, 그 밖에 입찰·경매의 경쟁 요소.","src":"공정거래법 제40조 제1항 제8호 | 공정거래법 시행령 제44조 제1항 | 기출 2021-8 | 기출 2024-21 | 기출 2025-8"},{"t":"제9호: 그 밖의 행위로서 다른 사업자(행위자 포함)의 사업활동 또는 사업내용을 방해·제한하거나, 가격·생산량 등 대통령령으로 정하는 정보를 주고받아 일정한 거래분야에서 경쟁을 실질적으로 제한하는 행위.","src":"공정거래법 제40조 제1항 제9호"},{"t":"제9호 대통령령 정보: 원가, 출고량·재고량·판매량, 거래조건 또는 대금·대가의 지급조건. 용역의 시공 방법은 정보에 해당하지 않는다.","src":"공정거래법 시행령 제44조 제2항 | 기출 2024-19"},{"t":"공동행위 유형이 아닌 것: 과대한 이익 제공으로 경쟁사업자 고객을 유인하는 행위, 거래상 지위를 부당하게 이용한 거래, 거래상대방 사업활동을 부당하게 구속하는 조건 거래(불공정거래행위 유형), 경쟁사업자의 고객을 유인하는 행위.","src":"공정거래법 제40조 제1항 | 기출 2021-8 | 기출 2022-9 | 기출 2023-8 | 기출 2024-21 | 기출 2025-9 | 기출 2026-8"}]},{"머리":"합의의 성립(판례·기출)","줄":[{"t":"합의에는 명시적 합의뿐 아니라 암묵의 요해(묵시적 합의)도 포함된다.","src":"기출 2023-10 | 기출 2024-22"},{"t":"합의는 공급자 사이, 수요자 사이, 공급자와 수요자 사이에서도 성립할 수 있다.","src":"기출 2023-6"},{"t":"합의는 해당 거래분야나 특정 입찰의 모든 사업자 사이에서 이루어질 필요가 없다.","src":"기출 2023-6"},{"t":"합의만으로 성립한다. 합의에 따른 행위의 일치(실행)는 요건이 아니다.","src":"기출 2021-7 | 기출 2023-6 | 기출 2025-8"},{"t":"어느 한 사업자가 진의 아닌 의사표시로 합의한 경우에도 공동행위는 성립한다.","src":"기출 2021-7 | 기출 2023-6 | 기출 2025-8"},{"t":"입찰에서 들러리를 서주는 등 입찰행위 실행에 묵시적으로 동의한 경우에도 공동행위가 성립한다.","src":"기출 2022-7"},{"t":"수 차례의 합의가 1개의 공동행위가 되기 위해 위반기간 전체에 걸쳐 합의 당사자가 동일할 필요는 없다.","src":"기출 2022-7"},{"t":"담합 참가 회사들이 순차적으로 합의 파기 의사를 대외적으로 표시하고 탈퇴해 1개 회사만 남으면 담합은 종료된다.","src":"기출 2024-22"},{"t":"'다른 사업자로 하여금 부당한 공동행위를 하도록 하는 행위'는 금지된다. 다른 사업자의 공동행위를 단순히 방조하는 행위는 여기에 포함되지 않는다.","src":"공정거래법 제40조 제1항 | 기출 2021-7 | 기출 2023-10 | 기출 2024-22 | 기출 2025-8"},{"t":"과점시장에서 선발업체가 독자적으로 가격을 정하고 후발업체가 일방적으로 모방하는 경우가 언제나 가격담합인 것은 아니다.","src":"기출 2024-22"},{"t":"과징금 산정 기준 매출액의 관련 상품·용역 범위는 합의 내용에 포함된 상품·용역의 종류와 성질, 거래지역, 거래상대방, 거래단계 등을 고려하여 개별적·구체적으로 판단한다.","src":"기출 2024-22"},{"t":"가격을 '유지'하는 합의도 가격을 결정·유지·변경하는 행위(제1호)에 해당한다.","src":"공정거래법 제40조 제1항 제1호 | 기출 2022-7"}]},{"머리":"합의 추정·무효·심사기준(제40조 제4항~제6항)","줄":[{"t":"부당한 공동행위를 할 것을 약정하는 계약 등은 해당 사업자 간에는 무효다.","src":"공정거래법 제40조 제4항 | 기출 2022-7 | 기출 2023-6 | 기출 2024-17 | 기출 2025-10 | 기출 2026-9"},{"t":"합의 추정 요건 1: 해당 거래분야, 상품·용역의 특성, 행위의 경제적 이유와 파급효과, 사업자 간 접촉의 횟수·양태 등을 보아 사업자들이 공동으로 한 것으로 볼 수 있는 상당한 개연성이 있는 때.","src":"공정거래법 제40조 제5항 제1호 | 기출 2021-7"},{"t":"합의 추정 요건 2: 제1항 각 호의 행위(제9호 중 정보교환으로 경쟁을 실질적으로 제한하는 행위는 제외)에 필요한 정보를 주고받은 때.","src":"공정거래법 제40조 제5항 제2호 | 기출 2026-9"},{"t":"입찰가격 결정에 필요한 정보를 주고받은 둘 이상의 사업자는 입찰담합을 합의한 것으로 추정한다.","src":"공정거래법 제40조 제5항 제2호 | 기출 2026-9"},{"t":"부당한 공동행위에 관한 심사의 기준은 공정거래위원회가 정하여 고시한다.","src":"공정거래법 제40조 제6항 | 기출 2024-17"}]},{"머리":"인가 사유·요건(제40조 제2항, 시행령 제45조)","줄":[{"t":"인가를 받으면 제1항이 적용되지 않는 목적 4가지: 불황극복을 위한 산업구조조정, 연구·기술개발, 거래조건의 합리화, 중소기업의 경쟁력향상.","src":"공정거래법 제40조 제2항 | 기출 2021-10 | 기출 2023-9 | 기출 2024-20 | 기출 2026-7"},{"t":"인가 목적이 아닌 것: 수익의 극대화, 기업지배구조의 조정·합리화, 대기업의 경쟁력 향상, 첨단산업 육성을 위한 산업구조조정.","src":"공정거래법 제40조 제2항 | 기출 2021-10 | 기출 2023-9 | 기출 2024-20 | 기출 2026-7"},{"t":"산업구조조정 요건(모두): 해당 산업 내 상당수 기업이 불황으로 사업활동에 곤란을 겪을 우려, 공급능력 현저 과잉 또는 생산시설·방법 낙후로 생산능률·국제경쟁력 현저 저하, 기업 합리화로는 극복 불가, 경쟁제한 효과보다 구조조정 효과가 클 것.","src":"공정거래법 시행령 제45조 제1항 제1호"},{"t":"연구·기술개발 요건(모두): 산업경쟁력 강화에 매우 필요하고 경제적 파급효과가 클 것, 투자금액이 과다하여 한 사업자가 조달하기 어려울 것, 성과의 불확실에 따른 위험분산에 필요할 것, 경쟁제한 효과보다 연구·기술개발 효과가 클 것.","src":"공정거래법 시행령 제45조 제1항 제2호 | 기출 2022-8"},{"t":"연구·기술개발 요건에 '소비자의 편익증진에 명백하게 기여할 것'은 없다. 그 표현은 거래조건 합리화 요건이다.","src":"공정거래법 시행령 제45조 제1항 제2호·제3호 | 기출 2022-8"},{"t":"거래조건 합리화 요건(모두): 생산능률 향상·거래 원활화·소비자 편익증진에 명백히 기여할 것, 합리화 내용이 해당 분야 대부분 사업자에게 기술적·경제적으로 가능할 것, 경쟁제한 효과보다 합리화 효과가 클 것.","src":"공정거래법 시행령 제45조 제1항 제3호"},{"t":"중소기업 경쟁력향상 요건(모두): 품질·기술향상 등 생산성 향상이나 교섭력 강화가 명백할 것, 참가사업자 모두가 중소기업자일 것, 공동행위 외의 방법으로는 대기업과 효율적으로 경쟁하거나 대항하기 어려울 것.","src":"공정거래법 시행령 제45조 제1항 제4호"},{"t":"인가 불가: 목적 달성에 필요한 정도를 초과하는 경우, 수요자·관련 사업자의 이익을 부당하게 침해할 우려가 있는 경우, 참가사업자 간 내용에 부당한 차별이 있는 경우, 참가·탈퇴를 부당하게 제한하는 경우.","src":"공정거래법 시행령 제45조 제2항"},{"t":"인가 신청: 공동행위대표사업자를 선정해 신청서 제출. 공정거래위원회는 신청일부터 30일(공시기간 제외) 이내 결정하며 30일 이내 연장 가능. 이해관계인 의견 청취를 위해 30일 이내 공시할 수 있다. 인가하면 인가증을 발급한다.","src":"공정거래법 시행령 제46조"},{"t":"인가된 공동행위가 폐지되면 공동행위대표사업자가 지체 없이 공정거래위원회에 알려야 한다.","src":"공정거래법 시행령 제47조 | 기출 2024-17"},{"t":"신청서 첨부서류: 요건 적합 증명서류, 불가 사유 비해당 증명서류, 참가사업자 최근 2년간 영업보고서·대차대조표·손익계산서, 공동행위 협정 또는 결의서 사본, 고시하는 서류.","src":"공정거래법 시행령 제46조 제2항"},{"t":"사업자단체도 같은 인가 요건에 해당하면 공정거래위원회 인가를 얻어 공동행위를 할 수 있다.","src":"공정거래법 제51조 제2항 | 기출 2022-20"}]},{"머리":"시정조치·과징금·형사(제42조·제43조·제124조)","줄":[{"t":"시정조치: 해당 행위의 중지, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치. 합병·분할 등 승계는 제7조 제2항~제4항 준용.","src":"공정거래법 제42조 | 기출 2022-10 | 기출 2024-18 | 기출 2025-10"},{"t":"과징금: 대통령령으로 정하는 매출액에 100분의 20을 곱한 금액 이하. 매출액이 없는 경우 등은 40억원 이하.","src":"공정거래법 제43조 | 기출 2022-10 | 기출 2023-10 | 기출 2024-18 | 기출 2026-9"},{"t":"입찰담합 및 이와 유사한 행위의 매출액은 계약금액을 매출액으로 본다.","src":"공정거래법 시행령 제50조"},{"t":"부당한 공동행위를 한 자 또는 하도록 한 자: 3년 이하의 징역 또는 2억원 이하의 벌금. 징역형과 벌금형을 병과할 수 있다.","src":"공정거래법 제124조 제1항 제9호·제2항 | 기출 2022-7 | 기출 2025-8"},{"t":"공정거래위원회 고발 없이는 공소 제기 불가. 부당한 공동행위는 동의의결 대상에서 제외되어 심의 절차를 진행한다.","src":"공정거래법 제129조 제1항·제89조 제1항 제1호 | 기출 2024-26"},{"t":"손해배상: 부당한 공동행위로 손해를 입은 자에게 손해의 3배를 넘지 않는 범위에서 책임. 고의·과실 없음을 입증하면 면책.","src":"공정거래법 제109조 제2항 | 기출 2024-29"},{"t":"부당한 공동행위에서 시정조치 소멸시효: 조사를 개시한 경우 조사 개시일부터 5년, 조사를 개시하지 않은 경우 위반행위 종료일부터 7년이 지나면 시정조치·과징금을 부과할 수 없다.","src":"공정거래법 제80조 제5항 | 기출 2021-23 | 기출 2022-26 | 기출 2023-28"},{"t":"공공부문 입찰: 공정거래위원회는 국가·지방자치단체·공공기관·지방공기업이 발주하는 입찰의 부당한 공동행위를 적발·방지하려고 중앙행정기관·지방자치단체·공공기관·지방공기업의 장에게 입찰 관련 자료의 제출과 협조를 요청할 수 있다. 대통령령으로 정하는 공공기관의 장은 입찰공고나 낙찰자 결정 시 입찰 관련 정보를 공정거래위원회에 제출하여야 한다.","src":"공정거래법 제41조 | 기출 2023-10 | 기출 2024-17"}]},{"머리":"자진신고자 등 감면(제44조, 시행령 제51조)","줄":[{"t":"감면 대상: 부당한 공동행위를 자진신고한 자, 증거제공 등으로 조사·심의·의결에 협조한 자(소속 전·현직 임직원 포함).","src":"공정거래법 제44조 제1항 | 기출 2021-9"},{"t":"감면 내용: 시정조치 또는 과징금의 감경·면제 가능, 고발 면제 가능. 고발 면제도 가능하다.","src":"공정거래법 제44조 제1항 | 기출 2021-9 | 기출 2023-10 | 기출 2024-17"},{"t":"과징금·시정조치 전부 면제(조사 개시 전 자진신고): 단독으로 증거를 제공한 최초의 자일 것, 공정거래위원회가 정보를 입수하지 못했거나 충분한 증거를 확보하지 못한 상태일 것, 사실을 모두 진술하고 끝까지 협조할 것, 부당한 공동행위를 중단할 것.","src":"공정거래법 시행령 제51조 제1항 제1호 | 기출 2026-4"},{"t":"조사 개시 후 협조: 과징금 면제, 시정조치 감경 또는 면제(최초 협조자 요건 동일).","src":"공정거래법 시행령 제51조 제1항 제2호 | 기출 2026-4"},{"t":"두 번째 자진신고자·협조자: 과징금 100분의 50 감경, 시정조치 감경 가능. 면제가 아니다. 사업자가 2개뿐이고 그중 하나인 경우는 제외. 최초 자진신고자 협조일부터 2년 이내여야 한다.","src":"공정거래법 시행령 제51조 제1항 제3호 | 기출 2022-10"},{"t":"감면 불가: 다른 사업자에게 의사에 반해 참여하도록 강요하거나 중단하지 못하도록 강요한 경우, 일정 기간 반복적으로 부당한 공동행위를 한 경우.","src":"공정거래법 시행령 제51조 제2항 | 기출 2026-4"},{"t":"감면받은 날부터 5년 이내에 다시 제40조 제1항을 위반하면 감경·면제를 하지 않는다.","src":"공정거래법 제44조 제2항 | 기출 2026-4"},{"t":"감면 취소: 재판에서 조사과정 진술이나 제출 자료의 중요한 내용을 부정하는 경우, 진술·자료가 재판에서 거짓으로 밝혀진 경우, 정당한 이유 없이 진술하지 않거나 출석하지 않는 경우, 자진신고 사실을 부인하는 소를 제기하는 경우.","src":"공정거래법 제44조 제3항 | 공정거래법 시행령 제51조 제3항 | 기출 2026-4"},{"t":"공정거래위원회와 소속 공무원은 사건처리에 필요한 경우 등 대통령령으로 정하는 경우를 제외하고 자진신고자 관련 정보를 사건 처리와 관계없는 자에게 제공·누설할 수 없다. 예외: 사건처리 필요, 자진신고자 동의, 소 제기·수행에 필요한 경우.","src":"공정거래법 제44조 제4항 | 공정거래법 시행령 제51조 제4항 | 기출 2021-9 | 기출 2026-4"},{"t":"자진신고자의 순서에 따라 감면 혜택에 차이가 있다.","src":"공정거래법 시행령 제51조 | 기출 2021-9"},{"t":"자진신고 관련 자료는 자료 열람·복사 요구 제외 대상이다.","src":"공정거래법 제95조 제2호"},{"t":"자진신고 감면 사업자(제44조 제1항 해당)의 손해배상액은 해당 사업자가 제40조 위반으로 손해를 입은 자에게 끼친 손해를 초과할 수 없고, 다른 사업자와 공동불법행위자로서 그 범위에서 책임을 진다.","src":"공정거래법 제109조 제2항 단서·제4항 | 기출 2024-29"}]}],"함정":[{"x":"사업자가 다른 사업자로 하여금 부당한 공동행위를 행하도록 하는 행위는 제19조 제1항에 위반되지 않는다.","o":"다른 사업자로 하여금 부당한 공동행위를 하도록 하는 행위도 금지 위반이다. (2021 기출 당시 제19조 제1항, 현행 제40조 제1항)","src":"공정거래법 제40조 제1항 | 기출 2021-7"},{"x":"사업자의 합의는 부당한 공동행위의 외형만 일치한다면 공동성에 대한 상당한 개연성이 없이도 추정된다.","o":"외형의 일치만으로 합의가 추정되지 않는다. 사업자들이 공동으로 한 것으로 볼 수 있는 상당한 개연성이 있어야 한다.","src":"공정거래법 제40조 제5항 제1호 | 기출 2021-7"},{"x":"다른 사업자의 부당한 공동행위를 단순히 방조하는 행위도 부당한 공동행위에 해당한다.","o":"단순 방조는 부당한 공동행위(다른 사업자로 하여금 하게 하는 행위)에 해당하지 않는다.","src":"기출 2023-10 | 기출 2024-22 | 기출 2021-7"},{"x":"공동행위가 성립하려면 사업자가 다른 사업자와 공동으로 일정한 행위를 하기로 합의 하고, 이를 실행하여야 한다.","o":"합의만으로 공동행위가 성립한다. 합의에 따른 실행은 요건이 아니다.","src":"기출 2023-6 | 기출 2025-8 | 기출 2021-7"},{"x":"증거제공 등의 방법으로 조사에 협조한 자에 대하여는 고발을 면제한다.","o":"고발을 면제할 수 있다(재량). 감경·면제 모두 가능하다.","src":"공정거래법 제44조 제1항 | 기출 2021-9"},{"x":"입찰에 참가하여 들러리를 서주는 등 입찰행위의 실행을 묵시적으로 동의한 경우에는 공동행위가 성립하지 아니한다.","o":"들러리를 서는 등 입찰행위 실행에 묵시적으로 동의한 경우에도 공동행위가 성립한다.","src":"기출 2022-7"},{"x":"수 차례의 합의가 1개의 부당한 공동행위가 되기 위해서는 위반행위 기간 전체에 걸쳐서 합의의 당사자가 동일하여야 한다.","o":"위반기간 전체에 걸쳐 합의 당사자가 동일할 필요는 없다.","src":"기출 2022-7"},{"x":"다른 사업자와 공동으로 부당하게 경쟁을 제한하기 위하여 가격을 유지하는 것은 부당한 공동행위에 해당하지 아니한다.","o":"가격을 유지하는 것도 부당한 공동행위(가격의 결정·유지·변경)에 해당한다.","src":"공정거래법 제40조 제1항 제1호 | 기출 2022-7"},{"x":"부당한 공동행위를 한 사업자에 대해서는 5년 이하의 징역 또는 3억원 이하의 벌금에 처한다.","o":"3년 이하의 징역 또는 2억원 이하의 벌금.","src":"공정거래법 제124조 제1항 제9호 | 기출 2022-7"},{"x":"부당한 공동행위의 사실을 두 번째로 자진신고하는 자에게는 과징금을 면제하여야 한다.","o":"두 번째 자진신고자는 과징금 100분의 50 감경 대상이며 면제 대상이 아니다.","src":"공정거래법 시행령 제51조 제1항 제3호 | 기출 2022-10"},{"x":"공동행위 참가자 중 일방의 진의 아닌 의사표시에 의하여 합의한 경우라면 다른 쪽의 사업자가 이를 진의로 신뢰하였더라도 부당한 공동행위는 성립하지 않는다.","o":"진의 아닌 의사표시로 합의한 경우에도 부당한 공동행위는 성립한다.","src":"기출 2021-7 | 기출 2025-8 | 기출 2023-6"},{"x":"부당한 공동행위를 할 것을 약정하는 계약 등은 해당 사업자 간에는 유효하다.","o":"해당 사업자 간에는 무효다.","src":"공정거래법 제40조 제4항 | 기출 2023-6"},{"x":"합의는 어떠한 거래분야나 특정한 입찰에 참여하는 모든 사업자들 사이에서 이루어져야 부당한 공동행위가 성립한다.","o":"모든 사업자 사이의 합의일 필요는 없다.","src":"기출 2023-6"},{"x":"합의는 그 합의에 따른 행위의 일치가 있어야만 부당한 공동행위가 성립한다.","o":"합의만으로 성립한다. 합의에 따른 행위의 일치는 요건이 아니다.","src":"기출 2023-6 | 기출 2025-8"},{"x":"B에게는 과징금을 부과할 수 없다.","o":"부당한 공동행위에 참가한 B에게도 과징금을 부과할 수 있다.","src":"공정거래법 제43조 | 기출 2024-18"},{"x":"공정거래위원회는 부당한 공동행위를 통하여 소비자에게 피해를 끼친 사업자에게 그 피해를 배상하도록 하는 내용의 동의의결을 할 수 있다.","o":"부당한 공동행위는 동의의결 대상이 아니며 심의 절차를 진행한다.","src":"공정거래법 제89조 제1항 제1호 | 기출 2025-10"},{"x":"부당한 공동행위임을 입증하는 증거를 단독으로 제공한 최초의 자가 아닌 경우에도 공정거래위원회가 부당한 공동행위에 대한 정보를 입수하지 못한 상태에서 조사등에 협조한 자에 대해서는 과징금 및 시정조치를 모두 면제한다.","o":"조사 개시 후 협조자는 최초 협조자 요건을 갖춘 경우에만 과징금 면제 대상이다.","src":"공정거래법 시행령 제51조 제1항 제2호 | 기출 2026-4"},{"x":"입찰에 참가하는 둘 이상의 사업자가 입찰가격 결정에 필요한 정보를 주고받더라도 이 법상 그 사업자들 사이에 공동으로 입찰담합 행위를 할 것을 합의한 것으로 추정 하지 아니한다.","o":"입찰가격 결정에 필요한 정보를 주고받은 사업자들은 합의한 것으로 추정한다.","src":"공정거래법 제40조 제5항 제2호 | 기출 2026-9"}]},"불공정거래행위의 금지":{"묶음":[{"머리":"불공정거래행위 10개 유형(제45조 제1항)","줄":[{"t":"제1호: 부당하게 거래를 거절하는 행위(거래거절).","src":"공정거래법 제45조 제1항 제1호"},{"t":"제2호: 부당하게 거래의 상대방을 차별하여 취급하는 행위(차별적 취급).","src":"공정거래법 제45조 제1항 제2호"},{"t":"제3호: 부당하게 경쟁자를 배제하는 행위(경쟁사업자 배제).","src":"공정거래법 제45조 제1항 제3호"},{"t":"제4호: 부당하게 경쟁자의 고객을 자기와 거래하도록 유인하는 행위(부당한 고객유인).","src":"공정거래법 제45조 제1항 제4호"},{"t":"제5호: 부당하게 경쟁자의 고객을 자기와 거래하도록 강제하는 행위(거래강제).","src":"공정거래법 제45조 제1항 제5호"},{"t":"제6호: 자기의 거래상의 지위를 부당하게 이용하여 상대방과 거래하는 행위(거래상 지위의 남용).","src":"공정거래법 제45조 제1항 제6호"},{"t":"제7호: 거래의 상대방의 사업활동을 부당하게 구속하는 조건으로 거래하는 행위(구속조건부거래).","src":"공정거래법 제45조 제1항 제7호"},{"t":"제8호: 부당하게 다른 사업자의 사업활동을 방해하는 행위(사업활동 방해).","src":"공정거래법 제45조 제1항 제8호"},{"t":"제9호: 부당하게 특수관계인 또는 다른 회사를 지원하는 행위(부당한 지원행위).","src":"공정거래법 제45조 제1항 제9호"},{"t":"제10호: 그 밖의 행위로서 공정한 거래를 해칠 우려가 있는 행위.","src":"공정거래법 제45조 제1항 제10호"},{"t":"사업자는 계열회사 또는 다른 사업자로 하여금 불공정거래행위를 하도록 해서도 안 된다.","src":"공정거래법 제45조 제1항"},{"t":"특수관계인 또는 회사는 제9호에 해당할 우려가 있음에도 해당 지원을 받는 행위를 해서는 안 된다.","src":"공정거래법 제45조 제2항"},{"t":"부당한 지원행위 수단: 가지급금·대여금·인력·부동산·유가증권·상품·용역·무체재산권 등을 제공하거나 상당히 유리한 조건으로 거래, 또는 거래상 실질적 역할이 없는 특수관계인·다른 회사를 매개로 거래.","src":"공정거래법 제45조 제1항 제9호"},{"t":"불공정거래행위가 되려면 공정한 거래를 해칠 우려가 있어야 한다.","src":"공정거래법 제45조 제1항"}]},{"머리":"제도 운영(제45조 제3항~제6항)","줄":[{"t":"불공정거래행위의 유형 또는 기준은 대통령령으로 정한다.","src":"공정거래법 제45조 제3항 | 기출 2022-17 | 기출 2024-12 | 기출 2026-14"},{"t":"공정거래위원회는 불공정거래행위를 예방하기 위해 필요하면 사업자가 준수하여야 할 지침을 제정·고시할 수 있다.","src":"공정거래법 제45조 제4항 | 기출 2022-17 | 기출 2024-12 | 기출 2026-14"},{"t":"사업자 또는 사업자단체는 부당한 고객유인을 방지하기 위하여 자율적으로 공정경쟁규약을 정할 수 있다. 공정경쟁규약으로 방지하려는 대상은 부당한 고객유인이다.","src":"공정거래법 제45조 제5항 | 기출 2022-17 | 기출 2023-11 | 기출 2025-12"},{"t":"공정경쟁규약이 제1항 제4호(부당한 고객유인)를 위반하는지 심사를 요청할 수 있다. 요청 의무는 없다.","src":"공정거래법 제45조 제6항 | 기출 2022-17 | 기출 2026-14"},{"t":"공정거래위원회는 심사 요청을 받은 날부터 60일 이내에 심사결과를 서면으로 요청인에게 통보하여야 한다. (90일이 아니다)","src":"공정거래법 시행령 제53조 | 기출 2022-17 | 기출 2024-12 | 기출 2026-14"}]},{"머리":"거래거절·차별적 취급(시행령 별표 2 제1호·제2호)","줄":[{"t":"거래거절 가: 공동의 거래거절. 정당한 이유 없이 경쟁관계에 있는 다른 사업자와 공동으로 특정사업자에게 거래개시를 거절하거나 계속적 거래관계에 있는 특정사업자에게 거래를 중단하거나 수량·내용을 현저히 제한.","src":"공정거래법 시행령 별표 2 제1호 가목 | 기출 2021-11 | 기출 2024-8"},{"t":"거래거절 나: 그 밖의 거래거절. 부당하게 특정사업자에게 거래개시를 거절하거나 계속적 거래관계에 있는 특정사업자에게 거래를 중단하거나 수량·내용을 현저히 제한.","src":"공정거래법 시행령 별표 2 제1호 나목 | 기출 2021-12"},{"t":"차별적 취급 가: 가격차별. 부당하게 거래지역 또는 거래상대방에 따라 현저하게 유리하거나 불리한 가격으로 거래.","src":"공정거래법 시행령 별표 2 제2호 가목 | 기출 2024-7"},{"t":"차별적 취급 나: 거래조건차별. 부당하게 특정사업자에게 수량·품질 등의 거래조건이나 거래내용을 현저하게 유리하거나 불리하게 취급.","src":"공정거래법 시행령 별표 2 제2호 나목 | 기출 2022-12 | 기출 2024-7"},{"t":"차별적 취급 다: 계열회사를 위한 차별. 정당한 이유 없이 자기 계열회사를 유리하게 하기 위해 가격·수량·품질 등 거래조건이나 거래내용을 현저하게 유리하거나 불리하게 하는 행위. 부당한 지원행위가 아니다.","src":"공정거래법 시행령 별표 2 제2호 다목 | 기출 2021-12 | 기출 2022-14 | 기출 2024-7"},{"t":"차별적 취급 라: 집단적 차별. 집단으로 특정사업자를 부당하게 차별적으로 취급하여 그 사업활동을 현저하게 유리하거나 불리하게 하는 행위.","src":"공정거래법 시행령 별표 2 제2호 라목 | 기출 2021-11 | 기출 2022-11 | 기출 2024-7"},{"t":"위계에 의한 차별은 차별적 취급 유형이 아니다(위계에 의한 고객유인은 부당한 고객유인).","src":"공정거래법 시행령 별표 2 | 기출 2024-7"}]},{"머리":"경쟁사업자 배제(시행령 별표 2 제3호)","줄":[{"t":"부당염매: 자기의 상품·용역을 공급하면서 정당한 이유 없이 공급에 소요되는 비용보다 현저히 낮은 가격으로 계속 공급하거나, 그 밖에 부당하게 낮은 가격으로 공급하여 자기 또는 계열회사의 경쟁사업자를 배제시킬 우려가 있는 행위.","src":"공정거래법 시행령 별표 2 제3호 가목 | 기출 2023-20 | 기출 2025-11"},{"t":"부당염매의 요건은 경쟁사업자를 배제시킬 '우려'다. 경쟁사업자가 실제로 배제되어야 하는 것은 아니다.","src":"공정거래법 시행령 별표 2 제3호 가목 | 기출 2023-20"},{"t":"부당고가매입: 부당하게 상품·용역을 통상거래가격보다 높은 가격으로 구입하여 자기 또는 계열회사의 경쟁사업자를 배제시킬 우려가 있는 행위.","src":"공정거래법 시행령 별표 2 제3호 나목 | 기출 2021-13 | 기출 2023-18"},{"t":"부당염매와 부당고가매입은 경쟁사업자 배제 유형이다. 부당한 거래단계 추가는 부당한 지원행위다.","src":"공정거래법 시행령 별표 2 | 기출 2021-13 | 기출 2022-14"}]},{"머리":"부당한 고객유인(시행령 별표 2 제4호)","줄":[{"t":"부당한 이익에 의한 고객유인: 정상적인 거래관행에 비추어 부당하거나 과대한 이익을 제공하거나 제공할 제의를 하여 경쟁사업자의 고객을 자기와 거래하도록 유인.","src":"공정거래법 시행령 별표 2 제4호 가목 | 기출 2021-8 | 기출 2025-12"},{"t":"위계에 의한 고객유인: 표시광고법상 부당한 표시·광고 외의 방법으로 자기 상품·용역의 내용이나 거래조건 등을 실제보다 또는 경쟁사업자의 것보다 현저히 우량·유리한 것으로 또는 경쟁사업자의 것을 현저히 불량·불리한 것으로 고객이 잘못 알게 하여 유인.","src":"공정거래법 시행령 별표 2 제4호 나목 | 기출 2022-12 | 기출 2026-10"},{"t":"그 밖의 부당한 고객유인: 경쟁사업자와 그 고객의 거래를 계약성립 저지, 계약불이행 유인 등으로 부당하게 방해해 고객을 자기와 거래하도록 유인.","src":"공정거래법 시행령 별표 2 제4호 다목"},{"t":"공정경쟁규약으로 방지하는 불공정거래행위는 부당한 고객유인이다. 거래거절, 차별적 취급, 경쟁사업자 배제, 구속조건부거래는 아니다.","src":"공정거래법 제45조 제5항 | 기출 2023-11 | 기출 2025-12"}]},{"머리":"거래강제(시행령 별표 2 제5호)","줄":[{"t":"끼워팔기: 거래상대방에게 자기의 상품·용역을 공급하면서 정상적인 거래관행에 비추어 부당하게 다른 상품·용역을 자기 또는 자기가 지정하는 사업자로부터 구입하도록 하는 행위.","src":"공정거래법 시행령 별표 2 제5호 가목 | 기출 2022-11 | 기출 2023-16 | 기출 2024-9 | 기출 2026-11"},{"t":"사원판매: 부당하게 자기 또는 계열회사의 임직원에게 자기 또는 계열회사의 상품·용역을 구입 또는 판매하도록 강제하는 행위.","src":"공정거래법 시행령 별표 2 제5호 나목 | 기출 2024-8 | 기출 2025-15 | 기출 2026-10"},{"t":"그 밖의 거래강제: 정상적인 거래관행에 비추어 부당한 조건 등 불이익을 제시하여 자기 또는 자기가 지정하는 사업자와 거래하도록 강제하는 행위.","src":"공정거래법 시행령 별표 2 제5호 다목 | 기출 2021-12"},{"t":"거래강제의 상대방은 원칙적으로 직접 거래의 상대방이다. 다음 거래단계 상대방은 포함되지 않는다.","src":"기출 2021-16"},{"t":"임직원에게 자사 상품 구매자 확대를 촉구·독려하는 것만으로는 사원판매가 아니다. 임직원에게 상품을 수여하는 신규 구독자 확장계획을 수립·시행한 것도 사원판매에 해당하지 않는다고 본 사례가 있다.","src":"기출 2021-16"},{"t":"공동주택지 판매에서 비인기토지를 매입하지 않고서는 인기토지를 사실상 살 수 없게 한 행위는 거래강제에 해당한다.","src":"기출 2021-15"}]},{"머리":"거래상 지위의 남용(시행령 별표 2 제6호)","줄":[{"t":"구입강제: 거래상대방이 구입할 의사가 없는 상품·용역을 구입하도록 강제.","src":"공정거래법 시행령 별표 2 제6호 가목 | 기출 2021-14 | 기출 2022-13 | 기출 2024-10"},{"t":"이익제공강요: 거래상대방에게 자기를 위해 금전·물품·용역, 그 밖의 경제상 이익을 제공하도록 강요.","src":"공정거래법 시행령 별표 2 제6호 나목 | 기출 2021-14 | 기출 2024-10 | 기출 2026-10"},{"t":"판매목표강제: 자기가 공급하는 상품·용역과 관련하여 거래상대방의 거래에 관한 목표를 제시하고 이를 달성하도록 강제.","src":"공정거래법 시행령 별표 2 제6호 다목 | 기출 2021-14 | 기출 2022-13"},{"t":"불이익제공: 구입강제·이익제공강요·판매목표강제 외의 방법으로 거래상대방에게 불이익이 되도록 거래조건을 설정 또는 변경하거나 이행과정에서 불이익을 주는 행위.","src":"공정거래법 시행령 별표 2 제6호 라목 | 기출 2024-10"},{"t":"경영간섭: 거래상대방의 임직원을 선임·해임할 때 자기의 지시 또는 승인을 얻게 하거나, 생산품목·시설규모·생산량·거래내용을 제한하여 경영활동을 간섭.","src":"공정거래법 시행령 별표 2 제6호 마목 | 기출 2021-14"},{"t":"거래상 지위의 남용이 아닌 것: 거래상대방의 거래지역·거래상대방 구속(구속조건부거래), 기술의 부당이용(사업활동 방해), 부당한 자금지원(부당한 지원행위), 거래처이전 방해(사업활동 방해), 부당고가매입(경쟁사업자 배제), 부당한 이익에 의한 고객유인(부당한 고객유인), 사원판매(거래강제).","src":"공정거래법 시행령 별표 2 | 기출 2021-14 | 기출 2022-13 | 기출 2024-10 | 기출 2026-10"},{"t":"상대방에게 부당하게 불이익을 주는 행위인지는 문제가 되는 거래조건으로 상대방에게 생길 수 있는 불이익의 내용과 불이익 발생의 개연성 등 여러 요소를 종합하여 판단한다. 신문사와 지국 간 소송은 원고 관할법원에서 한다는 약정은 공정거래를 저해할 우려가 있다고 단정할 수 없다고 본 사례가 있다.","src":"기출 2021-16"}]},{"머리":"구속조건부거래(시행령 별표 2 제7호)","줄":[{"t":"배타조건부거래: 부당하게 거래상대방이 자기 또는 계열회사의 경쟁사업자와 거래하지 않는 조건으로 그 거래상대방과 거래하는 행위.","src":"공정거래법 시행령 별표 2 제7호 가목 | 기출 2021-12 | 기출 2026-12"},{"t":"거래지역 또는 거래상대방의 제한: 상품·용역을 거래할 때 그 거래상대방의 거래지역 또는 거래상대방을 부당하게 구속하는 조건으로 거래.","src":"공정거래법 시행령 별표 2 제7호 나목 | 기출 2021-14 | 기출 2024-8 | 기출 2026-10"},{"t":"대리점에 전기면도기 등 품목을 인터넷 오픈마켓에 공급하는 것을 금지하고 어기면 공급가격 인상 등을 한 행위는 구속조건부거래다.","src":"기출 2022-15"}]},{"머리":"사업활동 방해(시행령 별표 2 제8호)","줄":[{"t":"기술의 부당이용: 다른 사업자의 기술을 부당하게 이용하여 사업활동을 상당히 곤란하게 할 정도로 방해.","src":"공정거래법 시행령 별표 2 제8호 가목 | 기출 2021-11 | 기출 2023-18 | 기출 2024-8 | 기출 2026-13"},{"t":"인력의 부당유인·채용: 다른 사업자의 인력을 부당하게 유인·채용하여 사업활동을 상당히 곤란하게 할 정도로 방해.","src":"공정거래법 시행령 별표 2 제8호 나목 | 기출 2021-11 | 기출 2023-18 | 기출 2026-13"},{"t":"거래처 이전 방해: 다른 사업자의 거래처 이전을 부당하게 방해하여 사업활동을 심히 곤란하게 할 정도로 방해.","src":"공정거래법 시행령 별표 2 제8호 다목 | 기출 2021-12 | 기출 2024-8 | 기출 2025-15 | 기출 2026-13"},{"t":"그 밖의 사업활동방해: 위 방법 외의 부당한 방법으로 다른 사업자의 사업활동을 심히 곤란하게 할 정도로 방해.","src":"공정거래법 시행령 별표 2 제8호 라목"},{"t":"생산·용역 거래를 위한 설비의 신설·증설이나 장비 도입의 방해·제한은 부당한 공동행위(제40조 제1항 제5호) 유형이다. 불공정거래행위 유형으로는 규정이 없다.","src":"공정거래법 제40조 제1항 제5호 | 기출 2025-14"}]},{"머리":"부당한 지원행위(시행령 별표 2 제9호)","줄":[{"t":"부당한 자금지원: 특수관계인 또는 다른 회사에 가지급금·대여금 등 자금을 상당히 낮거나 높은 대가로 제공·거래하거나 상당한 규모로 제공·거래.","src":"공정거래법 시행령 별표 2 제9호 가목 | 기출 2022-14 | 기출 2025-13"},{"t":"부당한 자산·상품 등 지원: 부동산·유가증권·무체재산권 등 자산 또는 상품·용역을 상당히 낮거나 높은 대가로 또는 상당한 규모로 제공·거래.","src":"공정거래법 시행령 별표 2 제9호 나목 | 기출 2021-13 | 기출 2022-14 | 기출 2023-17 | 기출 2025-13"},{"t":"부당한 인력지원: 인력을 상당히 낮거나 높은 대가로 또는 상당한 규모로 제공·거래.","src":"공정거래법 시행령 별표 2 제9호 다목 | 기출 2021-13 | 기출 2022-14 | 기출 2025-13"},{"t":"부당한 거래단계 추가 등: 직접 거래하면 상당히 유리한데도 ① 거래상 역할이 없거나 미미한 특수관계인·다른 회사를 거래단계에 추가하거나 거쳐 거래하는 행위, ② 거래단계에 추가하거나 거쳐 거래하면서 거래상 역할에 비해 과도한 대가를 지급하는 행위.","src":"공정거래법 시행령 별표 2 제9호 라목 | 기출 2021-13 | 기출 2022-14 | 기출 2025-13"},{"t":"부당한 거래기회 제공은 부당한 지원행위 유형이 아니다. 별표 2 제9호 유형은 자금지원, 자산·상품 등 지원, 인력지원, 거래단계 추가 등 4가지다. 부당고가매입은 경쟁사업자 배제 유형이다.","src":"공정거래법 시행령 별표 2 제9호 | 기출 2021-13"},{"t":"무체재산권 제공도 부당한 지원행위(제9호)에 해당한다. 과징금 한도가 다른 불공정거래행위(4%·10억)와 다르다.","src":"공정거래법 제45조 제1항 제9호 | 기출 2023-17"}]},{"머리":"과징금·형사·금지청구·보복조치","줄":[{"t":"과징금: 제45조 제1항(제9호 제외), 제46조, 제48조 위반 사업자에게 관련매출액 100분의 4 이하. 매출액이 없는 경우 등은 10억원 이하.","src":"공정거래법 제50조 제1항 | 기출 2023-20 | 기출 2025-11 | 기출 2025-16"},{"t":"과징금: 제45조 제1항 제9호(부당한 지원행위) 또는 제2항(지원받는 행위), 제47조 제1항·제3항 위반 시 해당 특수관계인 또는 회사에 평균매출액 100분의 10 이하. 매출액이 없는 경우 등은 40억원 이하.","src":"공정거래법 제50조 제2항 | 기출 2023-17 | 기출 2025-13 | 기출 2026-18"},{"t":"형사: 제45조 제1항 제9호 위반은 3년 이하의 징역 또는 2억원 이하의 벌금.","src":"공정거래법 제124조 제1항 제10호"},{"t":"형사: 제45조 제1항 위반(제1호·제2호·제3호·제7호·제9호 제외)의 불공정거래행위는 2년 이하의 징역 또는 1억5천만원 이하의 벌금.","src":"공정거래법 제125조 제4호"},{"t":"금지청구: 제45조 제1항(제9호 제외) 위반으로 피해를 입거나 입을 우려가 있는 자는 위반행위를 하거나 할 우려가 있는 사업자(사업자단체)에 침해행위의 금지·예방을 청구할 수 있다.","src":"공정거래법 제108조 제1항 | 기출 2023-21"},{"t":"금지청구의 소는 민사소송법상 관할 지방법원 외에 그 지방법원 소재지를 관할하는 고등법원이 있는 곳의 지방법원에도 제기할 수 있다.","src":"공정거래법 제108조 제2항 | 기출 2023-21"},{"t":"법원은 금지청구의 소가 제기되면 피고의 이익을 보호하기 위해 필요하다고 인정하는 때 피고의 신청이나 직권으로 원고에게 상당한 담보 제공을 명할 수 있다.","src":"공정거래법 제108조 제3항 | 기출 2023-21"},{"t":"보복조치 금지: 사업자는 제45조 제1항 불공정거래행위 및 제46조 재판매가격유지행위와 관련하여 분쟁조정 신청, 신고, 공정거래위원회 조사 협조를 한 사업자에게 그 이유로 거래정지·물량축소·그 밖의 불이익을 주거나 계열회사·다른 사업자가 하도록 해서는 안 된다.","src":"공정거래법 제48조 | 기출 2023-19"},{"t":"보복조치를 한 자: 3년 이하의 징역 또는 2억원 이하의 벌금. 보복조치는 과징금 4%·10억 대상이다.","src":"공정거래법 제124조 제1항 제11호·제50조 제1항"},{"t":"시정조치: 해당 불공정거래행위의 중지 및 재발방지를 위한 조치, 보복조치 금지, 계약조항의 삭제, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치.","src":"공정거래법 제49조 제1항"},{"t":"조정원의 분쟁조정은 제45조 제1항을 위반한 혐의가 있는 행위와 관련된 분쟁이 대상이다.","src":"공정거래법 제72조 제1항 제1호·제73조 제1항"}]}],"함정":[{"x":"거래강제의 상대방은 원칙적으로 직접 거래의 상대방뿐만 아니라 거래의 다음 단계의 상대방도 포함된다.","o":"거래강제의 상대방은 원칙적으로 직접 거래의 상대방이다.","src":"기출 2021-16"},{"x":"사업자 또는 사업자단체는 공정거래위원회에 공정경쟁규약이 이 법을 위반하는지에 대한 심사를 요청해야 한다.","o":"공정경쟁규약 심사는 요청할 수 있다(의무 아님).","src":"공정거래법 제45조 제6항 | 기출 2022-17"},{"x":"부당염매로 인해 경쟁사업자가 관련시장에서 실제로 배제될 것을 요건으로 한다.","o":"경쟁사업자를 배제시킬 '우려'가 있으면 족하다. 실제 배제는 요건이 아니다.","src":"공정거래법 시행령 별표 2 제3호 가목 | 기출 2023-20"},{"x":"사업자 또는 사업자단체는 공정거래위원회에 공정경쟁규약이 법률 규정을 위반하는지에 대한 심사를 요청하여야 한다.","o":"공정경쟁규약 심사는 요청할 수 있다(의무 아님).","src":"공정거래법 제45조 제6항 | 기출 2024-12"},{"x":"자기의 상품을 공급하는 경우에 정당한 이유 없이 그 공급에 소요되는 비용보다 현저히 낮은 가격으로 계속 공급하는 경우는 부당염매에 해당하지 않는다.","o":"비용보다 현저히 낮은 가격으로 계속 공급하는 행위는 부당염매에 해당한다.","src":"공정거래법 시행령 별표 2 제3호 가목 | 기출 2025-11"},{"x":"공정거래위원회는 공정경쟁규약의 심사를 요청받은 경우 요청을 받은 날부터 90일이 내에 그 심사결과를 서면으로 요청인에게 통보해야 한다.","o":"요청을 받은 날부터 60일 이내에 통보해야 한다.","src":"공정거래법 시행령 제53조 | 기출 2026-14"}]},"재판매가격유지행위의 제한":{"묶음":[{"머리":"재판매가격유지행위의 정의와 금지(제2조 제20호·제46조)","줄":[{"t":"재판매가격유지행위: 사업자가 상품·용역을 거래할 때 거래상대방인 사업자 또는 그 다음 거래단계별 사업자에 대해 거래가격을 정하여 그 가격대로 판매·제공할 것을 강제하거나 그 밖의 구속조건을 붙여 거래하는 행위.","src":"공정거래법 제2조 제20호 | 기출 2022-18 | 기출 2023-13 | 기출 2026-15"},{"t":"대상은 상품과 용역 모두다. 용역도 재판매가격유지행위 규제 대상이다.","src":"공정거래법 제2조 제20호 | 기출 2021-20 | 기출 2022-18 | 기출 2024-13"},{"t":"상대방은 직접 거래상대방인 사업자뿐 아니라 그 다음 거래단계별 사업자도 포함한다.","src":"공정거래법 제2조 제20호 | 기출 2021-20 | 기출 2024-13"},{"t":"사업자는 재판매가격유지행위를 하여서는 안 된다. 다만 정당한 이유가 있는 경우와 출판된 저작물인 경우에는 허용된다.","src":"공정거래법 제46조"},{"t":"허용 1: 효율성 증대로 인한 소비자후생 증대효과가 경쟁제한으로 인한 폐해보다 큰 경우 등 정당한 이유가 있는 경우.","src":"공정거래법 제46조 제1호 | 기출 2021-19 | 기출 2024-13 | 기출 2025-16"},{"t":"허용 2: 저작권법 제2조 제1호에 따른 저작물 중 관계 중앙행정기관의 장과 협의를 거쳐 공정거래위원회가 고시하는 출판된 저작물(전자출판물 포함).","src":"공정거래법 제46조 제2호 | 기출 2021-19 | 기출 2022-19 | 기출 2023-13 | 기출 2024-13 | 기출 2025-16"},{"t":"정당한 이유가 있는지의 증명책임은 사업자에게 있다.","src":"기출 2021-19 | 기출 2023-13 | 기출 2025-16"},{"t":"최고가격유지행위는 정당한 이유가 있으면 허용된다. 최저재판매가격 유지행위도 정당한 이유가 있으면 허용되므로 이유의 존재 여부와 상관없이 금지되는 것은 아니다.","src":"공정거래법 제46조 제1호 | 기출 2021-19 | 기출 2022-19 | 기출 2024-14"},{"t":"(2021 기출 당시) 품질동일성을 쉽게 식별할 수 있는 상품으로 공정거래위원회가 지정한 상품은 재판매가격유지행위가 허용되었다. 현행 제46조에는 지정상품 제도가 없다.","src":"기출 2021-20 | 기출 2022-19"}]},{"머리":"판단 기준·사례","줄":[{"t":"권장소비자가격 통보나 판매가격 인상요청에 실효성을 확보할 수 있는 수단이 부수되어 있지 않으면 재판매가격유지행위에 해당하지 않는다. 강제성 없는 희망가격 제시는 금지되지 않는다.","src":"기출 2022-19 | 기출 2023-13 | 기출 2024-14"},{"t":"거래가격을 정해 그 가격대로 판매하도록 구속조건을 붙여 거래하면 재판매가격유지행위다. 구속조건이 없으면 해당하지 않는다.","src":"공정거래법 제2조 제20호 | 기출 2023-13 | 기출 2024-14"},{"t":"골프용품 수입·판매회사가 도매가·권장소비자가를 표시한 가격표를 대리점에 배부하고 영업사원이 최저판매가를 구술 통지하면서 위반 시 거래정지 등 불이익을 준 행위는 재판매가격유지행위다.","src":"기출 2021-19"},{"t":"위탁매매 형식이라는 이유만으로 모든 거래에 대해 재판매가격유지행위가 허용되지는 않는다.","src":"기출 2022-19"},{"t":"금지 취지: 사업자가 거래가격을 미리 정하여 유통단계의 가격경쟁을 제한해 소비자후생을 저해하는 것을 방지하기 위한 것.","src":"기출 2021-19"},{"t":"성격: 상위 사업자가 하위 사업자에 조직적으로 가격제한을 가해 하위 사업자의 자율성을 침해하는 수직적 가격결정(Vertical Price Fixing)이다.","src":"기출 2022-18 | 기출 2024-14"},{"t":"효과: 판매업자에게 안정적 이윤을 보장해 유통경로 확보와 시장지배력 확대에 도움이 될 수 있다. 브랜드 내 가격경쟁(intrabrand)은 불가능해지지만 품질·서비스 등 비가격경쟁은 촉진될 수 있다.","src":"기출 2022-18"},{"t":"상표 내 경쟁은 제한되고 상표 간 경쟁은 촉진될 수 있다는 것이 재판매가격유지의 장점으로 거론되는 내용이다. 반대로 말하면 틀린다.","src":"기출 2024-14"}]},{"머리":"시정조치·과징금·사업자단체(제49조·제50조·제51조)","줄":[{"t":"시정조치: 재판매가격유지행위의 중지 및 재발방지를 위한 조치, 보복조치 금지, 계약조항의 삭제, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치. '법위반 사실의 공표'는 규정에 없다.","src":"공정거래법 제49조 제1항 | 기출 2025-20"},{"t":"과징금: 관련매출액에 100분의 4를 곱한 금액 이하. 매출액이 없는 경우 등은 10억원 이하. 부과기준은 거래거절 등 다른 불공정거래행위(제45조 제1항 제9호 제외)와 같다.","src":"공정거래법 제50조 제1항 | 기출 2025-16"},{"t":"사업자단체가 사업자에게 재판매가격유지행위를 하게 하거나 방조하면 금지행위에 해당한다. 사업자단체에는 10억원의 범위에서 과징금, 참가 사업자에는 매출액 100분의 10(없으면 20억원) 이하 과징금.","src":"공정거래법 제51조 제1항 제4호·제53조 제1항·제3항 | 기출 2023-13"},{"t":"재판매가격유지행위 관련 분쟁조정 신청·신고·조사협조를 이유로 한 보복조치는 금지된다. 금지청구(제108조)는 제45조 위반에 대한 것이며 제46조는 해당 조문에 없다.","src":"공정거래법 제48조·제108조 | 기출 2023-19"},{"t":"제46조 위반은 형사처벌 규정(제124조·제125조) 대상 조문에 열거되어 있지 않다. 제재는 시정조치와 과징금이다.","src":"공정거래법 제124조·제125조"}]}],"함정":[{"x":"골프용품 수입ㆍ판매회사가 골프채의 도매가 및 권장소비자가를 표시한 가격표를 대리점에 배부하고 영업사원이 최저판매가를 구술로 통지하는 방식으로 재판매가격을 유지하고 이를 위반할 경우 거래정지 등의 불이익을 준 것은 재판매가격유지행위에 해당하지 않는다.","o":"그 행위는 재판매가격유지행위에 해당한다.","src":"기출 2021-19"},{"x":"거래상대방인 사업자가 아니라 그 다음 거래단계별 사업자에 대하여 재판매가격유지 행위를 하는 것은 허용된다.","o":"직접 거래상대방뿐 아니라 그 다음 거래단계별 사업자에 대한 행위도 재판매가격유지행위 정의에 포함되어 금지된다.","src":"공정거래법 제2조 제20호 | 기출 2021-20"},{"x":"용역의 거래에 있어서는 재판매가격유지행위가 제한되지 않는다.","o":"용역 거래도 재판매가격유지행위 규제 대상이다.","src":"공정거래법 제2조 제20호 | 기출 2021-20"},{"x":"공정거래위원회는 재판매가격유지행위를 허용하는 경우에도 그 재판매가격유지계약이 소비자의 이익을 현저히 저해할 우려가 있을 때에는 계약내용의 수정을 명하여야 한다.","o":"출제 오답(바른 문장 미확인). 현행 제46조·제49조에 계약내용 수정명령 규정은 없다.","src":"보충(추정) | 기출 2021-20"},{"x":"공정거래위원회가 계약내용의 수정을 명한 경우 이에 응하지 않은 자에 대해서는과 징금을 부과할 수 있다.","o":"출제 오답(바른 문장 미확인). 현행 제재는 시정조치(제49조)와 과징금(제50조)이다.","src":"공정거래법 제49조 | 제50조 | 기출 2021-20"},{"x":"재판매가격유지행위 금지 규정이 적용되는 거래의 대상에 용역은 포함되지 아니한다.","o":"용역 거래도 규제 대상에 포함된다.","src":"공정거래법 제2조 제20호 | 기출 2022-18"},{"x":"최저재판매가격 유지행위는 정당한 이유의 존재유무와 상관없이 금지된다.","o":"최저재판매가격 유지행위도 정당한 이유가 있으면 허용된다.","src":"공정거래법 제46조 제1호 | 기출 2022-19"},{"x":"품질동일성의 용이한 식별 등의 요건을 갖춘 상품으로서 공정거래위원회로부터 지정을 받은 상품에 대해서는 재판매가격유지행위가 허용된다.","o":"현행 제46조에는 지정상품 제도가 없다. 허용되는 경우는 정당한 이유가 있는 경우와 출판된 저작물뿐이다.","src":"공정거래법 제46조 | 기출 2022-19"},{"x":"강제성이 없는 권장가격이 제시된 경우에도 재판매가격유지행위로서 금지된다.","o":"구속조건이 부수되지 않은 강제성 없는 권장가격 제시는 재판매가격유지행위가 아니다.","src":"기출 2022-19"},{"x":"위탁매매의 형식을 가지는 모든 거래에 대해서는 재판매가격유지행위가 허용된다.","o":"허용되는 경우는 제46조 각 호(정당한 이유가 있는 경우, 출판된 저작물)에 해당할 때뿐이다.","src":"공정거래법 제46조 | 기출 2022-19"},{"x":"공정거래위원회는 사업자에게 재판매가격유지행위를 하게 하는 사업자단체에 대하여 20억원의 범위에서 과징금을 부과할 수 있다.","o":"사업자단체에 10억원의 범위에서 과징금을 부과할 수 있다.","src":"공정거래법 제53조 제1항 | 기출 2023-13"},{"x":"사업자가 용역을 거래할 때 거래상대방인 사업자에 대하여 최저가격을 정하여 그가 격대로 제공할 것을 강제하였다면 정당한 이유가 존재하여도 금지된다.","o":"정당한 이유가 있으면 최저가격 유지행위도 허용된다.","src":"공정거래법 제46조 제1호 | 기출 2024-14"},{"x":"사업자가 상품을 거래할 때 거래상대방에 대하여 강제력 없는 희망가격을 제시하는 행위도 재판매가격유지행위로써 금지된다.","o":"강제성 없는 희망가격 제시는 구속조건이 부수되지 않는 한 금지되지 않는다.","src":"기출 2022-19 | 기출 2023-13 | 기출 2024-14"},{"x":"사업자가 상품을 거래하면서 거래상대방인 사업자에 대하여 거래가격을 정하여 그가 격대로 판매하도록 조건을 붙여 거래하는 행위를 하였다면 그 조건의 구속력 여부에 상관없이 금지된다.","o":"구속조건을 붙여 거래해야 재판매가격유지행위다. 구속력 없는 조건은 해당하지 않는다.","src":"공정거래법 제2조 제20호 | 기출 2024-14"},{"x":"상표간의 경쟁(inter-brand competition)은 제한되나 상표내의 경쟁(intra-brand competition) 은 촉진할 수 있다는 장점이 있다.","o":"상표 내 경쟁(intra-brand)은 제한되고 상표 간 경쟁(inter-brand)은 촉진될 수 있다.","src":"기출 2022-18 | 기출 2024-14"},{"x":"전자출판물은 관계 중앙행정기관의 장과의 협의를 거쳐 공정거래위원회가 고시하는 출판된 저작물에 포함되지 않는다.","o":"전자출판물도 포함된다.","src":"공정거래법 제46조 제2호 | 기출 2025-16"}]},"사업자단체의 금지행위":{"묶음":[{"머리":"사업자단체의 요건(제2조 제2호)","줄":[{"t":"사업자단체: 형태가 무엇이든 상관없이 둘 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 연합체.","src":"공정거래법 제2조 제2호 | 기출 2021-17 | 기출 2023-1 | 기출 2025-19 | 기출 2026-19"},{"t":"법인격이 필요 없다. 사업자단체와 구성 사업자는 법인이 아니어도 되며, 조합이나 법인 등 형태의 제한이 없다.","src":"공정거래법 제2조 제2호 | 기출 2021-17 | 기출 2024-15 | 기출 2026-19"},{"t":"둘 이상의 사업자로 구성된다.","src":"공정거래법 제2조 제2호 | 기출 2026-19"},{"t":"개별 구성사업자와 구별되는 단체성·조직성을 갖추어야 한다. 개별 사업자가 단체에 흡수되어 독자적 활동을 하지 않으면 사업자단체가 아니다.","src":"기출 2021-17 | 기출 2023-15 | 기출 2024-15 | 기출 2026-19"},{"t":"친목, 종교, 학술, 조사, 연구, 사회활동만을 목적으로 하는 단체는 사업자단체에 해당하지 않는다.","src":"기출 2021-17 | 기출 2023-15 | 기출 2024-15 | 기출 2026-19"},{"t":"대한의사협회는 사업자단체에 해당한다.","src":"기출 2022-21 | 기출 2026-19"},{"t":"사업자단체를 설립해도 공정거래위원회에 신고할 의무가 없다.","src":"기출 2021-17 | 기출 2025-19"}]},{"머리":"금지행위 4가지(제51조 제1항)","줄":[{"t":"제1호: 제40조 제1항 각 호의 행위(부당한 공동행위 유형)로 부당하게 경쟁을 제한하는 행위.","src":"공정거래법 제51조 제1항 제1호 | 기출 2021-18 | 기출 2023-14 | 기출 2025-18 | 기출 2026-20"},{"t":"제2호: 일정한 거래분야에서 현재 또는 장래의 사업자 수를 제한하는 행위.","src":"공정거래법 제51조 제1항 제2호 | 기출 2021-18 | 기출 2023-14 | 기출 2024-16 | 기출 2025-18"},{"t":"제3호: 구성사업자(사업자단체의 구성원인 사업자)의 사업내용 또는 활동을 부당하게 제한하는 행위.","src":"공정거래법 제51조 제1항 제3호 | 기출 2021-18 | 기출 2022-16 | 기출 2023-14 | 기출 2025-18"},{"t":"제4호: 사업자에게 불공정거래행위(제45조 제1항) 또는 재판매가격유지행위(제46조)를 하게 하거나 이를 방조하는 행위.","src":"공정거래법 제51조 제1항 제4호 | 기출 2021-18 | 기출 2023-14 | 기출 2024-16 | 기출 2025-18 | 기출 2026-20"},{"t":"금지행위에 없는 것: 시장지배적지위를 남용하여 경쟁을 제한하는 행위, 소비자의 이익을 현저히 해칠 우려가 있는 행위, 시장구조의 조사·공표.","src":"공정거래법 제51조 제1항 | 기출 2021-18 | 기출 2023-14 | 기출 2024-16 | 기출 2025-18"},{"t":"제1호의 인가에 관하여는 제40조 제2항·제3항을 준용한다('사업자'는 '사업자단체'로 본다).","src":"공정거래법 제51조 제2항 | 기출 2022-20"},{"t":"공정거래위원회는 금지행위를 예방하기 위해 필요하면 사업자단체가 준수하여야 할 지침을 제정·고시할 수 있다. 지침을 제정하려면 관계 행정기관의 장의 의견을 들어야 한다.","src":"공정거래법 제51조 제3항·제4항 | 기출 2021-17 | 기출 2022-20 | 기출 2023-15 | 기출 2025-19"}]},{"머리":"사례·판례(기출)","줄":[{"t":"제1호 행위는 사업자단체의 의사결정만으로 성립한다. 구성원이 그 의사결정에 따른 행위를 현실적으로 하였을 것을 요하지 않는다.","src":"기출 2022-21 | 기출 2026-20"},{"t":"광역시 치과의사회와 치과기공사회가 실무협의회 소속 회원을 통해 치과기공물 가격 가이드라인을 정하고 대표자 추인을 받아 안내문을 발송한 행위는 사업자단체에 의한 가격결정행위다.","src":"기출 2022-21"},{"t":"대한법무사협회가 소속 법무사의 집단등기사건 수임을 제한하는 규정을 제정·시행한 행위는 구성사업자의 사업내용·활동을 부당하게 제한하는 행위(제3호)다.","src":"기출 2022-21"},{"t":"대한의사협회가 의약분업정책에 항의해 일제 휴업을 결의·시행한 행위, 대한약사회가 소속 약국의 집단 휴업을 결의·시행한 행위도 제3호에 해당한다.","src":"기출 2022-21"},{"t":"자동차부분정비사업자 사업자단체가 구성사업자들에게 특정 지정폐기물 처리업체를 통해서만 처리하도록 강제하고 따르지 않는 구성사업자를 제명한 행위는 제3호에 해당한다.","src":"기출 2022-16 | 기출 2026-20"}]},{"머리":"시정조치·과징금·형사","줄":[{"t":"시정조치: 해당 사업자단체(필요한 경우 관련 구성사업자 포함)에 해당 행위의 중지, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치를 명할 수 있다.","src":"공정거래법 제52조 제1항 | 기출 2022-20 | 기출 2025-19"},{"t":"합병·분할 등에 따른 시정조치는 제7조 제2항~제4항을 준용한다('시장지배적사업자'는 '사업자단체'로 본다).","src":"공정거래법 제52조 제2항"},{"t":"과징금 대상 1: 제51조 제1항 위반 사업자단체에 10억원의 범위.","src":"공정거래법 제53조 제1항 | 기출 2022-20 | 기출 2023-13"},{"t":"과징금 대상 2: 제1호 위반 행위에 참가한 사업자에 매출액 100분의 20 이하(매출액이 없는 경우 등 40억원 이하).","src":"공정거래법 제53조 제2항"},{"t":"과징금 대상 3: 제2호~제4호 위반 행위에 참가한 사업자에 매출액 100분의 10 이하(매출액이 없는 경우 등 20억원 이하).","src":"공정거래법 제53조 제3항"},{"t":"형사: 제51조 제1항 제1호 위반은 3년 이하의 징역 또는 2억원 이하의 벌금. 같은 항 제3호 위반은 2년 이하의 징역 또는 1억5천만원 이하의 벌금.","src":"공정거래법 제124조 제1항 제12호·제125조 제5호 | 기출 2024-15"},{"t":"사업자단체가 제51조 제1항 제4호의 불공정거래행위를 하게 한 경우에도 금지청구(제108조)의 대상이 된다.","src":"공정거래법 제108조 제1항"}]}],"함정":[{"x":"사업자단체라 함은 법인격을 갖춘 2 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 연합체를 말한다.","o":"사업자단체는 법인격이 필요 없다. 형태가 무엇이든 상관없이 둘 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 연합체.","src":"공정거래법 제2조 제2호 | 기출 2021-17"},{"x":"구성사업자들의 친목, 종교, 학술만을 목적으로 하는 단체도 사업자단체에 해당한다.","o":"친목, 종교, 학술만을 목적으로 하는 단체는 사업자단체에 해당하지 않는다.","src":"기출 2023-15 | 기출 2026-19 | 기출 2021-17"},{"x":"사업자단체를 설립한 경우 이를 공정거래위원회에 신고하여야 한다.","o":"사업자단체 설립은 공정거래위원회 신고 대상이 아니다.","src":"기출 2025-19 | 기출 2021-17"},{"x":"공정거래위원회는 사업자단체가 준수하여야 할 지침을 제정ㆍ고시하여야 한다.","o":"지침은 필요한 경우 제정·고시할 수 있다(재량).","src":"공정거래법 제51조 제3항 | 기출 2021-17"},{"x":"공정거래위원회가 사업자단체에 시정조치를 명하는 경우 관련 구성사업자에 대해서는 시정조치를 명할 수 없다.","o":"사업자단체에 시정조치를 명할 때 필요한 경우 관련 구성사업자도 포함해 명할 수 있다.","src":"공정거래법 제52조 제1항 | 기출 2022-20"},{"x":"공정거래위원회는 사업자단체가 준수하여야 할 지침을 제정ㆍ고시하여야 한다.","o":"사업자단체 지침은 필요한 경우 제정·고시할 수 있다(재량).","src":"공정거래법 제51조 제3항 | 기출 2023-15"},{"x":"조사, 연구, 사회활동만을 목적으로 하여 이에 관한 활동만을 하는 단체도 이 법상 사 업자단체에 해당된다.","o":"조사, 연구, 사회활동만을 목적으로 하는 단체는 사업자단체에 해당하지 않는다.","src":"기출 2021-17 | 기출 2023-15 | 기출 2024-15"},{"x":"사업자단체를 설립한 경우에는 공정거래위원회에 신고하여야 한다.","o":"사업자단체 설립은 신고 대상이 아니다.","src":"기출 2021-17 | 기출 2025-19"},{"x":"대한의사협회는 사업자단체에 해당하지 아니 한다.","o":"대한의사협회는 사업자단체에 해당한다.","src":"기출 2022-21 | 기출 2026-19"},{"x":"사업자단체의 부당한 공동행위는 구성원이 사업자단체의 의사결정에 따른 행위를 현 실적으로 하였을 것을 요한다.","o":"사업자단체의 의사결정만으로 충분하며 구성원이 현실적으로 따를 필요는 없다.","src":"기출 2022-21 | 기출 2026-20"}]},"적용제외":{"묶음":[{"머리":"적용제외 규정(제116조~제118조)","줄":[{"t":"법령에 따른 정당한 행위: 사업자 또는 사업자단체가 다른 법령에 따라 하는 정당한 행위에는 이 법을 적용하지 않는다.","src":"공정거래법 제116조 | 기출 2023-29 | 기출 2025-28 | 기출 2026-3"},{"t":"무체재산권 행사행위: 저작권법, 특허법, 실용신안법, 디자인보호법, 상표법에 따른 권리의 정당한 행사라고 인정되는 행위에는 적용하지 않는다.","src":"공정거래법 제117조 | 기출 2023-29 | 기출 2025-28 | 기출 2026-3"},{"t":"일정한 조합의 행위에는 적용하지 않는다. 다만 불공정거래행위 또는 부당하게 경쟁을 제한하여 가격을 인상하게 되는 경우에는 적용한다.","src":"공정거래법 제118조 | 기출 2025-28 | 기출 2026-3"},{"t":"조합 요건 1: 소규모의 사업자 또는 소비자의 상호부조를 목적으로 할 것.","src":"공정거래법 제118조 제1호"},{"t":"조합 요건 2: 임의로 설립되고 조합원이 임의로 가입하거나 탈퇴할 수 있을 것.","src":"공정거래법 제118조 제2호"},{"t":"조합 요건 3: 각 조합원이 평등한 의결권을 가질 것.","src":"공정거래법 제118조 제3호"},{"t":"조합 요건 4: 조합원에게 이익배분을 하는 경우 그 한도가 정관에 정하여져 있을 것.","src":"공정거래법 제118조 제4호"},{"t":"조합연합체도 조합에 포함된다. 불공정거래행위는 조합 행위라도 적용 대상이다.","src":"공정거래법 제118조 | 기출 2025-28"}]},{"머리":"적용제외가 아닌 것·관련 조문","줄":[{"t":"국외에서 이루어진 행위라도 국내 시장에 영향을 미치면 이 법이 적용된다. 적용제외가 아니다.","src":"공정거래법 제3조 | 기출 2026-3"},{"t":"국가가 사경제의 주체로서 거래행위를 하면 그 범위에서 사업자에 포함되어 이 법이 적용된다.","src":"기출 2026-3"},{"t":"비밀엄수의무: 이 법에 따른 직무에 종사하거나 종사하였던 위원·공무원, 분쟁조정업무 담당자, 동의의결 이행관리 담당자, 시정조치 이행관리 담당자는 직무상 알게 된 사업자·사업자단체의 비밀을 누설하거나 이 법 시행 목적 외에 이용해서는 안 된다.","src":"공정거래법 제119조 | 기출 2023-29"},{"t":"제119조 위반: 2년 이하의 징역 또는 200만원 이하의 벌금.","src":"공정거래법 제127조 제3항"},{"t":"경쟁제한적 법령 제정 협의: 관계 행정기관의 장은 경쟁제한사항을 내용으로 하는 법령을 제정·개정하거나 경쟁제한사항을 내용으로 하는 승인·처분을 하려면 미리 공정거래위원회와 협의하여야 한다.","src":"공정거래법 제120조 제1항"},{"t":"관계 행정기관의 장이 경쟁제한사항을 내용으로 하는 예규·고시 등을 제정·개정하려면 미리 공정거래위원회에 통보하여야 한다.","src":"공정거래법 제120조 제2항 | 기출 2023-29"},{"t":"경쟁제한사항을 내용으로 하는 승인·처분을 한 경우에도 그 내용을 공정거래위원회에 통보하여야 한다. 공정거래위원회는 경쟁제한사항 시정 의견을 제시할 수 있다.","src":"공정거래법 제120조 제3항~제5항"},{"t":"공정거래위원회는 이 법 시행을 위해 필요하다고 인정할 때 관계 행정기관 등의 장의 의견을 들을 수 있고(들어야 하는 것이 아니다), 필요한 조사 의뢰·자료 요청, 시정조치 이행 확보를 위한 협조 의뢰를 할 수 있다.","src":"공정거래법 제121조 | 기출 2023-29"},{"t":"공정거래위원회는 이 법에 따른 권한의 일부를 소속 기관의 장이나 시·도지사에게 위임하거나 다른 행정기관의 장에게 위탁할 수 있다.","src":"공정거래법 제122조"}]}],"함정":[{"x":"공정거래위원회는 이 법의 시행을 위하여 필요하다고 인정할 때에는 관계 행정기관의 장의 의견을 들어야 한다.","o":"관계 행정기관 등의 장의 의견을 들을 수 있다(재량).","src":"공정거래법 제121조 제1항 | 기출 2023-29"},{"x":"불공정거래행위의 경우에도 이 법에 따라 일정한 요건을 갖추어 설립된 조합의 행위에 대해서는 이 법을 적용하지 아니한다.","o":"불공정거래행위나 부당하게 경쟁을 제한해 가격을 인상하는 경우에는 조합의 행위도 적용 대상이다.","src":"공정거래법 제118조 단서 | 기출 2025-28"},{"x":"국외에서 이루어진 행위는 그 행위가 국내 시장에 영향을 미치는 경우라도 이 법을 적용하지 아니한다.","o":"국외 행위도 국내 시장에 영향을 미치면 이 법이 적용된다.","src":"공정거래법 제3조 | 기출 2026-3"}]},"공정거래위원회의 조직과 회의":{"묶음":[{"머리":"설치·소관 사무(제54조·제55조)","줄":[{"t":"공정거래위원회는 이 법에 따른 사무를 독립적으로 수행하기 위하여 국무총리 소속으로 둔다. 정부조직법상 중앙행정기관으로서 소관 사무를 수행한다.","src":"공정거래법 제54조 | 기출 2022-22 | 기출 2025-22 | 기출 2026-28"},{"t":"소관 사무 1: 시장지배적지위의 남용행위 규제에 관한 사항.","src":"공정거래법 제55조 제1호 | 기출 2021-21 | 기출 2025-22 | 기출 2026-21"},{"t":"소관 사무 2: 기업결합의 제한 및 경제력 집중의 억제에 관한 사항.","src":"공정거래법 제55조 제2호"},{"t":"소관 사무 3: 부당한 공동행위 및 사업자단체의 경쟁제한행위 규제에 관한 사항.","src":"공정거래법 제55조 제3호 | 기출 2021-21 | 기출 2026-21"},{"t":"소관 사무 4: 불공정거래행위, 재판매가격유지행위 및 특수관계인에 대한 부당한 이익제공의 금지행위 규제에 관한 사항.","src":"공정거래법 제55조 제4호 | 기출 2021-21 | 기출 2026-21"},{"t":"소관 사무 5: 경쟁제한적인 법령 및 행정처분의 협의·조정 등 경쟁촉진정책에 관한 사항.","src":"공정거래법 제55조 제5호 | 기출 2021-21 | 기출 2022-22 | 기출 2026-21"},{"t":"소관 사무 6: 다른 법령에서 공정거래위원회의 소관으로 규정한 사항.","src":"공정거래법 제55조 제6호"},{"t":"'시장 또는 산업의 동향과 공정경쟁에 관한 조사 및 분석'은 공정거래위원회 소관 사무가 아니라 한국공정거래조정원의 업무다.","src":"공정거래법 제72조 제1항 제3호 | 기출 2021-21 | 기출 2026-21"},{"t":"국제협력: 정부는 외국정부와 이 법의 집행을 위한 협정을 체결할 수 있고, 공정거래위원회는 협정에 따라 외국정부의 법집행을 지원할 수 있다.","src":"공정거래법 제56조 제1항·제2항 | 기출 2025-22"},{"t":"협정이 없어도 외국정부의 법집행 요청 시 동일하거나 유사한 사항에 관해 대한민국의 지원요청에 따른다는 요청국의 보증이 있으면 지원할 수 있다.","src":"공정거래법 제56조 제3항 | 기출 2025-22"}]},{"머리":"구성·임기·신분(제57조~제63조)","줄":[{"t":"구성: 위원장 1명, 부위원장 1명을 포함하여 11명, 그중 5명은 비상임위원. (2023·2025 기출 당시 9명, 비상임 4명)","src":"공정거래법 제57조 제1항 | 기출 2023-25 | 기출 2025-22"},{"t":"위원 자격: 독점규제·공정거래 또는 소비자분야에 경험·전문지식이 있는 사람으로서 2급 이상 공무원 경력자, 판사·검사·변호사 15년 이상, 법률·경제·경영·소비자 분야 전공 부교수 이상으로 15년 이상 근무한 사람, 기업경영·소비자보호활동 15년 이상 종사자.","src":"공정거래법 제57조 제2항"},{"t":"임명: 위원장과 부위원장은 국무총리의 제청으로 대통령이 임명한다. 그 밖의 위원은 위원장의 제청으로 대통령이 임명하거나 위촉한다. 위원장은 국회 인사청문을 거친다.","src":"공정거래법 제57조 제2항"},{"t":"위원장과 부위원장은 정무직이다. 그 밖의 상임위원은 고위공무원단 소속 일반직공무원으로서 임기제공무원이다. 위원장·부위원장·사무처장은 정부위원이 된다.","src":"공정거래법 제57조 제3항·제4항"},{"t":"임기: 위원장, 부위원장 및 다른 위원 모두 3년이며 한 차례만 연임할 수 있다.","src":"공정거래법 제61조 | 기출 2021-27 | 기출 2022-22 | 기출 2025-21 | 기출 2026-28"},{"t":"신분보장: 금고 이상의 형 선고, 장기간의 심신쇠약으로 직무수행 불능인 경우를 제외하고 의사에 반해 면직·해촉되지 않는다.","src":"공정거래법 제62조"},{"t":"위원은 정당에 가입하거나 정치운동에 관여할 수 없다.","src":"공정거래법 제63조 | 기출 2025-21 | 기출 2026-28"},{"t":"위원장은 공정거래위원회를 대표하며 국무회의에 출석하여 발언할 수 있다. 위원장이 직무를 수행할 수 없으면 부위원장이, 둘 다 불가능하면 선임상임위원 순으로 대행한다.","src":"공정거래법 제60조 | 기출 2022-22 | 기출 2026-28"},{"t":"사무처를 두어 사무를 처리한다. 사무처의 장은 정부위원이 된다.","src":"공정거래법 제70조·제57조 제4항"}]},{"머리":"회의의 구분·관장·의결(제58조·제59조·제64조)","줄":[{"t":"회의 구분: 위원 전원으로 구성하는 전원회의, 상임위원 1명을 포함하여 위원 3명으로 구성하는 소회의. 소회의는 5개 이내를 둔다.","src":"공정거래법 제58조 | 공정거래법 시행령 제59조 제1항 | 기출 2023-25 | 기출 2025-21 | 기출 2026-28"},{"t":"위원장이 소회의 구성위원을 지정하고 분장업무를 지정·변경할 수 있다.","src":"공정거래법 시행령 제59조 제2항·제60조"},{"t":"전원회의 관장 1: 공정거래위원회 소관 법령이나 규칙·고시 등의 해석 적용에 관한 사항.","src":"공정거래법 제59조 제1항 제1호 | 기출 2021-27"},{"t":"전원회의 관장 2: 제96조에 따른 이의신청.","src":"공정거래법 제59조 제1항 제2호"},{"t":"전원회의 관장 3: 소회의에서 의결되지 않았거나 소회의가 전원회의에서 처리하도록 결정한 사항.","src":"공정거래법 제59조 제1항 제3호"},{"t":"전원회의 관장 4: 규칙 또는 고시의 제정 또는 변경.","src":"공정거래법 제59조 제1항 제4호 | 기출 2024-23 | 기출 2025-21 | 기출 2026-23"},{"t":"전원회의 관장 5: 경제적 파급효과가 중대한 사항.","src":"공정거래법 제59조 제1항 제5호 | 기출 2023-25 | 기출 2026-23"},{"t":"전원회의 관장 6: 그 밖에 전원회의에서 스스로 처리하는 것이 필요하다고 인정하는 사항. 소회의는 전원회의 관장 사항 외의 사항을 심의·의결한다.","src":"공정거래법 제59조 제1항 제6호·제2항"},{"t":"전원회의: 위원장이 주재하며 재적위원 과반수의 찬성으로 의결한다. (현행 조문에는 별도의 출석 정족수가 없다.)","src":"공정거래법 제64조 제1항 | 기출 2022-22 | 기출 2023-25 | 기출 2024-23"},{"t":"소회의: 상임위원이 주재하며 구성위원 전원의 출석과 출석위원 전원의 찬성으로 의결한다.","src":"공정거래법 제64조 제2항 | 기출 2021-27 | 기출 2022-22 | 기출 2023-25 | 기출 2024-23 | 기출 2026-23"}]},{"머리":"심리·제척·의결서(제65조~제69조)","줄":[{"t":"심리와 의결은 공개한다. 다만 사업자 또는 사업자단체의 사업상 비밀을 보호할 필요가 있다고 인정할 때에는 공개하지 않는다.","src":"공정거래법 제65조 제1항 | 기출 2022-23 | 기출 2023-24"},{"t":"심리는 구술심리를 원칙으로 하되 필요한 경우 서면심리로 할 수 있다.","src":"공정거래법 제65조 제2항 | 기출 2023-24 | 기출 2026-23"},{"t":"의결의 합의는 공개하지 않는다.","src":"공정거래법 제65조 제3항"},{"t":"전원회의 및 소회의 의장은 심판정에 출석하는 당사자·이해관계인·참고인·참관인 등에게 질서유지를 위해 필요한 조치를 명할 수 있다. 따르지 않으면 100만원 이하의 과태료.","src":"공정거래법 제66조·제130조 제2항 | 기출 2021-27"},{"t":"제척 사유: ① 자기·배우자(였던 사람)가 당사자이거나 공동권리자·공동의무자인 사건, ② 자기가 당사자와 친족이거나 친족이었던 사건, ③ 자기 또는 자기가 속한 법인이 당사자의 법률·경영 등에 대한 자문·고문인 사건, ④ 증언·감정을 한 사건, ⑤ 당사자의 대리인으로 관여했거나 관여했던 사건, ⑥ 대상 처분·부작위에 관여한 사건, ⑦ 공정거래위원회 소속 공무원으로서 해당 사건을 조사·심사한 사건.","src":"공정거래법 제67조 제1항 | 기출 2022-23 | 기출 2026-23"},{"t":"기피: 당사자는 위원에게 심의·의결의 공정을 기대하기 어려운 사정이 있으면 기피신청을 할 수 있다. 위원장은 위원회 의결을 거치지 않고 기피 여부를 결정한다.","src":"공정거래법 제67조 제2항 | 기출 2022-23 | 기출 2023-24"},{"t":"회피: 위원 본인이 제척·기피 사유에 해당하면 스스로 심의·의결을 회피할 수 있다.","src":"공정거래법 제67조 제3항"},{"t":"의결서: 의결 내용 및 이유를 명시하고 의결에 참여한 위원이 서명날인한다.","src":"공정거래법 제68조 제1항"},{"t":"경정: 의결서 등에 오기, 계산착오, 그 밖에 유사한 오류가 명백한 경우 신청이나 직권으로 경정할 수 있다.","src":"공정거래법 제68조 제2항 | 기출 2021-27 | 기출 2022-23 | 기출 2023-24"},{"t":"판단 시점: 이 법 위반 의결은 심리를 종결하는 날까지 발생한 사실을 기초로 판단한다.","src":"공정거래법 제69조 | 기출 2022-23 | 기출 2023-24 | 기출 2025-21"}]}],"함정":[{"x":"소회의의 의사는 상임위원이 주재하며 구성위원 전원의 출석과 출석위원 과반수의 찬성으로 의결한다.","o":"소회의는 구성위원 전원의 출석과 출석위원 전원의 찬성으로 의결한다.","src":"공정거래법 제64조 제2항 | 기출 2021-27"},{"x":"공정거래위원회 소관의 고시의 해석적용에 관한 사항은 소회의에서 심의ㆍ의결한다.","o":"소관 법령이나 규칙·고시 등의 해석 적용에 관한 사항은 전원회의가 심의·의결한다.","src":"공정거래법 제59조 제1항 제1호 | 기출 2021-27"},{"x":"공정거래위원회는 의결서 등에 오기가 있는 것이 명백한 때에는 직권으로만 경정할 수 있다.","o":"신청이나 직권으로 경정할 수 있다.","src":"공정거래법 제68조 제2항 | 기출 2021-27"},{"x":"공정거래위원회의 위원장의 임기는 3년으로 하고, 연임할 수 없다.","o":"임기는 3년이며 한 차례만 연임할 수 있다.","src":"공정거래법 제61조 | 기출 2021-27"},{"x":"공정거래위원회 위원장과 다른 위원의 임기는 3년으로 하고, 연임할 수 없다.","o":"임기는 3년이며 한 차례만 연임할 수 있다.","src":"공정거래법 제61조 | 기출 2022-22"},{"x":"당사자는 공정거래위원회 위원에게 심의ㆍ의결의 공정을 기대하기 어려운 사정이 있다고 할지라도 기피신청을 할 수 없다.","o":"공정을 기대하기 어려운 사정이 있으면 기피신청을 할 수 있다.","src":"공정거래법 제67조 제2항 | 기출 2022-23"},{"x":"공정거래위원회의 심리와 의결은 비공개를 원칙으로 하고 공개를 예외로 한다.","o":"심리와 의결은 공개가 원칙이다. 사업상 비밀 보호가 필요하면 공개하지 않는다.","src":"공정거래법 제65조 제1항 | 기출 2022-23"},{"x":"의결서 등에 오기, 계산착오 또는 그 밖에 이와 유사한 오류가 있는 것이 명백한 경우에는 신청으로만 경정할 수 있다.","o":"신청이나 직권으로 경정할 수 있다.","src":"공정거래법 제68조 제2항 | 기출 2022-23"},{"x":"이 법에 위반되는 사항에 대하여 공정거래위원회가 의결하는 경우에는 그 사항에 관한 심리를 시작하는 날까지 발생한 사실을 기초로 판단한다.","o":"심리를 종결하는 날까지 발생한 사실을 기초로 판단한다.","src":"공정거래법 제69조 | 기출 2022-23"},{"x":"공정거래위원회의 심리는 서면심리를 원칙으로 하되, 필요하면 구술심리로 할 수 있다.","o":"구술심리가 원칙이고 필요한 경우 서면심리로 할 수 있다.","src":"공정거래법 제65조 제2항 | 기출 2023-24"},{"x":"소회의는 상임위원이 주재하며, 구성위원 과반수의 출석과 출석위원 전원의 찬성으로 의결한다.","o":"구성위원 전원의 출석과 출석위원 전원의 찬성으로 의결한다.","src":"공정거래법 제64조 제2항 | 기출 2023-25"},{"x":"공정거래위원회의 위원장, 부위원장 및 다른 위원의 임기는 3년으로 하고, 두 차례까지 연임할 수 있다.","o":"임기는 3년이며 한 차례만 연임할 수 있다.","src":"공정거래법 제61조 | 기출 2025-21"},{"x":"정부와 외국정부 사이에 협정이 체결되지 아니한 경우에는 공정거래위원회는 외국 정부의 법 집행요청이 있더라도 지원을 할 수 없다.","o":"협정이 없어도 요청국의 보증이 있으면 외국정부의 법집행을 지원할 수 있다.","src":"공정거래법 제56조 제3항 | 기출 2025-22"},{"x":"공정거래위원회의 심리는 서면심리를 원칙으로 하되, 필요한 경우 구술심리로 할 수 있다.","o":"구술심리가 원칙이다.","src":"공정거래법 제65조 제2항 | 기출 2026-23"},{"x":"위원장, 부위원장 및 다른 위원의 임기는 3년으로 하고, 연임할 수 없다.","o":"임기는 3년이며 한 차례만 연임할 수 있다.","src":"공정거래법 제61조 | 기출 2026-28"}]},"위반행위의 조사 등 절차":{"묶음":[{"머리":"인지·신고·처분 통지·시효(제80조)","줄":[{"t":"공정거래위원회는 이 법을 위반한 혐의가 있다고 인정할 때 직권으로 필요한 조사를 할 수 있다.","src":"공정거래법 제80조 제1항 | 기출 2021-23 | 기출 2023-28 | 기출 2025-25 | 기출 2026-24"},{"t":"누구든지 이 법에 위반되는 사실을 공정거래위원회에 신고할 수 있다. 이해관계자만 신고할 수 있는 것이 아니다.","src":"공정거래법 제80조 제2항 | 기출 2022-26 | 기출 2024-25 | 기출 2025-25"},{"t":"신고는 서면이 원칙이다. 긴급하거나 부득이한 사정이 있으면 전화 또는 구두로 신고할 수 있다.","src":"공정거래법 시행령 제71조 | 기출 2021-23 | 기출 2024-25 | 기출 2025-25"},{"t":"신고서 기재사항: 신고인의 성명·주소, 피신고인의 주소·대표자 성명·사업내용, 피신고인의 위반행위 내용, 그 밖에 위반행위를 명백히 할 사항.","src":"공정거래법 시행령 제71조"},{"t":"직권 조사 또는 신고로 조사한 결과 처분을 하거나 하지 않는 경우 그 근거·내용·사유 등을 기재한 서면(의결서를 작성하면 의결서 정본)을 당사자에게 통지하여야 한다.","src":"공정거래법 제80조 제3항 | 기출 2022-26 | 기출 2024-25 | 기출 2026-24"},{"t":"신고는 공정거래위원회의 직권 발동을 촉구하는 단서 제공에 불과하다.","src":"기출 2022-30"},{"t":"무혐의 처분은 헌법소원의 대상이 될 수 있다. 신고자는 무혐의 처분에 대해 이의신청이나 행정소송은 제기할 수 없다는 취지로 출제되었다.","src":"기출 2022-30 | 기출 2024-25"},{"t":"원칙적 시효: 위반행위 종료일부터 7년이 지나면 시정조치·과징금을 부과할 수 없다.","src":"공정거래법 제80조 제4항 | 기출 2022-26 | 기출 2025-25 | 기출 2026-24"},{"t":"부당한 공동행위 시효: 조사를 개시한 경우 조사 개시일부터 5년, 조사를 개시하지 않은 경우 위반행위 종료일부터 7년.","src":"공정거래법 제80조 제5항 | 기출 2021-23 | 기출 2022-26 | 기출 2023-28"},{"t":"법원 판결로 처분이 취소되어 판결이유에 따라 새로운 처분을 하는 경우에는 시효 제한을 적용하지 않는다.","src":"공정거래법 제80조 제6항"},{"t":"공정거래위원회가 자료의 열람·복사 요구를 거부해 당사자가 소를 제기하면 시효 진행이 정지되고 재판이 확정된 때부터 진행한다. 동의의결을 신청해도 진행이 정지된다.","src":"공정거래법 제80조 제7항·제90조 제10항"},{"t":"부당한 공동행위 조사 개시일: 직권조사는 처분·조사를 한 날 중 가장 빠른 날, 신고(자진신고 포함)로 개시하면 신고 접수일.","src":"공정거래법 시행령 제72조"}]},{"머리":"조사 방법·조사권 제한(제81조~제85조)","줄":[{"t":"제81조 제1항 처분 3가지: 당사자·이해관계인·참고인의 출석 및 의견 청취, 감정인 지정 및 감정 위촉, 사업자·사업자단체·임직원에게 원가·경영상황 보고와 자료·물건 제출 명령 또는 일시 보관.","src":"공정거래법 제81조 제1항 | 기출 2021-23"},{"t":"소속 공무원이 사업자·사업자단체의 사무소·사업장에 출입해 업무·경영상황, 장부·서류, 전산자료·음성녹음자료·화상자료 등을 조사할 수 있다.","src":"공정거래법 제81조 제2항"},{"t":"조사공무원은 자료나 물건의 제출을 명하거나 제출된 자료·물건을 일시 보관할 수 있다. 보관할 때는 보관조서를 작성·발급하고, 조사와 관련 없거나 보관할 필요가 없어지면 즉시 반환한다.","src":"공정거래법 제81조 제6항~제8항 | 기출 2022-27"},{"t":"조사공무원은 제59조의 심의·의결 절차가 진행 중이면 출입 조사나 진술청취를 해서는 안 된다. 다만 조사공무원 또는 당사자의 신청에 대해 전원회의 또는 소회의가 필요하다고 인정하면 할 수 있다.","src":"공정거래법 제81조 제4항 | 기출 2023-28"},{"t":"출석요구서에는 사건명, 출석하는 자의 성명, 출석일시·장소를 적어 발부한다.","src":"공정거래법 시행령 제73조 제1항 | 기출 2022-27"},{"t":"감정인 지정은 사건명, 감정인 성명, 감정의 목적 및 내용, 감정기간이 포함된 서면으로 한다.","src":"공정거래법 시행령 제73조 제2항 | 기출 2022-27"},{"t":"자료·물건 제출 명령은 사건명, 보고·제출 일시, 보고·제출할 사항이 포함된 서면으로 한다. 공정거래위원회 회의에 출석한 자에게는 구두로 할 수 있다.","src":"공정거래법 시행령 제73조 제3항"},{"t":"이해관계인·참고인을 출석하게 하거나 감정인을 위촉하면 예산 범위에서 필요한 경비를 지급할 수 있다.","src":"공정거래법 시행령 제74조 | 기출 2022-27"},{"t":"조사공무원은 지정된 장소에서 당사자 등의 진술을 들을 수 있다. 사업자·사업자단체의 사무소·사업장에 출입해 진술을 들으려면 그 사무소·사업장에서 들어야 한다.","src":"공정거래법 제81조 제3항 | 기출 2022-27"},{"t":"조사는 정규 근무시간 내에 진행한다. 증거인멸 우려 등으로 목적 달성이 불가능하면 피조사업체와 협의해 근무시간 외에도 할 수 있다. 조사기간 내에 종료하며 필요하면 연장할 수 있고 연장 시 공문서를 발급한다.","src":"공정거래법 제82조"},{"t":"공정거래위원회로부터 조사 및 심의를 받는 사업자·사업자단체·임직원은 변호사 등 변호인으로 하여금 조사 및 심의에 참여하게 하거나 의견을 진술하게 할 수 있다.","src":"공정거래법 제83조 | 기출 2022-30 | 기출 2023-28 | 기출 2025-25 | 기출 2026-24"},{"t":"조사공무원은 이 법 시행에 필요한 최소한의 범위에서 조사하여야 하며 다른 목적 등을 위해 조사권을 남용해서는 안 된다. 불가피한 경우에도 예외가 없다.","src":"공정거래법 제84조 | 기출 2023-28 | 기출 2025-25 | 기출 2026-24"},{"t":"조사 연기신청: 천재지변이나 그 밖에 대통령령으로 정하는 사유(예: 인수·합병 절차 진행)로 처분 이행이나 조사를 받기 곤란하면 연기를 신청할 수 있다. 공정거래위원회는 타당하면 연기할 수 있다.","src":"공정거래법 제85조 | 기출 2021-23"},{"t":"서면실태조사: 일정한 거래분야의 공정한 거래질서 확립을 위해 서면실태조사를 하고 결과를 공표할 수 있다. 조사계획을 수립하고, 자료제출 요구 시 자료의 범위·내용, 요구사유, 제출기한을 서면으로 밝힌다.","src":"공정거래법 제87조 | 기출 2023-27"},{"t":"사업자 등이 출석요구에 정당한 이유 없이 불응하면 1억원 이하(임원·종업원 등은 1천만원 이하)의 과태료.","src":"공정거래법 제130조 제1항 제6호"}]},{"머리":"시정권고(제88조)","줄":[{"t":"공정거래위원회는 이 법을 위반하는 행위가 있는 경우 사업자 또는 사업자단체에 시정방안을 정해 따를 것을 권고할 수 있다.","src":"공정거래법 제88조 제1항 | 기출 2023-27"},{"t":"권고를 받은 자는 통지받은 날부터 10일 이내에 수락 여부를 공정거래위원회에 통지하여야 한다.","src":"공정거래법 제88조 제2항"},{"t":"권고를 수락하면 이 법에 따른 시정조치가 명하여진 것으로 본다.","src":"공정거래법 제88조 제3항 | 기출 2023-27"},{"t":"시정권고 서면 기재사항: 법위반 내용, 권고사항, 시정기한, 수락여부 통지기한, 수락거부시의 조치. 이행강제금은 기재사항이 아니다. 동의의결 신청절차도 아니다.","src":"공정거래법 시행령 제78조 | 기출 2022-28 | 기출 2026-27"}]},{"머리":"동의의결(제89조~제92조)","줄":[{"t":"신청 주체: 공정거래위원회의 조사나 심의를 받고 있는 사업자 또는 사업자단체. 목적은 경쟁제한상태 등의 자발적 해소, 소비자 피해구제, 거래질서 개선.","src":"공정거래법 제89조 제1항 | 기출 2021-29 | 기출 2024-26 | 기출 2025-24"},{"t":"동의의결 없이 심의를 진행하는 경우: ① 해당 행위가 제40조 제1항(부당한 공동행위) 위반, ② 제129조 제2항 고발요건 해당, ③ 동의의결 전에 신청인이 신청을 취소.","src":"공정거래법 제89조 제1항 단서 | 기출 2023-27 | 기출 2024-26 | 기출 2026-25"},{"t":"신청은 해당 행위를 특정할 수 있는 사실관계, 해당 행위의 중지·원상회복 등 시정방안, 피해 구제·예방 시정방안을 기재한 서면으로 한다.","src":"공정거래법 제89조 제2항 | 기출 2025-24"},{"t":"공정거래위원회가 사실관계 조사를 마친 후 시정방안이 요건을 갖췄다고 판단하면 심의 절차를 중단하고 시정방안과 같은 취지로 의결할 수 있다. 시정방안은 신청인과 협의해 수정할 수 있다.","src":"공정거래법 제89조 제3항 | 기출 2024-26"},{"t":"동의의결 요건: ① 위반으로 판단될 경우 예상되는 시정조치 및 그 밖의 제재와 균형을 이룰 것, ② 경쟁질서·거래질서를 회복시키거나 소비자·다른 사업자 등을 보호하기에 적절할 것.","src":"공정거래법 제89조 제3항"},{"t":"동의의결은 해당 행위가 이 법에 위반된다고 인정한 것을 의미하지 않는다. 누구든 동의의결을 받은 사실을 들어 위반을 주장할 수 없다.","src":"공정거래법 제89조 제4항 | 기출 2024-26 | 기출 2026-25"},{"t":"공정거래위원회는 신속한 조치의 필요성, 소비자 피해의 직접 보상 필요성 등을 종합 고려해 절차 개시 여부를 결정한다(반드시 개시할 의무는 없다).","src":"공정거래법 제90조 제1항 | 기출 2023-27 | 기출 2025-24"},{"t":"의견수렴: 동의의결 전 30일 이상 기간을 정해 해당 행위의 개요, 관련 법령 조항, 시정방안, 이해를 돕는 정보를 신고인 등 이해관계인에게 통지하거나 관보·홈페이지에 공고해 의견을 제출할 기회를 준다.","src":"공정거래법 제90조 제2항 | 기출 2021-29"},{"t":"동의의결·취소는 전원회의 또는 소회의의 심의·의결을 거친다.","src":"공정거래법 제90조 제4항"},{"t":"신청인은 이행계획과 이행결과를 제출하여야 한다. 공정거래위원회는 이행 여부를 점검하고 자료 제출을 요청할 수 있다. 이행관리 업무는 한국공정거래조정원 또는 한국소비자원에 위탁할 수 있다.","src":"공정거래법 제90조 제5항~제7항 | 기출 2025-24 | 기출 2026-25"},{"t":"위탁받은 기관은 이행관리 현황을 분기별로 보고하고, 신청인이 이행을 게을리하면 지체 없이 통보한다.","src":"공정거래법 제90조 제8항·제9항"},{"t":"동의의결 취소 사유: ① 기초 사실관계의 현저한 변경 등으로 시정방안이 적정하지 않게 된 경우, ② 불완전·부정확한 정보 제공 또는 거짓·부정한 방법으로 받은 경우, ③ 정당한 이유 없이 이행하지 않는 경우.","src":"공정거래법 제91조 제1항 | 기출 2021-29 | 기출 2024-26 | 기출 2026-25"},{"t":"취소 후 효과: 제1호 사유로 취소하면 신청인이 다시 신청할 수 있다. 제2호·제3호 사유로 취소하면 중단된 심의절차를 계속 진행할 수 있다.","src":"공정거래법 제91조 제2항·제3항"},{"t":"동의의결 시 시정방안을 이행하지 않으면 제92조에 따라 이행강제금이 부과·징수될 수 있다는 사실을 서면으로 알려야 한다(구두 아님).","src":"공정거래법 시행령 제79조 | 기출 2025-24"},{"t":"동의의결 이행강제금: 정당한 이유 없이 이행기한까지 이행하지 않은 자에게 이행되거나 취소되기 전까지 이행기한 다음 날부터 1일당 200만원 이하.","src":"공정거래법 제92조 제1항"},{"t":"동의의결 이행계획의 이행 여부 점검과 이행 관련 자료 제출요청 업무는 한국공정거래조정원에 위탁한다.","src":"공정거래법 시행령 제80조 | 기출 2025-24"},{"t":"자료제출 명령 불이행 이행강제금: 소회의 결정으로 이행기한을 정해 다시 명령할 수 있고 불이행 시 1일 평균매출액의 1천분의 3 범위(매출액이 없거나 산정 곤란하면 1일 200만원 범위)에서 부과. 부과 가능 사실은 서면으로 알린다.","src":"공정거래법 제86조 제1항 | 공정거래법 시행령 제77조"}]},{"머리":"의견진술·증거조사·자료열람(제93조~제95조)","줄":[{"t":"시정조치를 명하거나 과징금을 부과하기 전에 당사자 또는 이해관계인에게 의견을 진술할 기회를 주어야 한다. 당사자는 회의에 출석해 의견을 진술하거나 자료를 제출할 수 있다.","src":"공정거래법 제93조 | 기출 2021-30 | 기출 2025-23"},{"t":"증거조사: 사건 심의에 필요하면 당사자의 신청이나 직권으로 할 수 있다. 증거조사 신청을 채택하지 않으면 의장이 그 이유를 당사자에게 고지한다.","src":"공정거래법 제94조 | 기출 2025-23"},{"t":"자료열람·복사 요구: 당사자 또는 신고인 등은 처분 관련 자료의 열람·복사를 요구할 수 있다. 영업비밀 자료, 자진신고 등 관련 자료, 다른 법률상 비공개 자료는 제외한다. 자료를 제출한 자의 동의 여부와 상관없이 모든 자료에 응해야 하는 것이 아니다.","src":"공정거래법 제95조 | 기출 2021-30"}]},{"머리":"이의신청·소제기·집행정지(제96조~제100조)","줄":[{"t":"이의신청: 처분의 통지를 받은 날부터 30일 이내에 그 사유를 갖추어 공정거래위원회에 한다.","src":"공정거래법 제96조 제1항 | 기출 2021-30 | 기출 2024-27 | 기출 2025-23"},{"t":"재결: 이의신청을 받은 날부터 60일 이내에 하여야 한다. 부득이한 사정이 있으면 30일의 범위에서 결정으로 연장할 수 있다.","src":"공정거래법 제96조 제2항 | 기출 2021-30 | 기출 2024-27 | 기출 2025-23"},{"t":"재결기간 연장 사유: 시장 범위·점유율 등 별도 경제적 분석 필요, 고도의 법리적 분석 필요, 새로운 주장·자료 제출로 장기 조사 필요, 당사자 등의 조사 비협조.","src":"공정거래법 시행령 제82조 제3항"},{"t":"이의신청 서류 보완에 걸리는 기간은 재결기간에 산입하지 않는다.","src":"공정거래법 시행령 제82조 제2항"},{"t":"집행정지: 시정조치를 받은 자가 이의신청을 제기한 경우 회복하기 어려운 손해를 예방하기 위해 필요하다고 인정하면 당사자 신청이나 직권으로 시정조치 이행·절차 계속 진행의 정지를 결정할 수 있다.","src":"공정거래법 제97조 제1항"},{"t":"불복의 소: 처분의 통지를 받은 날 또는 이의신청에 대한 재결서 정본을 송달받은 날부터 30일 이내에 제기. 이 기간은 불변기간.","src":"공정거래법 제99조 | 기출 2024-27"},{"t":"불복의 소는 서울고등법원을 전속관할로 한다. 행정법원이 아니다.","src":"공정거래법 제100조 | 기출 2024-27 | 기출 2026-35"},{"t":"시정조치 이행관리: 공정거래위원회는 시정조치 이행 여부를 점검하고 자료제출을 요구할 수 있으며 이행관리 업무를 조정원에 위탁할 수 있다.","src":"공정거래법 제97조의2"},{"t":"문서 송달은 행정절차법 제14조~제16조를 준용한다. 국외에 주소·영업소가 있는 사업자는 국내에 대리인을 지정하게 하여 송달한다.","src":"공정거래법 제98조"},{"t":"사건처리절차 등 필요한 사항은 공정거래위원회가 고시한다.","src":"공정거래법 제101조"}]}],"함정":[{"x":"이 법에 위반되는 사실이 인정되어 그 사실을 공정거래위원회에 신고할 때에는 반드 시 서면으로 제출하여야 한다.","o":"신고는 서면이 원칙이나 긴급하거나 부득이한 사정이 있으면 전화 또는 구두로 할 수 있다.","src":"공정거래법 시행령 제71조 | 기출 2021-23"},{"x":"공정거래위원회는 동의의결을 하기 전에 20일 이상의 기간을 정하여 해당 행위의 개요 등을 이해관계인에게 통지하여 의견을 제출할 기회를 주어야 한다.","o":"30일 이상의 기간을 정하여 의견을 제출할 기회를 주어야 한다.","src":"공정거래법 제90조 제2항 | 기출 2021-29"},{"x":"이해관계자만이 이 법에 위반되는 사실을 공정거래위원회에 신고할 수 있다.","o":"누구든지 신고할 수 있다.","src":"공정거래법 제80조 제2항 | 기출 2022-26"},{"x":"이 법 위반의 혐의가 있는 경우에 공정거래위원회는 당사자의 신고로만 필요한 조사를 할 수 있다.","o":"직권으로도 조사할 수 있다.","src":"공정거래법 제80조 제1항 | 기출 2022-26"},{"x":"공정거래위원회가 조사한 결과이 법에 따른 처분을 하지 아니하는 경우에는 그 근거 등을 기재한 서면을 해당 사건의 당사자에게 통지하지 아니한다.","o":"처분을 하지 않는 경우에도 근거·내용·사유 등을 기재한 서면을 당사자에게 통지하여야 한다.","src":"공정거래법 제80조 제3항 | 기출 2022-26"},{"x":"이 법 위반행위에 대하여 해당 위반행위의 종료일부터 5년이 지난 경우에는 이 법에 따른 시정조치를 명하거나 과징금을 부과할 수 없다.","o":"위반행위 종료일부터 7년이 지나면 시정조치·과징금을 부과할 수 없다.","src":"공정거래법 제80조 제4항 | 기출 2022-26"},{"x":"조사를 하는 공무원은 대통령령으로 정하는 바에 따라 사업자, 사업자단체 또는 이들의 임직원에게 조사에 필요한 자료나 물건의 제출을 명할 수 있으나 제출된 자료나 물건을 보관할 수는 없다.","o":"자료나 물건의 제출을 명하거나 제출된 자료·물건을 일시 보관할 수 있다.","src":"공정거래법 제81조 제6항 | 기출 2022-27"},{"x":"신청인이 동의의결을 신청한 경우 공정거래위원회는 동의의결 절차를 반드시 개시 하여야 한다.","o":"공정거래위원회는 개시 여부를 종합 고려해 결정한다. 반드시 개시하는 것이 아니다.","src":"공정거래법 제90조 제1항 | 기출 2023-27"},{"x":"공정거래위원회 전원회의의 심의·의결절차가 이미 진행 중인 경우 전원회의가 필요하 다고 인정하더라도, 조사공무원은 장소를 불문하고 이해관계인 또는 참고인의 진술을 들을 수 없다.","o":"조사공무원 또는 당사자의 신청에 대해 전원회의 또는 소회의가 필요하다고 인정하면 진술을 들을 수 있다.","src":"공정거래법 제81조 제4항 단서 | 기출 2023-28"},{"x":"공정거래위원회의 동의의결은 해당 행위가 이 법에 위반된다고 인정한 것을 의미한다.","o":"동의의결은 위반을 인정한 것을 의미하지 않는다.","src":"공정거래법 제89조 제4항 | 기출 2024-26"},{"x":"처분에 대한 불복의 소는 행정법원을 전속관할로 한다.","o":"불복의 소는 서울고등법원을 전속관할로 한다.","src":"공정거래법 제100조 | 기출 2024-27"},{"x":"공정거래위원회는 사건을 심의하기 위하여 필요하면 당사자의 신청으로 증거조사를 할 수 있으나 직권으로 증거조사를 진행할 수는 없다.","o":"당사자의 신청이나 직권으로 증거조사를 할 수 있다.","src":"공정거래법 제94조 제1항 | 기출 2025-23"},{"x":"공정거래위원회는 동의의결을 하는 경우에 동의의결된 시정방안을 이행하지 않으면 이행강제금이 부과·징수될 수 있다는 사실을 구두 또는 서면으로 알려야 한다.","o":"동의의결 시 이행강제금이 부과·징수될 수 있다는 사실을 서면으로 알려야 한다.","src":"공정거래법 시행령 제79조 | 기출 2025-24"},{"x":"누구든지 이 법에 위반되는 사실을 신고할 수 있고, 이 경우 그 신고는 서면을 통해 서만 신고할 수 있다.","o":"신고는 서면이 원칙이나 긴급·부득이한 경우 전화·구두로 할 수 있다.","src":"공정거래법 시행령 제71조 | 기출 2025-25"},{"x":"공정거래위원회는 이 법 위반행위에 대하여 3년이 지난 경우에는 시정조치를 명하거나 과징금을 부과할 수 없다.","o":"종료일부터 7년이 지나면 시정조치·과징금을 부과할 수 없다.","src":"공정거래법 제80조 제4항 | 기출 2025-25"},{"x":"조사공무원은 이 법의 시행을 위하여 필요한 최소한의 범위에서 조사를 하여야 하나, 불가피한 경우에는 다른 목적을 위하여도 조사권을 남용할 수 있다.","o":"조사권을 다른 목적으로 남용해서는 안 되며 불가피한 경우의 예외도 없다.","src":"공정거래법 제84조 | 기출 2025-25"},{"x":"공정거래위원회는 이 법을 위반한 혐의가 있다고 인정할 때에도 직권으로 조사를 개시할 수 없다.","o":"직권으로 필요한 조사를 할 수 있다.","src":"공정거래법 제80조 제1항 | 기출 2025-25"},{"x":"공정거래위원회는 이 법 위반행위에 대하여 해당 위반행위의 종료일부터 3년이 지난 경우에는 이 법에 따른 시정조치를 명하거나 과징금을 부과할 수 없다.","o":"종료일부터 7년이 지난 경우 시정조치·과징금을 부과할 수 없다.","src":"공정거래법 제80조 제4항 | 기출 2026-24"},{"x":"부당한 공동행위를 이유로 공정거래위원회의 조사를 받는 사업자가 공정거래위원회에 동의의결을 신청한 경우 공정거래위원회는 심의절차를 중지하고 동의의결을 할 수 있다.","o":"부당한 공동행위는 동의의결 대상이 아니다.","src":"공정거래법 제89조 제1항 제1호 | 기출 2026-25"}]},"과징금":{"묶음":[{"머리":"부과 시 고려사항·승계(제102조)","줄":[{"t":"과징금 부과 시 고려사항: ① 위반행위의 내용 및 정도, ② 위반행위의 기간 및 횟수, ③ 위반행위로 취득한 이익의 규모 등.","src":"공정거래법 제102조 제1항 | 기출 2021-24 | 기출 2023-30 | 기출 2025-26 | 기출 2026-26"},{"t":"고려사항이 아닌 것: 국내·외 법인 여부, 사업자의 매출액 규모, 사업자의 재산상태(손해배상액 산정 고려사항과 구별).","src":"공정거래법 제102조 제1항 | 기출 2025-26"},{"t":"합병으로 소멸한 회사의 위반행위는 합병 후 존속하거나 합병으로 설립된 회사의 행위로 보아 과징금을 부과·징수할 수 있다.","src":"공정거래법 제102조 제2항 | 기출 2022-29 | 기출 2024-28 | 기출 2026-26"},{"t":"분할·분할합병된 경우 분할일 이전 위반행위를 분할되는 회사, 분할·분할합병으로 설립되는 새로운 회사, 분할되는 회사의 일부를 합병하여 존속하는 다른 회사 중 어느 하나의 행위로 보고 과징금을 부과·징수할 수 있다.","src":"공정거래법 제102조 제3항 | 기출 2023-30 | 기출 2024-28"},{"t":"채무자회생법 제215조에 따라 새로운 회사를 설립하는 경우 기존 회사 또는 새로운 회사 중 어느 하나의 행위로 보고 과징금을 부과·징수할 수 있다.","src":"공정거래법 제102조 제4항 | 기출 2022-29"},{"t":"과징금 부과기준은 대통령령으로 정한다.","src":"공정거래법 제102조 제5항"},{"t":"분할·분할합병되는 경우(부과일에 분할·분할합병되는 경우 포함) 과징금은 분할되는 회사, 분할로 설립되는 회사, 분할되는 회사의 일부를 합병하여 존속하는 회사가 연대하여 납부할 책임을 진다. 분할로 해산되는 경우에는 설립되는 회사 등이 연대 책임.","src":"공정거래법 제104조 | 기출 2023-30 | 기출 2024-28"}]},{"머리":"유형별 과징금 한도 정리","줄":[{"t":"시장지배적지위 남용: 매출액 100분의 6, 매출액 없으면 20억원.","src":"공정거래법 제8조"},{"t":"부당한 공동행위: 매출액 100분의 20, 매출액 없으면 40억원.","src":"공정거래법 제43조 | 기출 2022-10 | 기출 2023-10 | 기출 2026-9"},{"t":"불공정거래행위(제9호 제외)·재판매가격유지·보복조치: 매출액 100분의 4, 매출액 없으면 10억원.","src":"공정거래법 제50조 제1항 | 기출 2023-20 | 기출 2025-11"},{"t":"부당한 지원행위(제45조 제1항 제9호)·지원받는 행위·특수관계인에 대한 부당한 이익제공: 평균매출액 100분의 10, 매출액 없으면 40억원.","src":"공정거래법 제50조 제2항 | 기출 2026-18"},{"t":"사업자단체 금지행위 위반: 사업자단체에 10억원의 범위. 제1호 위반 참가 사업자는 100분의 20(40억원), 제2~4호 위반 참가 사업자는 100분의 10(20억원).","src":"공정거래법 제53조"},{"t":"관련매출액: 위반기간 동안 일정한 거래분야에서 판매한 관련 상품·용역의 매출액. 입찰담합 및 유사 행위는 계약금액.","src":"공정거래법 시행령 제13조 제1항·제50조"},{"t":"부당한 지원행위 등의 매출액은 해당 사업자의 직전 3개 사업연도 평균 매출액이다. 사업 개시 후 3년이 안 된 경우는 환산한다.","src":"공정거래법 시행령 제56조 제2항"}]},{"머리":"납부기한의 연기·분할납부(제103조, 시행령 제86조)","줄":[{"t":"요건: 과징금 금액이 대통령령 기준(관련 매출액의 100분의 1 또는 10억원)을 초과하고, 아래 사유로 전액 일시 납부가 어렵다고 인정될 때. 필요하면 담보를 제공하게 할 수 있다.","src":"공정거래법 제103조 제1항 | 공정거래법 시행령 제86조 제1항"},{"t":"사유: ① 재해 또는 도난 등으로 재산에 현저한 손실이 생긴 경우, ② 사업여건 악화로 사업이 중대한 위기에 처한 경우, ③ 일시납부로 자금사정에 현저한 어려움이 예상되는 경우, ④ 이에 준하는 사유.","src":"공정거래법 제103조 제1항"},{"t":"연기·분할납부는 할 수 있는 재량이다. 허용하여야 하는 것이 아니다.","src":"공정거래법 제103조 제1항 | 기출 2021-24"},{"t":"신청 기한: 과징금 납부를 통지받은 날부터 30일 이내에 공정거래위원회에 신청.","src":"공정거래법 제103조 제2항 | 기출 2023-30 | 기출 2024-28 | 기출 2026-26"},{"t":"납부기한 연기는 납부기한 다음 날부터 2년을 초과할 수 없다. 분할납부 기한 간격은 6개월 이하, 분할 횟수는 6회 이하.","src":"공정거래법 시행령 제86조 제2항·제3항"},{"t":"제3호 사유 고려: 직전 3개 사업연도 연속 당기순손실 여부, 자본총액의 2배 초과 부채 보유 여부, 그 밖에 고시하는 사항.","src":"공정거래법 시행령 제86조 제4항"},{"t":"취소·일시징수 사유: ① 분할납부 결정된 과징금을 기한까지 납부하지 않은 경우, ② 담보 변경·보전 명령 불이행, ③ 강제집행·경매 개시·파산선고·법인 해산·체납처분 등으로 징수 불가능하다고 인정되는 경우, ④ 사유가 해소되어 일시 납부할 수 있다고 인정되는 경우.","src":"공정거래법 제103조 제3항 | 기출 2023-30 | 기출 2026-26"}]},{"머리":"징수·체납처분·결손처분(제105조~제107조)","줄":[{"t":"가산금: 납부기한 다음 날부터 납부한 날까지 연 100분의 40의 범위에서 은행 연체이자율을 고려해 징수. 가산금 징수 기간은 60개월 상한.","src":"공정거래법 제105조 제1항"},{"t":"독촉 후에도 납부하지 않으면 국세체납처분의 예에 따라 징수할 수 있다. 징수·체납처분 업무는 국세청장에게 위탁할 수 있다.","src":"공정거래법 제105조 제2항·제3항 | 기출 2026-26"},{"t":"체납된 과징금 징수를 위해 필요하다고 인정하면 국세청장에게 체납자의 국세과세정보 제공을 요청할 수 있다(요청하여야 하는 것이 아니다).","src":"공정거래법 제105조 제4항 | 기출 2021-24 | 기출 2022-29"},{"t":"환급: 이의신청 재결 또는 법원 판결 등으로 환급하면 납부한 날부터 환급한 날까지 환급가산금을 지급하여야 한다.","src":"공정거래법 제106조"},{"t":"결손처분 사유 1: 체납처분이 끝나고 체납액에 충당된 배분금액이 체납액에 미치지 못하는 경우.","src":"공정거래법 제107조 제1항 제1호 | 기출 2023-22 | 기출 2025-30"},{"t":"결손처분 사유 2: 징수금등의 징수권에 대한 소멸시효가 완성된 경우.","src":"공정거래법 제107조 제1항 제2호 | 기출 2022-29 | 기출 2023-22 | 기출 2025-30"},{"t":"결손처분 사유 3: 체납자의 행방이 분명하지 않거나 재산이 없다는 것이 판명된 경우.","src":"공정거래법 제107조 제1항 제3호 | 기출 2021-24 | 기출 2025-30"},{"t":"결손처분 사유 4: 체납처분 목적물인 총재산의 추산가액이 체납처분비에 충당하고 남을 여지가 없음이 확인된 경우.","src":"공정거래법 제107조 제1항 제4호 | 기출 2023-22 | 기출 2025-30"},{"t":"결손처분 사유 5: 총재산이 징수금등보다 우선하는 국세·지방세·전세권·질권·저당권 담보채권 등의 변제에 충당하고 남을 여지가 없음이 확인된 경우.","src":"공정거래법 제107조 제1항 제5호 | 기출 2023-22"},{"t":"결손처분 사유 6: 징수할 가능성이 없는 경우로서 대통령령으로 정하는 사유. '체납자가 국외로 이주하여 해외 소재지가 확인된 경우'는 사유로 규정되어 있지 않다.","src":"공정거래법 제107조 제1항 제6호 | 기출 2023-22"},{"t":"결손처분은 '할 수 있다'. 사유가 있어도 하여야 하는 것이 아니다. 징수권 소멸시효가 완성되지 않은 경우(기출 ㄴ)는 사유가 아니다.","src":"공정거래법 제107조 제1항 | 기출 2021-24 | 기출 2025-30"},{"t":"결손처분 시 지방행정기관 등에 체납자 행방·재산 유무를 조사·확인하여야 한다. 제4호·제5호 사유로 결손처분하면 체납처분을 중지하고 압류를 해제한다.","src":"공정거래법 제107조 제2항·제3항"},{"t":"결손처분 후 압류할 수 있는 다른 재산을 발견하면 지체 없이 결손처분을 취소하고 체납처분을 하여야 한다. 다만 소멸시효 완성(제2호)으로 결손처분한 경우에는 취소하지 않는다.","src":"공정거래법 제107조 제4항 | 기출 2021-24"}]}],"함정":[{"x":"공정거래위원회는 체납된 과징금의 징수를 위하여 필요하다고 인정되는 경우에는 국세청장에 대하여 과징금을 체납한 자에 대한 국세과세에 관한 정보의 제공을 요청하 여야 한다.","o":"국세청장에게 국세과세정보 제공을 요청할 수 있다(재량).","src":"공정거래법 제105조 제4항 | 기출 2021-24"},{"x":"공정거래위원회는 과징금의 납부의무자의 재산이 없다는 것이 판명된 경우 결손처분 을 하여야 한다.","o":"재산이 없다는 것이 판명되면 결손처분을 할 수 있다(재량).","src":"공정거래법 제107조 제1항 제3호 | 기출 2021-24"},{"x":"징수금등의 징수권에 대한 소멸시효가 완성된 경우에도 공정거래위원회는 과징금의 납부의무자에 대한 결손처분을 한 후 압류할 수 있는 다른 재산을 발견한 때에는 지체 없이 결손처분을 취소하고 체납처분을 하여야 한다.","o":"소멸시효 완성으로 결손처분한 경우에는 다른 재산을 발견해도 결손처분을 취소하지 않는다.","src":"공정거래법 제107조 제4항 단서 | 기출 2021-24"},{"x":"공정거래위원회는 도난으로 재산에 현저한 손실이 발생하여 과징금을 부과받은 자가 과징금의 전액을 일시에 납부하기가 어렵다고 인정되는 때에는 그 납부기한을 연장하 거나 분할납부하게 하여야 한다.","o":"납부기한을 연기하거나 분할납부하게 할 수 있다(재량).","src":"공정거래법 제103조 제1항 | 기출 2021-24"},{"x":"과징금납부의무자는 과징금 납부기한의 연기 또는 분할납부를 신청할 수 없다.","o":"과징금 납부기한 연기 또는 분할납부를 신청할 수 있다.","src":"공정거래법 제103조 | 기출 2022-29"},{"x":"분할납부가 허용된 과징금납부의무자가 그 사유가 해소되어 과징금을 일시에 납부할 수 있다고 인정되는 경우에도, 공정거래위원회는 분할납부 결정을 취소하고 일시에 징수할 수 없다.","o":"사유가 해소되어 일시 납부가 가능하다고 인정되면 분할납부 결정을 취소하고 일시에 징수할 수 있다.","src":"공정거래법 제103조 제3항 제4호 | 기출 2023-30"},{"x":"과징금납부의무자가 그 부과된 과징금 납부기한의 연기를 신청하려는 경우에는 과징 금 납부를 통지받은 날부터 60일 이내에 공정거래위원회에 신청하여야 한다.","o":"과징금 납부를 통지받은 날부터 30일 이내에 신청하여야 한다.","src":"공정거래법 제103조 제2항 | 기출 2024-28"}]},"손해배상 및 벌칙":{"묶음":[{"머리":"손해배상책임(제109조)","줄":[{"t":"일반 손해배상: 사업자·사업자단체는 이 법을 위반하여 피해를 입은 자에게 손해배상 책임을 진다. 고의 또는 과실이 없음을 입증하면 면책된다. 입증책임은 가해 사업자에게 있다.","src":"공정거래법 제109조 제1항 | 기출 2023-21 | 기출 2024-29 | 기출 2025-27"},{"t":"3배 배상 대상: 제40조(부당한 공동행위), 제48조(보복조치), 제51조 제1항 제1호(사업자단체의 공동행위 방식 경쟁제한) 위반. 손해의 3배를 넘지 않는 범위에서 책임. 고의·과실 없음을 입증하면 면책.","src":"공정거래법 제109조 제2항 | 기출 2021-25 | 기출 2024-29"},{"t":"자진신고·조사협조 감면 사업자는 배상액이 제40조 위반으로 손해를 입은 자에게 발생한 손해를 초과할 수 없다. 이때 다른 사업자와 공동불법행위자(민법 제760조)로서 그 범위에서 책임진다.","src":"공정거래법 제109조 제2항 단서·제4항 | 기출 2024-29"},{"t":"배상액 고려사항: ① 고의 또는 손해 발생의 우려를 인식한 정도, ② 위반행위로 인한 피해 규모, ③ 위반행위로 취득한 경제적 이익, ④ 위반행위에 따른 벌금 및 과징금, ⑤ 위반행위의 기간·횟수 등, ⑥ 사업자의 재산상태, ⑦ 사업자·사업자단체의 피해구제 노력의 정도.","src":"공정거래법 제109조 제3항 | 기출 2021-25 | 기출 2023-23 | 기출 2025-27 | 기출 2026-22"},{"t":"고려사항이 아닌 것: 시장지배적 사업자인지 여부, 피해자의 재산상태.","src":"공정거래법 제109조 제3항 | 기출 2021-25 | 기출 2023-23 | 기출 2026-22"},{"t":"손해배상소송에서 법원은 공정거래위원회에 사건기록(심문조서, 속기록, 그 밖의 재판상 증거 일체)의 송부를 요구할 수 있다.","src":"공정거래법 제110조 | 기출 2023-21 | 기출 2024-29 | 기출 2025-27"},{"t":"자료제출: 법원은 제40조 제1항, 제45조 제1항(제9호 제외), 제51조 제1항 제1호 위반 손해배상소송에서 당사자 신청으로 상대방에게 손해 증명·손해액 산정에 필요한 자료(자진신고 관련 자료 제외) 제출을 명할 수 있다.","src":"공정거래법 제111조 제1항"},{"t":"정당한 이유 없이 자료제출명령에 따르지 않으면 법원은 자료 기재에 대한 상대방의 주장을 진실한 것으로 인정할 수 있다. 영업비밀이라도 손해 증명에 반드시 필요하면 제출 거절의 정당한 이유로 보지 않는다.","src":"공정거래법 제111조 제3항·제4항 | 기출 2023-21 | 기출 2024-29"},{"t":"손해액 인정: 손해 발생은 인정되나 손해액 입증이 사실의 성질상 매우 곤란하면 변론 전체의 취지와 증거조사 결과에 기초해 상당한 손해액을 인정할 수 있다.","src":"공정거래법 제115조 | 기출 2024-29"}]},{"머리":"비밀유지명령(제112조~제114조)","줄":[{"t":"법원은 손해배상소송에서 당사자가 보유한 영업비밀에 대해 신청이 있으면 결정으로 상대방 당사자, 소송대리인 등에게 소송 수행 외 목적 사용·공개를 금지하는 비밀유지명령을 내릴 수 있다. 신청은 서면으로 한다.","src":"공정거래법 제112조 제1항·제2항"},{"t":"비밀유지명령은 결정서가 명령을 받을 자에게 송달된 때부터 효력이 발생한다.","src":"공정거래법 제112조 제4항"},{"t":"비밀유지명령 신청을 기각·각하한 재판에 대해서는 즉시항고를 할 수 있다.","src":"공정거래법 제112조 제5항"},{"t":"비밀유지명령 취소: 신청인 또는 명령을 받은 자가 요건을 갖추지 못했거나 못하게 된 경우 소송기록 보관 법원에 취소를 신청할 수 있다. 취소신청에 대한 재판에 대해서도 즉시항고를 할 수 있고, 취소 재판은 확정되어야 효력이 발생한다.","src":"공정거래법 제113조 | 기출 2025-27"},{"t":"비밀유지명령 위반: 2년 이하의 징역 또는 2천만원 이하의 벌금. 신청한 자의 고소가 있어야 공소 제기 가능.","src":"공정거래법 제127조 제1항·제2항"},{"t":"비밀유지명령이 내려진 소송기록의 비밀 기재부분 열람 청구가 명령 받지 않은 자에 의해 이루어지면 법원사무관등은 신청한 당사자에게 그 사실을 알리고, 청구일부터 2주일이 지날 때까지 열람하게 해서는 안 된다.","src":"공정거래법 제114조"}]},{"머리":"벌칙(제124조~제128조)","줄":[{"t":"제124조(3년 이하의 징역 또는 2억원 이하의 벌금): 남용행위, 탈법행위, 의결권 행사 위반, 지주회사 규정 위반, 상호출자·순환출자 위반, 채무보증 위반, 부당한 공동행위, 부당한 지원행위(제45조 제1항 제9호)·특수관계인 이익제공, 보복조치, 사업자단체의 제51조 제1항 제1호 위반, 폭언·폭행 등으로 조사를 거부·방해·기피한 자.","src":"공정거래법 제124조 제1항"},{"t":"징역형과 벌금형은 병과할 수 있다.","src":"공정거래법 제124조 제2항 | 기출 2025-8"},{"t":"제125조(2년 이하의 징역 또는 1억5천만원 이하의 벌금): 시정조치 불이행, 일정 자료제출 거부·허위, 공인회계사 감사 미수감, 제45조 제1항 위반 불공정거래행위(제1·2·3·7·9호 제외), 사업자단체의 제51조 제1항 제3호 위반, 제81조 제1항 제3호·제6항 보고·자료제출 위반, 자료 은닉·폐기·위조 등 조사 방해.","src":"공정거래법 제125조"},{"t":"제126조(1억원 이하의 벌금): 지주회사 설립·전환 신고 미이행·허위, 지주회사 사업내용 보고서 미제출, 주식소유·채무보증 현황 신고 미이행·허위, 거짓 감정.","src":"공정거래법 제126조"},{"t":"제127조: 비밀유지명령 위반 2년 이하의 징역 또는 2천만원 이하의 벌금, 제119조 비밀엄수 위반 2년 이하의 징역 또는 200만원 이하의 벌금.","src":"공정거래법 제127조"},{"t":"양벌규정: 법인의 대표자, 법인 또는 개인의 대리인·사용인·종업원이 업무에 관해 제124조~제126조 위반을 하면 행위자를 벌하는 외에 법인 또는 개인에게도 벌금형을 과한다. 상당한 주의와 감독을 게을리하지 않았다면 제외.","src":"공정거래법 제128조 | 기출 2026-2"},{"t":"과태료(제130조): 사업자·사업자단체 등 1억원 이하, 임원·종업원·이해관계인 1천만원 이하(기업결합 신고 위반, 공시 위반, 출석요구 불응, 서면실태조사 자료 미제출 등). 심판정 질서유지 명령 불이행은 100만원 이하.","src":"공정거래법 제130조"}]},{"머리":"고발(제129조)","줄":[{"t":"제124조·제125조의 죄는 공정거래위원회의 고발이 있어야 공소를 제기할 수 있다(전속고발). 시장지배적지위 남용도 같다.","src":"공정거래법 제129조 제1항 | 기출 2021-26 | 기출 2024-30"},{"t":"위반의 정도가 객관적으로 명백하고 중대하여 경쟁질서를 현저히 해친다고 인정하면 공정거래위원회는 고발하여야 한다. (현행 중대범죄수사청장에게 고발, 기출 당시 검찰총장)","src":"공정거래법 제129조 제2항 | 기출 2021-26 | 기출 2024-30"},{"t":"검찰총장·중대범죄수사청장은 고발요건에 해당하는 사실을 통보하고 고발을 요청할 수 있다.","src":"공정거래법 제129조 제3항 | 기출 2024-30"},{"t":"공정거래위원회가 고발요건에 해당하지 않는다고 결정해도 감사원장, 중소벤처기업부장관, 조달청장은 사회적 파급효과, 국가재정 영향, 중소기업 피해 정도 등을 이유로 고발을 요청할 수 있다. 기획재정부장관은 포함되지 않는다.","src":"공정거래법 제129조 제4항 | 기출 2021-26 | 기출 2024-30"},{"t":"제3항 또는 제4항의 고발요청이 있으면 공정거래위원회는 고발하여야 한다.","src":"공정거래법 제129조 제5항 | 기출 2024-30"},{"t":"공정거래위원회는 공소가 제기된 후에는 고발을 취소할 수 없다. 상황 변화를 이유로도 불가능.","src":"공정거래법 제129조 제6항 | 기출 2021-26 | 기출 2024-30"},{"t":"중소벤처기업부장관은 직접 검찰총장에게 고발할 수 없고 공정거래위원회에 고발을 요청할 수 있을 뿐이다.","src":"공정거래법 제129조 제4항 | 기출 2021-26"}]}],"함정":[{"x":"해당 피해자가 사업자의 고의 또는 중과실이 있음을 입증한 경우에 한하여 사업자는 그 피해자에 대하여 손해배상의 책임을 진다.","o":"사업자가 고의·과실 없음을 입증하지 못하면 책임을 진다. 입증책임은 사업자에게 있다.","src":"공정거래법 제109조 제1항 | 기출 2023-21"},{"x":"이 법 위반행위로 인해 피해를 입은 자가 손해배상청구소송을 제기한 경우 그 피해를 입은 자는 사업자의 고의 또는 과실을 입증할 책임을 진다.","o":"사업자가 고의·과실 없음을 입증하여야 한다. 피해자가 입증책임을 지지 않는다.","src":"공정거래법 제109조 제1항 | 기출 2024-29"},{"x":"사업자 또는 사업자단체는 어떠한 경우에도 이 법 위반행위로 손해를 입은 자에게 손해액 이상의 배상책임을 부담하지 아니한다.","o":"부당한 공동행위 등은 손해의 3배를 넘지 않는 범위에서 손해액 이상의 배상책임을 질 수 있다.","src":"공정거래법 제109조 제2항 | 기출 2025-27"},{"x":"법원은 이 법제109조 제2항에 따른 배상액을 정할 때에는 위반행위에 따른 벌금 및 과징금을 고려하지 아니한다.","o":"벌금 및 과징금을 고려하여야 한다.","src":"공정거래법 제109조 제3항 제4호 | 기출 2025-27"},{"x":"비밀유지명령의 취소신청에 대한 재판에 대해서는 즉시항고를 할 수 없다.","o":"비밀유지명령 취소신청에 대한 재판에도 즉시항고를 할 수 있다.","src":"공정거래법 제113조 제3항 | 기출 2025-27"},{"x":"사업자 또는 사업자단체는 이 법을 위반하여 피해를 입은 자가 있는 경우, 고의 또는 과실이 없음을 입증한 경우에도 손해배상책임을 부담한다.","o":"고의·과실이 없음을 입증하면 손해배상책임을 지지 않는다.","src":"공정거래법 제109조 | 기출 2025-27"}]},"공정거래분쟁조정협의회":{"묶음":[{"머리":"설치·구성(제72조·제73조)","줄":[{"t":"한국공정거래조정원 업무: 제45조 제1항 위반 혐의 행위 관련 분쟁 조정, 다른 법률상 분쟁 조정, 시장·산업 동향과 공정경쟁 조사·분석, 사업자 거래관행 조사·분석, 동의의결 이행관리, 시정조치 이행관리, 제도·정책 연구·건의, 위탁받은 사업.","src":"공정거래법 제72조 제1항"},{"t":"조정원은 법인이다. 조정원의 장은 공정거래위원회 위원장이 임명한다.","src":"공정거래법 제72조 제2항·제3항"},{"t":"제45조 제1항을 위반한 혐의가 있는 행위와 관련된 분쟁을 조정하기 위해 조정원에 공정거래분쟁조정협의회를 둔다.","src":"공정거래법 제73조 제1항 | 기출 2023-26 | 기출 2025-29"},{"t":"협의회는 위원장 1명을 포함하여 9명 이내의 위원으로 구성한다. 위원장은 상임이다.","src":"공정거래법 제73조 제2항 | 기출 2025-29 | 기출 2026-30"},{"t":"위원장은 위원 중에서 조정원의 장의 제청으로 공정거래위원회 위원장이 위촉한다.","src":"공정거래법 제73조 제3항 | 기출 2025-29"},{"t":"위원은 조정원의 장의 제청으로 공정거래위원회 위원장이 임명하거나 위촉한다. 부위원장 직은 규정에 없다.","src":"공정거래법 제73조 제4항 | 기출 2026-30"},{"t":"위원 자격: 4급 이상 공무원 경력자, 판사·검사·변호사 7년 이상, 법률·경제·경영·소비자 분야 전공 부교수 이상으로 7년 이상 근무한 사람, 기업경영·소비자보호·분쟁조정 활동 7년 이상 종사자. 이 중 한 부류 이상이 1명 이상 포함되어야 한다.","src":"공정거래법 제73조 제4항 | 공정거래법 시행령 제63조"},{"t":"위원의 임기는 3년이다. 결원 시 보궐위원을 위촉하며 임기는 전임자의 남은 임기.","src":"공정거래법 제73조 제5항·제6항 | 기출 2023-26 | 기출 2025-29 | 기출 2026-30"},{"t":"공정거래위원회 위원장은 위원이 직무 관련 비위, 직무태만, 품위손상 등으로 적합하지 않다고 인정하면 해임 또는 해촉할 수 있다(협의회 위원장의 권한이 아니다).","src":"공정거래법 제73조 제7항 | 기출 2026-30"},{"t":"협의회 위원장은 직무 외에 영리를 목적으로 하는 업무에 종사하지 못한다. 공정거래위원회 위원장의 심사를 거쳐 비영리 업무를 겸할 수 있다.","src":"공정거래법 제73조 제8항~제10항 | 기출 2025-29"},{"t":"위원장은 회의를 소집하고 의장이 된다. 위원장이 직무를 수행할 수 없으면 공정거래위원회 위원장이 지명하는 위원이 대행한다.","src":"공정거래법 제74조 제1항·제3항 | 기출 2026-30"}]},{"머리":"회의(제74조·제75조, 시행령 제64조)","줄":[{"t":"협의회는 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다.","src":"공정거래법 제74조 제2항 | 기출 2023-26 | 기출 2026-30"},{"t":"조정 대상 분쟁의 당사자인 사업자는 협의회에 출석하여 의견을 진술할 수 있다.","src":"공정거래법 제74조 제4항 | 기출 2023-26"},{"t":"회의 소집은 개최 7일 전까지 일시·장소·안건을 서면으로 알린다(긴급·부득이한 경우 예외). 회의는 비공개이나 위원장이 필요하다고 인정하면 분쟁당사자·이해관계인에게 공개할 수 있다.","src":"공정거래법 시행령 제64조"},{"t":"제척 사유: 자기·배우자(였던 사람)가 분쟁당사자이거나 공동권리자·의무자, 분쟁당사자와 친족, 자문·고문, 증언·감정, 대리인 관여.","src":"공정거래법 제75조 제1항"},{"t":"분쟁당사자는 공정을 기하기 어려운 사정이 있으면 협의회에 기피신청을 할 수 있다. 위원 본인은 스스로 회피할 수 있다.","src":"공정거래법 제75조 제2항·제3항"}]},{"머리":"조정 신청(제76조)","줄":[{"t":"신청 주체: 제45조 제1항을 위반한 혐의가 있는 행위로 피해를 입은 사업자가 분쟁조정신청서를 협의회에 제출.","src":"공정거래법 제76조 제1항 | 기출 2022-24 | 기출 2024-24"},{"t":"신청서 기재: 분쟁당사자 성명·주소, 조정 신청의 취지와 이유, 대리인, 소송사건번호(소가 제기된 경우). 첨부: 원인과 사실 증명서류, 위임장, 증거서류.","src":"공정거래법 시행령 제65조 제1항·제2항"},{"t":"공정거래위원회는 제80조 제2항에 따른 신고가 접수된 경우 협의회에 그 행위 또는 사건의 분쟁조정을 의뢰할 수 있다.","src":"공정거래법 제76조 제2항 | 기출 2024-24"},{"t":"협의회는 신청·의뢰를 받으면 즉시 접수사실 등을 공정거래위원회 및 분쟁당사자에게 통지하여야 한다.","src":"공정거래법 제76조 제3항 | 기출 2026-29"},{"t":"시효중단: 분쟁조정의 신청은 시효중단의 효력이 있다. 다만 신청이 취하되거나 각하된 경우에는 없다.","src":"공정거래법 제76조 제4항 | 기출 2022-24 | 기출 2026-29"},{"t":"취하·각하된 경우 6개월 내에 재판상 청구, 파산절차 참가, 압류·가압류, 가처분을 하면 시효는 최초의 분쟁조정 신청으로 중단된 것으로 본다. 재판상 청구 시점이 아니다.","src":"공정거래법 제76조 제5항 | 기출 2022-24 | 기출 2024-24"},{"t":"중단된 시효는 조정조서를 작성한 때 또는 조정이 이루어지지 않고 절차가 종료된 때부터 새로 진행한다.","src":"공정거래법 제76조 제6항 | 기출 2022-24"},{"t":"협의회는 신청의 보완이 필요하면 상당한 기간을 정해 요구할 수 있다. 보완 기간은 60일 기간에 산입하지 않는다.","src":"공정거래법 시행령 제65조 제5항"}]},{"머리":"조정 절차·각하·종료(제77조·제77조의2)","줄":[{"t":"협의회는 분쟁당사자에게 스스로 합의하도록 권고하거나 조정안을 작성하여 제시할 수 있다.","src":"공정거래법 제77조 제1항 | 기출 2022-25 | 기출 2024-24"},{"t":"협의회는 사실 확인을 위해 필요하면 조사를 하거나 분쟁당사자에게 자료 제출이나 출석을 요구할 수 있다.","src":"공정거래법 제77조 제2항 | 기출 2022-25"},{"t":"각하 사유 1: 조정신청 내용과 직접적인 이해관계가 없는 자가 신청한 경우. 기각이 아니라 각하다.","src":"공정거래법 제77조 제3항 제1호 | 기출 2021-22 | 기출 2022-25 | 기출 2026-29"},{"t":"각하 사유 2: 이 법의 적용대상이 아닌 사안에 관해 신청한 경우.","src":"공정거래법 제77조 제3항 제2호 | 기출 2021-22"},{"t":"각하 사유 3: 공정거래위원회가 직접 처리하는 것이 적합한 경우로 대통령령이 정하는 기준에 해당하는 행위. 현재 기준은 제45조 제1항 제9호(부당한 지원행위) 위반 혐의 행위.","src":"공정거래법 제77조 제3항 제3호 | 공정거래법 시행령 제69조 제1항"},{"t":"각하 사유 4: 신청 전에 공정거래위원회가 제80조에 따라 조사를 개시한 사건에 대해 신청한 경우. 다만 시정조치 등 처분을 받은 후 신청한 경우는 제외. 제4호 해당 여부는 공정거래위원회의 확인을 받는다.","src":"공정거래법 제77조 제3항 제4호 | 기출 2021-22"},{"t":"종료 사유 1: 분쟁당사자가 권고·조정안을 수락하거나 스스로 조정하는 등 조정이 성립된 경우(종료하여야 한다).","src":"공정거래법 제77조 제4항 제1호 | 기출 2026-29"},{"t":"종료 사유 2: 신청을 받은 날(또는 의뢰받은 날)부터 60일이 지나도 조정이 성립하지 않은 경우. 분쟁당사자 양쪽이 연장에 동의하면 90일이다. (30일이 아니다)","src":"공정거래법 제77조 제4항 제2호 | 기출 2022-25"},{"t":"종료 사유 3: 분쟁당사자의 어느 한쪽이 조정을 거부하는 등 조정절차를 진행할 실익이 없는 경우. 각하가 아니라 종료다.","src":"공정거래법 제77조 제4항 제3호 | 기출 2021-22"},{"t":"조정신청을 각하하거나 절차를 종료하면 공정거래위원회에 조정의 경위, 사유 등을 서면으로 지체 없이 보고하고 분쟁당사자에게 통보한다.","src":"공정거래법 제77조 제5항"},{"t":"조정절차 개시 전에 시정조치 등을 하지 않은 분쟁조정사항은 조정절차가 종료될 때까지 공정거래위원회가 시정조치(제49조 제1항) 및 시정권고(제88조 제1항)를 하지 못한다.","src":"공정거래법 제77조 제6항"},{"t":"소송과의 관계: 분쟁조정 신청 전후로 소가 제기되어 진행 중이면 수소법원은 조정이 있을 때까지 소송절차를 중지할 수 있다. 소송절차가 중지되지 않으면 협의회는 조정절차를 중지하여야 한다. 동종·유사 사건 소송 진행 중이면 협의회가 결정으로 조정절차를 중지할 수 있다.","src":"공정거래법 제77조의2"},{"t":"법원에 소가 제기되어 조정절차를 진행할 실익이 없는 경우는 조정절차를 종료한다(출제 기준).","src":"기출 2021-22"}]},{"머리":"조정조서(제78조)","줄":[{"t":"조정이 성립되면 조정에 참가한 위원과 분쟁당사자가 기명날인하거나 서명한 조정조서를 작성한다. 위원 전원이 아니라 조정에 참가한 위원이다.","src":"공정거래법 제78조 제1항 | 기출 2021-28 | 기출 2026-29"},{"t":"분쟁당사자가 조정절차 개시 전에 스스로 조정하고 조정조서 작성을 요청하면 협의회는 조정조서를 작성하여야 한다.","src":"공정거래법 제78조 제2항 | 기출 2021-28 | 기출 2022-25"},{"t":"분쟁당사자는 합의된 사항의 이행결과를 공정거래위원회에 제출하여야 한다.","src":"공정거래법 제78조 제3항 | 기출 2021-28"},{"t":"조정절차 개시 전에 처분하지 않은 사항에 대해 합의가 이루어지고 이행하면 공정거래위원회는 시정조치 및 시정권고를 하지 않는다.","src":"공정거래법 제78조 제4항 | 기출 2021-28"},{"t":"조정조서는 재판상 화해와 동일한 효력을 갖는다. 시정명령과 같은 효력이 아니다.","src":"공정거래법 제78조 제5항 | 기출 2021-28 | 기출 2022-24 | 기출 2024-24"},{"t":"협의회는 조정이 성립되면 공정거래위원회에 조정결과를 보고한다.","src":"공정거래법 시행령 제69조 제3항"}]}],"함정":[{"x":"분쟁당사자의 일방이 조정을 거부하여 조정절차를 진행할 실익이 없는 경우에는 조정 신청을 각하하여야 한다.","o":"일방이 조정을 거부해 진행 실익이 없으면 조정절차를 종료한다(각하 아님).","src":"공정거래법 제77조 제4항 제3호 | 기출 2021-22"},{"x":"분쟁조정사항에 대하여 조정이 성립되어 조정조서를 작성한 경우 조정조서는 협의회의 시정명령과 동일한 효력을 갖는다.","o":"조정조서는 재판상 화해와 동일한 효력을 갖는다.","src":"공정거래법 제78조 제5항 | 기출 2021-28"},{"x":"분쟁의 신청이 취하되거나 각하된 경우에, 6개월 내에 재판상의 청구를 하였을 때에는 시효는 그 재판상의 청구시 중단된 것으로 본다.","o":"6개월 내에 재판상 청구를 하면 시효는 최초의 분쟁조정 신청으로 중단된 것으로 본다.","src":"공정거래법 제76조 제5항 | 기출 2022-24"},{"x":"조정신청의 내용과 직접적인 이해관계가 없는 자가 조정신청을 한 경우 협의회는 조 정신청을 기각하여야 한다.","o":"직접적 이해관계 없는 자의 신청은 각하하여야 한다(기각 아님).","src":"공정거래법 제77조 제3항 제1호 | 기출 2022-25"},{"x":"협의회는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 전원의 찬성으로 의결한다.","o":"재적위원 과반수 출석, 출석위원 과반수 찬성으로 의결한다.","src":"공정거래법 제74조 제2항 | 기출 2023-26"},{"x":"분쟁조정의 신청이 각하된 경우에, 6개월 내에 재판상의 청구를 하였을 때에는 시효는 재판상 청구시에 중단된 것으로 본다.","o":"각하된 경우 6개월 내 재판상 청구를 하면 최초의 분쟁조정 신청으로 중단된 것으로 본다.","src":"공정거래법 제76조 제5항 | 기출 2024-24"},{"x":"협의회는 위원장 1명을 포함하여 9명 이내의 위원으로 구성하며, 위원장은 비상임으로 한다.","o":"협의회 위원장은 상임이다.","src":"공정거래법 제73조 제2항 | 기출 2025-29"},{"x":"분쟁조정의 신청은 그 신청이 각하된 경우에도 시효중단의 효력이 있다.","o":"각하된 경우에는 시효중단의 효력이 없다.","src":"공정거래법 제76조 제4항 | 기출 2026-29"},{"x":"분쟁당사자가 협의회의 권고 또는 조정안을 수락하거나 스스로 조정하는 등 조정이 성립된 경우, 협의회는 조정절차를 종료할 수 있다.","o":"조정이 성립된 경우 협의회는 조정절차를 종료하여야 한다.","src":"공정거래법 제77조 제4항 제1호 | 기출 2026-29"},{"x":"조정신청의 내용과 직접적인 이해관계가 없는 자가 조정신청을 한 경우 협의회는 조정 신청을 각하할 수 없다.","o":"이해관계가 없는 자의 신청은 각하하여야 한다.","src":"공정거래법 제77조 제3항 제1호 | 기출 2026-29"},{"x":"협의회는 분쟁조정사항에 대하여 조정이 성립된 경우 협의회 위원 전원과 분쟁당사자가 기명날인하거나 서명한 조정조서를 작성한다.","o":"조정에 참가한 위원과 분쟁당사자가 기명날인하거나 서명한다.","src":"공정거래법 제78조 제1항 | 기출 2026-29"},{"x":"협의회는 위원장 1명, 부위원장 1명을 포함하여 10인의 위원으로 구성한다.","o":"위원장 1명을 포함하여 9명 이내로 구성한다. 부위원장은 규정에 없다.","src":"공정거래법 제73조 제2항 | 기출 2026-30"},{"x":"협의회 위원의 임기는 5년으로 한다.","o":"위원의 임기는 3년이다.","src":"공정거래법 제73조 제5항 | 기출 2026-30"},{"x":"협의회 위원장은 협의회 위원이 직무와 관련된 비위사실이 있거나 직무태만, 품위손상 또는 그 밖의 사유로 위원으로 적합하지 아니하다고 인정되는 경우 그 직에서 해임할 수 있다.","o":"해임·해촉은 공정거래위원회 위원장이 한다.","src":"공정거래법 제73조 제7항 | 기출 2026-30"},{"x":"협의회 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 협의회 부위원장이 그 직무를 대행한다.","o":"공정거래위원회 위원장이 지명하는 위원이 직무를 대행한다.","src":"공정거래법 제74조 제3항 | 기출 2026-30"}]},"총칙(목적ㆍ정의ㆍ적용범위)":{"묶음":[{"머리":"목적·정의(제1조·제2조)","줄":[{"t":"목적: 사업자가 거래상 지위를 남용하여 불공정한 내용의 약관을 작성해 거래에 사용하는 것을 방지하고 불공정한 약관을 규제함으로써 건전한 거래질서를 확립한다. 이를 통해 소비자를 보호하고 국민생활을 균형 있게 향상시킨다.","src":"약관법 제1조 | 기출 2023-31 | 기출 2025-31"},{"t":"약관: 명칭이나 형태 또는 범위에 상관없이 계약의 한쪽 당사자가 여러 명의 상대방과 계약을 체결하기 위하여 일정한 형식으로 미리 마련한 계약의 내용.","src":"약관법 제2조 제1호 | 기출 2021-31 | 기출 2026-32"},{"t":"사업자: 계약의 한쪽 당사자로서 상대 당사자에게 약관을 계약의 내용으로 할 것을 제안하는 자.","src":"약관법 제2조 제2호 | 기출 2023-31 | 기출 2025-31 | 기출 2026-32"},{"t":"고객: 계약의 한쪽 당사자로서 사업자로부터 약관을 계약의 내용으로 할 것을 제안받은 자.","src":"약관법 제2조 제3호 | 기출 2025-31 | 기출 2026-32"},{"t":"약관이라는 명칭을 쓰지 않아도, 계약서 자체에 포함되어 있어도 실질이 약관이면 이 법의 적용을 받는다.","src":"약관법 제2조 제1호 | 기출 2021-31 | 기출 2024-40"}]},{"머리":"약관에 해당하는지(판례·기출)","줄":[{"t":"약관에 해당: 공공사업자의 전기·가스 공급규정.","src":"기출 2025-33"},{"t":"약관에 해당: 지방자치단체의 택지공급계약서.","src":"기출 2025-33"},{"t":"약관에 해당: 예탁금 회원제로 운영되는 골프클럽 회원권의 양도·양수절차 조항.","src":"기출 2025-33"},{"t":"약관에 해당하지 않음: 회사의 정관.","src":"기출 2025-33"},{"t":"약관에 해당하지 않음: 계약당사자가 개별적인 교섭을 거쳐 기재한 위약금 조항. 개별 교섭으로 정한 계약조항은 약관이 아니다.","src":"기출 2021-31 | 기출 2025-33"}]},{"머리":"개별 약정 우선(제4조)","줄":[{"t":"약관에서 정하고 있는 사항에 관하여 사업자와 고객이 약관의 내용과 다르게 합의한 사항이 있으면 그 합의 사항이 약관보다 우선한다.","src":"약관법 제4조 | 기출 2021-31 | 기출 2023-31 | 기출 2025-31 | 기출 2026-32"}]},{"머리":"적용 범위(제30조)","줄":[{"t":"적용 제외: 상법 제3편(회사), 근로기준법, 그 밖에 대통령령으로 정하는 비영리사업 분야에 속하는 계약에 관한 약관.","src":"약관법 제30조 제1항 | 기출 2024-40"},{"t":"약관이 근로기준법에 속하는 계약에 관한 것이면 이 법을 적용하지 않는다.","src":"약관법 제30조 제1항 | 기출 2024-40"},{"t":"특정한 거래 분야의 약관에 대해 다른 법률에 특별한 규정이 있으면 그 법률을 우선 적용하고, 없는 경우에 이 법에 따른다. 이 법은 약관에 관한 일반법이다.","src":"약관법 제30조 제2항 | 기출 2023-31 | 기출 2024-40 | 기출 2025-31"},{"t":"거래주체나 계약유형에 관계없이 원칙적으로 모든 약관에 적용된다.","src":"약관법 제30조 | 기출 2024-40"},{"t":"국제적으로 통용되는 약관 등 특별한 사정이 있는 약관은 대통령령으로 정하는 경우 제7조~제14조 적용을 조항별·업종별로 제한할 수 있다.","src":"약관법 제15조 | 기출 2024-40"}]},{"머리":"공정거래법 준용·벌칙(제30조의2·제32조·제33조)","줄":[{"t":"공정거래위원회의 심의·의결에는 공정거래법 제64조~제68조를 준용한다.","src":"약관법 제30조의2 제1항"},{"t":"이의신청, 소송 제기, 불복 소송의 전속관할에는 공정거래법 제96조~제98조, 제98조의2, 제98조의3, 제99조~제101조를 준용한다.","src":"약관법 제30조의2 제2항"},{"t":"제17조의2 제2항에 따른 명령을 이행하지 않은 자: 2년 이하의 징역 또는 1억원 이하의 벌금.","src":"약관법 제32조"},{"t":"양벌규정: 대표자, 대리인, 사용인, 종업원이 제32조 위반을 하면 행위자를 벌하는 외에 법인 또는 개인에게도 벌금형. 상당한 주의와 감독을 게을리하지 않았다면 제외.","src":"약관법 제33조"},{"t":"행정관청이 다른 법률에 따라 약관을 인가하거나 특정 거래 분야에 설치된 심사기구에서 약관을 심사할 때는 제6조~제14조를 인가·심사 기준으로 하여야 한다.","src":"약관법 제31조"}]}],"함정":[{"x":"계약의 당사자들이 계약조항을 개별적으로 교섭하여 정한 경우 그 내용도 약관에 해당한다.","o":"개별적으로 교섭하여 정한 계약조항은 약관이 아니다.","src":"약관법 제2조 제1호 | 기출 2021-31"},{"x":"특정한 거래 분야의 약관에 대하여 다른 법률에 특별한 규정이 있는 경우에도 약관의 규제에 관한 법률의 규정이 우선적으로 적용된다.","o":"다른 법률에 특별한 규정이 있으면 그 법률을 우선 적용한다.","src":"약관법 제30조 제2항 | 기출 2023-31"},{"x":"약관에서 정하고 있는 사항에 관하여 사업자와 고객이 약관의 내용과 다르게 합의한 사항이 있더라도 약관의 내용이 우선 적용된다.","o":"약관과 다르게 합의한 사항이 약관보다 우선한다.","src":"약관법 제4조 | 기출 2025-31"},{"x":"약관에서 정하고 있는 사항에 관하여 사업자와 고객이 약관의 내용과 다르게 합의한 사항이 있더라도 그 합의 사항이 약관보다 우선할 수 없다.","o":"약관과 다르게 합의한 사항이 약관보다 우선한다.","src":"약관법 제4조 | 기출 2026-32"}]},"약관의 작성ㆍ설명의무 및 해석":{"묶음":[{"머리":"작성 방법(제3조 제1항)","줄":[{"t":"사업자는 고객이 약관의 내용을 쉽게 알 수 있도록 한글로 작성하여야 한다.","src":"약관법 제3조 제1항 | 기출 2021-32 | 기출 2022-31 | 기출 2023-32 | 기출 2024-38"},{"t":"표준화·체계화된 용어를 사용하여야 한다.","src":"약관법 제3조 제1항 | 기출 2022-31 | 기출 2023-32 | 기출 2024-38"},{"t":"약관의 중요한 내용을 부호, 색채, 굵고 큰 문자 등으로 명확하게 표시하여 알아보기 쉽게 작성하여야 한다.","src":"약관법 제3조 제1항 | 기출 2021-32 | 기출 2022-31 | 기출 2023-32 | 기출 2024-38"}]},{"머리":"명시·교부의무(제3조 제2항, 시행령 제2조)","줄":[{"t":"사업자는 계약을 체결할 때 고객에게 약관의 내용을 계약 종류에 따라 일반적으로 예상되는 방법으로 분명하게 밝혀야 한다.","src":"약관법 제3조 제2항 | 기출 2021-32 | 기출 2022-31"},{"t":"고객이 요구할 경우 약관의 사본을 내주어 약관의 내용을 알 수 있게 하여야 한다.","src":"약관법 제3조 제2항 | 기출 2022-31"},{"t":"명시·교부의무가 면제되는 업종 4가지: 여객운송업, 전기·가스 및 수도사업, 우편업, 공중전화 서비스 제공 통신업.","src":"약관법 제3조 제2항 단서 | 기출 2025-36 | 기출 2026-37"},{"t":"금융업과 보험업은 명시·교부의무 면제 업종이 아니다. 업종 예외 없이 모든 사업자에게 적용되는 것도 아니다.","src":"약관법 제3조 제2항 | 기출 2021-32 | 기출 2022-31 | 기출 2023-32 | 기출 2024-38 | 기출 2025-36 | 기출 2026-37"},{"t":"면제 업종의 약관도 사업자는 영업소에 해당 약관을 비치하여 고객이 볼 수 있도록 하여야 한다.","src":"약관법 시행령 제2조 | 기출 2022-33"}]},{"머리":"설명의무(제3조 제3항·제4항)","줄":[{"t":"사업자는 약관에 정하여져 있는 중요한 내용을 고객이 이해할 수 있도록 설명하여야 한다.","src":"약관법 제3조 제3항 | 기출 2021-32 | 기출 2022-33"},{"t":"계약의 성질상 설명하는 것이 현저하게 곤란한 경우에는 설명의무가 면제된다.","src":"약관법 제3조 제3항 단서 | 기출 2021-33 | 기출 2022-33 | 기출 2023-32 | 기출 2024-38"},{"t":"설명의무 대상인 중요한 내용: 사회통념에 비추어 고객이 계약체결 여부나 대가를 결정하는 데 직접적인 영향을 미칠 수 있는 사항.","src":"기출 2022-33"},{"t":"설명의무의 상대방은 계약자 본인에 한하지 않는다. 사업자가 계약자의 대리인과 계약을 체결하면 그 대리인에게 설명하면 된다.","src":"기출 2022-33"},{"t":"사업자가 명시·교부의무(제2항) 또는 설명의무(제3항)를 위반하여 계약을 체결하면 해당 약관을 계약의 내용으로 주장할 수 없다. 계약이 무효가 되거나 사업자가 계약을 취소할 수 있는 것이 아니다.","src":"약관법 제3조 제4항 | 기출 2021-33 | 기출 2022-33 | 기출 2023-32 | 기출 2024-38 | 기출 2025-32"},{"t":"명시·교부의무 위반(고객에게 약관 내용을 밝히지 않거나 사본을 내주지 않음), 설명의무 위반은 각각 500만원 이하의 과태료.","src":"약관법 제34조 제3항 제1호·제2호 | 기출 2025-35"}]},{"머리":"약관의 해석(제5조)","줄":[{"t":"약관은 신의성실의 원칙에 따라 공정하게 해석되어야 한다.","src":"약관법 제5조 제1항 | 기출 2022-32 | 기출 2025-32 | 기출 2026-32"},{"t":"고객에 따라 다르게 해석되어서는 안 된다(객관적·획일적 해석). 계약 체결 경위 등을 고려해 고객별로 달리 해석하지 않는다.","src":"약관법 제5조 제1항 | 기출 2022-32 | 기출 2025-32 | 기출 2026-32"},{"t":"평균적 고객의 이해가능성을 기준으로 해석한다.","src":"기출 2022-32"},{"t":"약관의 뜻이 명백하지 아니한 경우에는 고객에게 유리하게 해석되어야 한다(작성자불이익 원칙).","src":"약관법 제5조 제2항 | 기출 2022-32 | 기출 2023-31 | 기출 2025-32"},{"t":"약관 내용이 모호하다는 것은 두 가지 이상의 의미로 해석될 수 있음을 뜻한다.","src":"기출 2022-32"},{"t":"사업자의 책임이나 의무를 면제하는 약관 문언이 불명확하면 사업자가 그중 최소한의 책임과 의무만 면제하는 것으로 해석하고 확장 해석하지 않는다.","src":"기출 2025-32"}]}],"함정":[{"x":"약관의 명시 및 설명의무는 모든 사업자에게 예외 없이 적용된다.","o":"여객운송업, 전기·가스 및 수도사업, 우편업, 공중전화 서비스 제공 통신업은 명시·교부의무가 면제되고, 계약의 성질상 설명이 현저히 곤란하면 설명의무가 면제된다.","src":"약관법 제3조 | 기출 2021-32"},{"x":"약관을 통하여 계약을 체결하려는 모든 사업자는 반드시 약관을 고객에게 교부하고, 그 내용을 설명하여야 한다.","o":"업종에 따라 교부의무가 면제되고 설명이 현저히 곤란한 경우 설명의무가 면제된다. 모든 사업자에게 예외 없이 적용되는 것이 아니다.","src":"약관법 제3조 | 기출 2021-33"},{"x":"약관의 내용 중 사업자와 고객 간의 재판관할의 합의 조항은이 법의 적용대상에서 제외된다.","o":"재판관할 합의 조항도 이 법의 대상이며 고객에게 부당하게 불리하면 무효다.","src":"약관법 제14조 제1호 | 기출 2021-33"},{"x":"불공정약관조항에 대한 무효규정은 모든 업종의 사업자에 대해 예외 없이 적용된다.","o":"국제적으로 통용되는 운송업, 금융업·보험업, 무역보험 약관은 제7조~제14조 적용이 제한될 수 있다.","src":"약관법 제15조 | 약관법 시행령 제3조 | 기출 2021-33"},{"x":"사업자가 약관의 설명의무를 위반하여 계약을 체결한 경우, 그 계약은 무효이다.","o":"약관을 계약의 내용으로 주장할 수 없다. 계약이 무효가 되는 것이 아니다.","src":"약관법 제3조 제4항 | 기출 2021-33"},{"x":"보험약관의 경우 여객운송업의 약관과 마찬가지로 이 법의 명시ㆍ설명의무 및 교부의 무관련 규정이 적용되지 않는다.","o":"보험약관은 면제 업종이 아니라 명시·교부의무가 적용된다.","src":"약관법 제3조 제2항 | 기출 2022-31"},{"x":"약관은 고객에 따라 다르게 해석되어도 무방하다.","o":"약관은 고객에 따라 다르게 해석되어서는 안 된다.","src":"약관법 제5조 제1항 | 기출 2022-32"},{"x":"약관에 대한 설명의무를 위반한 경우, 사업자는 계약을 취소할 수 있다.","o":"해당 약관을 계약의 내용으로 주장할 수 없다. 계약을 취소하는 것이 아니다.","src":"약관법 제3조 제4항 | 기출 2022-33"},{"x":"업종에 상관없이 모든 사업자는 약관의 명시ㆍ교부의무를 부담한다.","o":"여객운송업, 전기·가스 및 수도사업, 우편업, 공중전화 서비스 제공 통신업은 명시·교부의무가 면제된다.","src":"약관법 제3조 제2항 | 기출 2023-32"},{"x":"금융업에 대해서는 약관의 명시 및 교부의무가 면제된다.","o":"금융업은 명시·교부의무 면제 업종이 아니다.","src":"약관법 제3조 제2항 | 기출 2024-38"},{"x":"약관의 구속력의 근거가 개별적 법률행위에 있으므로 해당 계약 체결의 경위 등을 고려하여 고객에 따라 다르게 해석되어야 한다.","o":"약관은 고객에 따라 다르게 해석되어서는 안 된다.","src":"약관법 제5조 제1항 | 기출 2025-32"}]},"불공정약관조항의 무효":{"묶음":[{"머리":"일반원칙(제6조)","줄":[{"t":"신의성실의 원칙을 위반하여 공정성을 잃은 약관 조항은 무효다.","src":"약관법 제6조 제1항 | 기출 2022-34 | 기출 2026-33"},{"t":"공정성을 잃은 것으로 '추정'되는 조항 3가지(간주가 아님): ① 고객에게 부당하게 불리한 조항, ② 고객이 계약의 거래형태 등 모든 사정에 비추어 예상하기 어려운 조항, ③ 계약의 목적을 달성할 수 없을 정도로 계약에 따르는 본질적 권리를 제한하는 조항.","src":"약관법 제6조 제2항 | 기출 2022-34 | 기출 2023-33 | 기출 2026-33"}]},{"머리":"면책조항의 금지(제7조)","줄":[{"t":"무효 1: 사업자, 이행 보조자 또는 피고용자의 고의 또는 중대한 과실로 인한 법률상의 책임을 배제하는 조항. 단순 과실로 인한 책임 배제는 제7조 제1호 대상이 아니다.","src":"약관법 제7조 제1호 | 기출 2022-34 | 기출 2024-32 | 기출 2026-31"},{"t":"무효 2: 상당한 이유 없이 사업자의 손해배상 범위를 제한하거나 사업자가 부담하여야 할 위험을 고객에게 떠넘기는 조항.","src":"약관법 제7조 제2호 | 기출 2021-34 | 기출 2023-36 | 기출 2024-32 | 기출 2026-31"},{"t":"무효 3: 상당한 이유 없이 사업자의 담보책임을 배제 또는 제한하거나 담보책임에 따르는 고객의 권리행사 요건을 가중하는 조항(완화가 아니다).","src":"약관법 제7조 제3호 | 기출 2021-34 | 기출 2024-32 | 기출 2026-31"},{"t":"무효 4: 상당한 이유 없이 계약목적물에 관하여 견본이 제시되거나 품질·성능 등에 관한 표시가 있는 경우 그 보장된 내용에 대한 책임을 배제 또는 제한하는 조항.","src":"약관법 제7조 제4호 | 기출 2021-34 | 기출 2024-32 | 기출 2026-31"}]},{"머리":"손해배상액의 예정(제8조)","줄":[{"t":"고객에게 '부당하게 과중한' 지연 손해금 등의 손해배상 의무를 부담시키는 약관 조항은 무효다. 지연 손해금 등을 부담시키는 것 자체가 무효인 것은 아니다.","src":"약관법 제8조 | 기출 2021-35 | 기출 2022-34 | 기출 2025-39 | 기출 2026-33"}]},{"머리":"계약의 해제·해지(제9조)","줄":[{"t":"제1호: 법률에 따른 고객의 해제권 또는 해지권을 배제하거나 그 행사를 제한하는 조항.","src":"약관법 제9조 제1호 | 기출 2022-35 | 기출 2023-33 | 기출 2024-39"},{"t":"제2호: 사업자에게 법률에서 규정하고 있지 않은 해제권 또는 해지권을 부여하여 고객에게 부당하게 불이익을 줄 우려가 있는 조항. 고객에게 법에 없는 해제권을 부여하는 조항은 무효사유가 아니다.","src":"약관법 제9조 제2호 | 기출 2022-35 | 기출 2024-39 | 기출 2026-34"},{"t":"제3호: 법률에 따른 사업자의 해제권 또는 해지권의 행사 요건을 완화하여 고객에게 부당하게 불이익을 줄 우려가 있는 조항.","src":"약관법 제9조 제3호 | 기출 2021-35 | 기출 2024-39"},{"t":"제4호: 해제·해지로 인한 원상회복의무를 상당한 이유 없이 고객에게 과중하게 부담시키거나 고객의 원상회복 청구권을 부당하게 포기하도록 하는 조항.","src":"약관법 제9조 제4호 | 기출 2022-35 | 기출 2023-40 | 기출 2026-34"},{"t":"제5호: 해제·해지로 인한 사업자의 원상회복의무나 손해배상의무를 부당하게 경감하는 조항. 사업자에게 과중하게 부담시키는 조항은 무효사유가 아니다.","src":"약관법 제9조 제5호 | 기출 2022-35 | 기출 2023-40 | 기출 2024-39"},{"t":"제6호: 계속적 채권관계의 발생을 목적으로 하는 계약에서 존속기간을 부당하게 단기 또는 장기로 하거나 묵시적인 기간의 연장 또는 갱신이 가능하도록 정하여 고객에게 부당하게 불이익을 줄 우려가 있는 조항.","src":"약관법 제9조 제6호 | 기출 2021-36 | 기출 2024-39 | 기출 2026-34"}]},{"머리":"채무의 이행(제10조)","줄":[{"t":"제1호: 상당한 이유 없이 급부의 내용을 사업자가 일방적으로 결정하거나 변경할 수 있도록 권한을 부여하는 조항.","src":"약관법 제10조 제1호 | 기출 2021-35 | 기출 2023-40"},{"t":"제2호: 상당한 이유 없이 사업자가 이행하여야 할 급부를 일방적으로 중지할 수 있게 하거나 제3자에게 대행할 수 있게 하는 조항.","src":"약관법 제10조 제2호 | 기출 2023-40"}]},{"머리":"고객의 권익 보호(제11조)","줄":[{"t":"제1호: 법률에 따른 고객의 항변권, 상계권 등의 권리를 '상당한 이유 없이' 배제하거나 제한하는 조항.","src":"약관법 제11조 제1호 | 기출 2021-36 | 기출 2022-37 | 기출 2023-35 | 기출 2025-38 | 기출 2026-38"},{"t":"제2호: 고객에게 주어진 기한의 이익을 '상당한 이유 없이' 박탈하는 조항. 기한의 이익을 부여하는 조항은 무효사유가 아니다.","src":"약관법 제11조 제2호 | 기출 2021-35 | 기출 2023-35 | 기출 2025-38 | 기출 2026-38"},{"t":"제3호: 고객이 제3자와 계약을 체결하는 것을 '부당하게' 제한하는 조항.","src":"약관법 제11조 제3호 | 기출 2023-35 | 기출 2025-38 | 기출 2026-38"},{"t":"제4호: 사업자가 업무상 알게 된 고객의 비밀을 '정당한 이유 없이' 누설하는 것을 허용하는 조항.","src":"약관법 제11조 제4호 | 기출 2023-35 | 기출 2025-38 | 기출 2026-38"},{"t":"제11조의 수식어 정리: 항변권·상계권 = 상당한 이유 없이, 기한의 이익 박탈 = 상당한 이유 없이, 제3자와의 계약 제한 = 부당하게, 고객 비밀 누설 = 정당한 이유 없이.","src":"약관법 제11조 | 기출 2023-35"}]},{"머리":"의사표시의 의제(제12조)","줄":[{"t":"제1호: 일정한 작위·부작위가 있을 때 고객의 의사표시가 표명되거나 표명되지 않은 것으로 보는 조항. 다만 상당한 기한 내에 의사표시를 하지 않으면 의제된다는 뜻을 명확하게 따로 고지한 경우나 부득이한 사유로 고지할 수 없는 경우는 제외(유효).","src":"약관법 제12조 제1호 | 기출 2022-36"},{"t":"제2호: 고객의 의사표시의 형식이나 요건에 대하여 부당하게 엄격한 제한을 두는 조항.","src":"약관법 제12조 제2호 | 기출 2021-35 | 기출 2022-36"},{"t":"제3호: 고객의 이익에 중대한 영향을 미치는 사업자의 의사표시가 상당한 이유 없이 고객에게 도달된 것으로 보는 조항.","src":"약관법 제12조 제3호 | 기출 2021-36 | 기출 2022-36"},{"t":"제4호: 고객의 이익에 중대한 영향을 미치는 사업자의 의사표시 기한을 부당하게 길게 정하거나 불확정하게 정하는 조항.","src":"약관법 제12조 제4호 | 기출 2021-36 | 기출 2022-36 | 기출 2023-36"}]},{"머리":"대리인의 책임 가중·소송 제기 금지(제13조·제14조)","줄":[{"t":"제13조: 고객의 대리인에 의해 계약이 체결된 경우 고객이 의무를 이행하지 않으면 대리인에게 그 의무의 전부 또는 일부를 이행할 책임을 지우는 약관 조항은 무효.","src":"약관법 제13조 | 기출 2022-37 | 기출 2025-39"},{"t":"제14조 제1호: 고객에게 부당하게 불리한 소송 제기 금지 조항 또는 재판관할의 합의 조항은 무효. 재판관할 합의 조항 자체가 이 법의 적용대상에서 제외되는 것은 아니다.","src":"약관법 제14조 제1호 | 기출 2021-33 | 기출 2022-37"},{"t":"제14조 제2호: 소송 제기 등과 관련해 '상당한 이유 없이 고객에게' 입증책임을 부담시키는 약관 조항은 무효. 사업자에게 입증책임을 부담시키는 조항이 아니다.","src":"약관법 제14조 제2호 | 기출 2021-36 | 기출 2025-39"}]},{"머리":"적용 제한(제15조, 시행령 제3조)","줄":[{"t":"국제적으로 통용되는 약관이나 특별한 사정이 있는 약관으로서 대통령령으로 정하는 경우 제7조~제14조 적용을 조항별·업종별로 제한할 수 있다.","src":"약관법 제15조 | 기출 2021-33 | 기출 2024-40"},{"t":"제7조~제14조 적용이 제한되는 업종: ① 국제적으로 통용되는 운송업, ② 국제적으로 통용되는 금융업 및 보험업, ③ 무역보험법에 따른 무역보험. 국제적으로 통용되는 부동산업은 해당하지 않는다.","src":"약관법 시행령 제3조 | 기출 2024-40 | 기출 2026-40"},{"t":"불공정약관 무효규정은 모든 업종의 사업자에게 예외 없이 적용되는 것이 아니다.","src":"약관법 제15조 | 기출 2021-33"}]},{"머리":"일부 무효의 특칙(제16조)·사용금지(제17조)","줄":[{"t":"약관의 전부 또는 일부 조항이 제3조 제4항에 따라 계약의 내용이 되지 못하거나 제6조~제14조에 따라 무효인 경우 계약은 나머지 부분만으로 유효하게 존속한다.","src":"약관법 제16조 | 기출 2022-37 | 기출 2025-39"},{"t":"다만 유효한 부분만으로는 계약의 목적 달성이 불가능하거나 유효한 부분이 한쪽 당사자에게 부당하게 불리한 경우에는 그 계약이 무효가 된다. 유효한 부분만으로 목적 달성이 가능하면 계약 전체가 무효로 되지 않는다.","src":"약관법 제16조 단서 | 기출 2021-34"},{"t":"사업자는 제6조~제14조에 해당하는 불공정약관조항을 계약의 내용으로 하여서는 안 된다.","src":"약관법 제17조 | 기출 2025-39"},{"t":"표준약관 표지를 사용하면서 표준약관과 다른 내용을 약관으로 사용하는 경우, 표준약관보다 고객에게 더 불리한 약관 내용은 무효다.","src":"약관법 제19조의3 제9항"}]}],"함정":[{"x":"신의성실의 원칙을 위반하여 공정성을 잃은 약관조항에 의해 계약이 체결된 경우에는 유효한 부분만으로 계약의 목적 달성이 가능한 경우에도 계약의 전체가 무효로 된다.","o":"유효한 부분만으로 목적 달성이 가능하면 계약은 나머지 부분만으로 유효하게 존속한다.","src":"약관법 제16조 | 기출 2021-34"},{"x":"약관의 내용 중 고객에게 부당하게 불리한 조항은 공정성을 잃은 것으로 간주한다.","o":"공정성을 잃은 것으로 '추정'한다.","src":"약관법 제6조 제2항 제1호 | 기출 2022-34"},{"x":"약관의 내용 중 고객이 계약의 거래형태 등 관련된 모든 사정에 비추어 예상하기 어려운 조항은 공정성을 잃은 것으로 간주한다.","o":"공정성을 잃은 것으로 '추정'한다.","src":"약관법 제6조 제2항 제2호 | 기출 2022-34"},{"x":"계약 당사자의 책임에 관하여 정하고 있는 약관의 내용 중 사업자, 이행 보조자 또는 피용자의 과실로 인한 법률상의 책임을 배제하는 조항은 무효로 한다.","o":"사업자, 이행 보조자 또는 피고용자의 '고의 또는 중대한 과실'로 인한 책임을 배제하는 조항이 무효다.","src":"약관법 제7조 제1호 | 기출 2022-34"},{"x":"신의성실의 원칙을 위반하여 공정성을 잃은 약관조항은 무효로 추정된다.","o":"공정성을 잃은 약관조항은 '무효'다(추정이 아니다).","src":"약관법 제6조 제1항 | 기출 2022-34"},{"x":"약관의 일부의 조항이 이 법제3조 제4항에 따라 계약의 내용이 되지 못하는 경우에는 그 계약은 전부 무효가 되는 것이 원칙이다.","o":"계약은 나머지 부분만으로 유효하게 존속하는 것이 원칙이다.","src":"약관법 제16조 | 기출 2022-37"},{"x":"소송 제기 등과 관련된 약관의 내용 중 사업자에게 입증책임을 부담시키는 약관 조항은 무효로 한다.","o":"상당한 이유 없이 '고객에게' 입증책임을 부담시키는 조항이 무효다.","src":"약관법 제14조 제2호 | 기출 2025-39"},{"x":"고객이 계약의 거래형태 등 관련된 모든 사정에 비추어 예상하기 어려운 조항은 공정 성을 잃은 것으로 간주된다.","o":"공정성을 잃은 것으로 '추정'된다.","src":"약관법 제6조 제2항 제2호 | 기출 2026-33"}]},"약관의 규제(행정적 규제ㆍ표준약관ㆍ심사청구)":{"묶음":[{"머리":"시정 조치(제17조의2)","줄":[{"t":"시정권고: 제17조를 위반한 사업자에게 해당 불공정약관조항의 삭제·수정 등 시정에 필요한 조치를 권고할 수 있다.","src":"약관법 제17조의2 제1항 | 기출 2021-38"},{"t":"시정명령: 아래 사유에 해당하면 삭제·수정, 시정명령을 받은 사실의 공표, 그 밖에 약관을 시정하기 위해 필요한 조치를 명할 수 있다.","src":"약관법 제17조의2 제2항 | 기출 2024-33"},{"t":"시정명령 사유 1: 사업자가 공정거래법상 시장지배적사업자인 경우.","src":"약관법 제17조의2 제2항 제1호 | 기출 2024-33"},{"t":"시정명령 사유 2: 사업자가 자기의 거래상의 지위를 부당하게 이용하여 계약을 체결하는 경우.","src":"약관법 제17조의2 제2항 제2호"},{"t":"시정명령 사유 3: 일반 공중에게 물품·용역을 공급하는 계약으로서 체결의 긴급성·신속성 때문에 고객이 약관 조항 내용을 변경하기 곤란한 경우.","src":"약관법 제17조의2 제2항 제3호"},{"t":"시정명령 사유 4: 사업자의 지위가 현저히 우월하거나 고객이 다른 사업자를 선택할 범위가 제한되어 약관을 계약 내용으로 하는 것이 사실상 강제되는 경우.","src":"약관법 제17조의2 제2항 제4호"},{"t":"시정명령 사유 5: 계약의 성질상 또는 목적상 취소·해제·해지가 불가능하거나 취소·해제·해지하면 고객에게 현저한 재산상 손해가 발생하는 경우.","src":"약관법 제17조의2 제2항 제5호"},{"t":"시정명령 사유 6: 사업자가 제1항의 권고를 정당한 사유 없이 따르지 않아 여러 고객에게 피해가 발생하거나 발생할 우려가 현저한 경우.","src":"약관법 제17조의2 제2항 제6호"},{"t":"시정권고·시정명령을 할 때 필요하면 같은 종류의 사업을 하는 다른 사업자에게 같은 내용의 불공정약관조항을 사용하지 말 것을 권고할 수 있다.","src":"약관법 제17조의2 제3항 | 기출 2021-38 | 기출 2024-33"},{"t":"시정권고 또는 시정명령은 그 내용을 분명히 밝힌 서면으로 하여야 한다.","src":"약관법 시행령 제4조 | 기출 2021-38"},{"t":"시정명령(제17조의2 제2항 명령)을 이행하지 않으면 2년 이하의 징역 또는 1억원 이하의 벌금.","src":"약관법 제32조"}]},{"머리":"관청 인가 약관(제18조)","줄":[{"t":"공정거래위원회는 행정관청이 작성한 약관이나 다른 법률에 따라 행정관청의 인가를 받은 약관이 제6조~제14조에 해당된다고 인정하면 해당 행정관청에 그 사실을 통보하고 시정에 필요한 조치를 하도록 요청할 수 있다.","src":"약관법 제18조 제1항 | 기출 2021-38"},{"t":"은행법에 따른 은행의 약관이 불공정약관에 해당한다고 인정하면 금융감독원에 통보하고 시정에 필요한 조치를 권고할 수 있다. 보험회사 약관은 해당하지 않는다.","src":"약관법 제18조 제2항 | 기출 2021-38 | 기출 2024-33"},{"t":"제1항에 따라 행정관청에 시정을 요청한 경우 공정거래위원회는 제17조의2 제1항·제2항의 시정권고·시정명령을 하지 않는다.","src":"약관법 제18조 제3항"},{"t":"요청·권고는 내용을 분명히 밝힌 서면(전자문서 포함)으로 한다. 요청·권고를 받은 행정관청 또는 금융감독원은 받은 날부터 60일 이내에 공정거래위원회에 서면으로 처리결과를 알려야 한다.","src":"약관법 시행령 제5조"}]},{"머리":"약관의 심사청구(제19조·제19조의2)","줄":[{"t":"심사청구를 할 수 있는 자: ① 약관 조항과 관련하여 법률상 이익이 있는 자, ② 소비자기본법 제29조에 따라 등록된 소비자단체, ③ 소비자기본법 제33조에 따라 설립된 한국소비자원, ④ 사업자단체.","src":"약관법 제19조 제1항 | 기출 2021-37 | 기출 2022-38 | 기출 2023-37 | 기출 2026-35"},{"t":"심사청구를 할 수 없는 자: 금융감독원, 중소벤처기업부, 한국공정거래조정원, 소비자기본법에 따라 등록되지 않은 소비자단체, 사실상 이익만 있는 자.","src":"약관법 제19조 제1항 | 기출 2021-37 | 기출 2022-38 | 기출 2023-37"},{"t":"심사청구는 공정거래위원회에 서면이나 전자문서로 제출한다. 전화·구두나 법원 제출은 안 된다.","src":"약관법 제19조 제2항 | 기출 2024-34 | 기출 2026-35"},{"t":"심사청구서 기재: 청구인 성명·주소, 사업자 성명(상호)·주소, 심사청구의 취지와 이유. 심사 대상 약관의 사본을 첨부.","src":"약관법 시행령 제6조 제1항"},{"t":"공정거래위원회는 심사청구를 받은 날부터 특별한 사유가 없으면 60일 이내에 심사결과를 청구인에게 서면으로 통보하여야 한다.","src":"약관법 시행령 제6조 제2항"},{"t":"심사대상인 약관 조항이 변경되면 공정거래위원회가 직권으로 또는 심사청구인의 신청에 의해 심사대상을 변경할 수 있다.","src":"약관법 제19조의2 | 기출 2024-34"}]},{"머리":"표준약관(제19조의3)","줄":[{"t":"작성 주체: 사업자 및 사업자단체는 일정한 거래 분야에서 표준이 될 약관의 제정·개정안을 마련해 법 위반 여부에 관한 심사를 공정거래위원회에 청구할 수 있다.","src":"약관법 제19조의3 제1항 | 기출 2021-40 | 기출 2023-38 | 기출 2024-33 | 기출 2025-40"},{"t":"소비자단체등(소비자기본법에 따라 등록된 소비자단체, 한국소비자원)은 소비자 피해가 자주 일어나는 거래 분야에서 표준이 될 약관을 제정 또는 개정할 것을 공정거래위원회에 요청할 수 있다.","src":"약관법 제19조의3 제2항 | 기출 2021-40 | 기출 2023-38 | 기출 2024-34 | 기출 2025-40"},{"t":"공정거래위원회가 심사 청구를 '권고'할 수 있는 경우 3가지: ① 소비자단체등의 요청이 있는 경우, ② 일정 거래 분야에서 여러 고객에게 피해가 발생하거나 우려되어 조사한 결과 약관이 없거나 불공정약관조항이 있는 경우, ③ 법률의 제정·개정·폐지 등으로 약관을 정비할 필요가 발생한 경우.","src":"약관법 제19조의3 제3항 | 기출 2021-40 | 기출 2022-40 | 기출 2023-38 | 기출 2024-33 | 기출 2026-36"},{"t":"약관분쟁조정협의회의 요청은 권고 사유가 아니다. 심사 청구를 명령할 수도 없다(권고만 가능).","src":"약관법 제19조의3 제3항 | 기출 2021-40 | 기출 2026-36"},{"t":"권고를 받은 날부터 4개월 이내에 필요한 조치를 하지 않으면 거래 당사자 및 소비자단체등의 의견을 듣고 관계 부처 협의를 거쳐 공정거래위원회가 표준약관을 제정 또는 개정할 수 있다.","src":"약관법 제19조의3 제4항"},{"t":"공정거래위원회는 심사하거나 제정·개정한 표준약관을 공시하고 사용을 '권장'할 수 있다. 사용을 명하는 것이 아니다.","src":"약관법 제19조의3 제5항 | 기출 2022-40"},{"t":"표준약관 사용을 권장받은 사업자·사업자단체가 표준약관과 다른 약관을 사용하면 다르게 정한 주요 내용을 고객이 알기 쉽게 표시하여야 한다.","src":"약관법 제19조의3 제6항 | 기출 2022-40 | 기출 2025-35"},{"t":"공정거래위원회는 표준약관 표지를 정할 수 있고, 표준약관을 사용하는 사업자는 고시하는 바에 따라 표지를 사용할 수 있다.","src":"약관법 제19조의3 제7항 | 기출 2022-40 | 기출 2023-38"},{"t":"표준약관과 다른 내용을 약관으로 사용하는 경우 표준약관 표지를 사용해서는 안 된다.","src":"약관법 제19조의3 제8항 | 기출 2023-38 | 기출 2025-40"},{"t":"표준약관 심사청구를 받으면 공정거래위원회는 받은 날부터 60일 이내에 심사결과를 신청인에게 알려야 한다(90일이 아니다). 표준약관 사용 사업자에게 운용 상황 제출을 하게 할 수 있다.","src":"약관법 시행령 제7조 | 기출 2022-40 | 기출 2025-40"}]},{"머리":"조사·의견진술·공개(제20조·제22조·제23조)","줄":[{"t":"조사 사유: ① 시정권고·시정명령을 하기 위해 필요한 경우, ② 약관 심사청구를 받은 경우. 조사 공무원은 권한을 표시하는 증표를 내보여야 한다.","src":"약관법 제20조"},{"t":"공정거래위원회는 심의 전에 그 약관에 따라 거래한 사업자 또는 이해관계인에게 심사 대상이 되었다는 사실을 알려야 한다(서면으로, 회의 일시·장소 기재). 통지받은 당사자는 회의에 출석해 의견을 진술하거나 자료를 제출할 수 있다.","src":"약관법 제22조 제1항·제2항 | 약관법 시행령 제8조"},{"t":"심사 대상 약관이 다른 법률에 따라 행정관청의 인가를 받았거나 받아야 하면 심의 전에 그 행정관청에 의견 제출을 요구할 수 있다.","src":"약관법 제22조 제3항"},{"t":"공정거래위원회는 이 법에 위반된다고 심의·의결한 약관 조항의 목록을 인터넷 홈페이지에 공개하여야 한다.","src":"약관법 제23조 | 기출 2024-34"}]},{"머리":"과태료(제34조)","줄":[{"t":"5천만원 이하: ① 표준약관과 다른 내용을 약관으로 사용하면서 표준약관 표지를 사용한 자, ② 제20조 제1항 조사를 거부·방해·기피한 사업자 또는 사업자단체.","src":"약관법 제34조 제1항 | 기출 2024-31 | 기출 2025-35"},{"t":"1천만원 이하: 사업자 또는 사업자단체의 임원·종업원, 그 밖의 이해관계인이 조사를 거부·방해·기피한 경우.","src":"약관법 제34조 제2항 | 기출 2024-31"},{"t":"500만원 이하: ① 고객에게 약관의 내용을 밝히지 않거나 사본을 내주지 않은 자, ② 약관의 중요한 내용을 설명하지 않은 자, ③ 표준약관과 다르게 정한 주요 내용을 고객이 알기 쉽게 표시하지 않은 자.","src":"약관법 제34조 제3항 | 기출 2024-31 | 기출 2025-35"},{"t":"100만원 이하: 공정거래법 제66조에 따른 질서유지 명령을 따르지 않은 자.","src":"약관법 제34조 제4항"},{"t":"과태료는 대통령령으로 정하는 바에 따라 공정거래위원회가 부과·징수한다.","src":"약관법 제34조 제5항"},{"t":"과태료가 가장 높은 것: 표준약관 표지 위반(5천만원 이하). 조사 거부 사업자도 5천만원 이하.","src":"약관법 제34조 | 기출 2024-31"}]}],"함정":[{"x":"공정거래위원회는 보험업법에 따른 보험회사의 약관이 이 법의 규정상 불공정약관 조항에 해당된다고 인정할 때에는 금융감독원에 그 사실을 통보하고 이를 시정하기 위하여 필요한 조치를 권고할 수 있다.","o":"금융감독원에 통보·권고하는 대상은 은행법에 따른 은행의 약관이다. 보험회사 약관은 해당하지 않는다.","src":"약관법 제18조 제2항 | 기출 2021-38"},{"x":"사업자 및 사업자단체는 표준약관과 다른 내용을 약관으로 사용하는 경우에도 표준약관 표지(標識)를 사용할 수 있다.","o":"표준약관과 다른 내용을 약관으로 사용하면 표준약관 표지를 사용할 수 없다.","src":"약관법 제19조의3 제8항 | 기출 2023-38"},{"x":"공정거래위원회는 불공정약관 조항에 대해서 구체적인 내용을 제시하여 수정할 것을 적극적으로 명할 수 있다.","o":"출제 오답(바른 문장 미확인). 조문은 불공정약관조항의 삭제·수정 등 시정 권고, 일정 사유에 해당하면 삭제·수정·공표 등 명령이다.","src":"약관법 제17조의2 | 기출 2024-33"},{"x":"긴급한 경우 약관의 심사청구는 공정거래위원회에 전화 또는 구두로 제출할 수 있다.","o":"약관 심사청구는 서면이나 전자문서로 제출한다.","src":"약관법 제19조 제2항 | 기출 2024-34"},{"x":"이 법에 따른 약관의 심사청구는 서면이나 전자문서로 제출하고, 법원에 해야 한다.","o":"공정거래위원회에 서면이나 전자문서로 제출한다.","src":"약관법 제19조 제2항 | 기출 2026-35"}]},"약관 분쟁조정협의회":{"묶음":[{"머리":"설치·구성(제24조)","줄":[{"t":"약관 분쟁조정협의회는 한국공정거래조정원에 둔다. 대상은 제17조를 위반한 약관 또는 이와 법률상 쟁점이 공통되는 약관과 관련된 분쟁이다.","src":"약관법 제24조 제1항 | 약관법 시행령 제8조의2"},{"t":"위원장 1명을 포함한 9명의 위원으로 구성한다. 위원장은 상임이다.","src":"약관법 제24조 제2항 | 기출 2021-39 | 기출 2022-39 | 기출 2024-35"},{"t":"위원장은 조정원의 장의 제청으로 공정거래위원회 위원장이 위촉한다.","src":"약관법 제24조 제3항 | 기출 2021-39 | 기출 2022-39 | 기출 2024-35"},{"t":"위원은 조정원의 장의 제청으로 공정거래위원회 위원장이 임명하거나 위촉한다(약관규제·소비자 분야 경험·전문지식이 있는 사람: 4급 이상 공무원 경력자, 판사·검사·변호사 자격자, 부교수 이상 대학 교원, 기업경영·소비자권익·분쟁조정 학식·경험자).","src":"약관법 제24조 제5항 | 기출 2023-39 | 기출 2024-35"},{"t":"위원 임기는 3년이며 연임할 수 있다. 결원 시 보궐위원의 임기는 전임자의 남은 임기.","src":"약관법 제24조 제6항·제7항 | 기출 2021-39 | 기출 2023-39"},{"t":"위원장이 사고로 직무를 수행할 수 없으면 위원장이 지명하는 협의회 위원이 대행한다.","src":"약관법 제24조 제4항"},{"t":"위원장은 직무 외에 영리를 목적으로 하는 업무에 종사하지 못한다. 공정거래위원회 위원장의 심사를 거쳐 비영리 업무는 겸할 수 있다.","src":"약관법 제24조 제9항~제11항"}]},{"머리":"회의(제25조)","줄":[{"t":"회의 구분: 위원 전원으로 구성되는 전체회의, 위원장이 지명하는 3명(위원장 포함 가능)으로 구성되는 분과회의.","src":"약관법 제25조 제1항 | 기출 2021-39 | 기출 2022-39 | 기출 2023-39"},{"t":"분과회의는 전체회의로부터 위임받은 사항을 심의·의결한다.","src":"약관법 제25조 제2항"},{"t":"전체회의: 위원장이 주재하며 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다. (3분의 2가 아니다)","src":"약관법 제25조 제3항 | 기출 2021-39 | 기출 2023-39 | 기출 2024-35"},{"t":"분과회의: 위원장 또는 위원장이 지명하는 위원이 주재하며 구성위원 전원의 출석과 출석위원 전원의 찬성으로 의결한다. 분과회의 의결은 협의회 의결로 보되 결과를 전체회의에 보고한다.","src":"약관법 제25조 제4항 | 기출 2024-35"},{"t":"분쟁당사자(소비자기본법상 소비자 제외 고객, 사업자)는 회의에 출석하여 의견을 진술하거나 관계 자료를 제출할 수 있다. 서면으로만 제출하는 것이 아니다.","src":"약관법 제25조 제5항 | 기출 2023-39"},{"t":"회의는 개최 7일 전까지 일시·장소·안건을 서면으로 알려 소집한다. 회의는 공개하지 않으며 위원장이 필요하다고 인정하면 분쟁당사자 등이 방청하게 할 수 있다.","src":"약관법 시행령 제8조의3"},{"t":"제척·기피·회피: 위원 또는 배우자(였던 자)가 분쟁당사자이거나 공동권리자·의무자인 경우, 친족관계, 자문·고문, 대리인 관여·증언·감정 등. 분쟁당사자는 기피신청을 할 수 있고 위원은 회피할 수 있다.","src":"약관법 제26조"}]},{"머리":"분쟁조정의 신청(제27조)","줄":[{"t":"신청 주체: 제17조 위반 약관 등으로 피해를 입은 고객이 분쟁조정 신청서를 협의회에 제출. 공정거래위원회는 분쟁조정을 협의회에 의뢰할 수 있다.","src":"약관법 제27조 제1항·제2항 | 기출 2023-34"},{"t":"협의회는 신청서를 접수하거나 의뢰받으면 즉시 분쟁당사자에게 통지하여야 한다.","src":"약관법 제27조 제3항 | 기출 2023-34"},{"t":"신청 불가·각하 사유 1: 분쟁조정 신청 이전에 공정거래위원회가 조사 중인 사건.","src":"약관법 제27조 제1항 제1호 | 기출 2023-34 | 기출 2025-37"},{"t":"신청 불가·각하 사유 2: 신청 내용이 약관의 해석이나 그 이행을 요구하는 사건.","src":"약관법 제27조 제1항 제2호 | 기출 2023-34 | 기출 2024-37 | 기출 2025-37"},{"t":"신청 불가·각하 사유 3: 약관의 무효판정을 요구하는 사건.","src":"약관법 제27조 제1항 제3호 | 기출 2024-37"},{"t":"신청 불가·각하 사유 4: 고객과 사업자 간에 분쟁해결이나 피해보상에 관한 합의가 이루어진 사건.","src":"약관법 시행령 제8조의4 제4항 제1호 | 기출 2024-37 | 기출 2025-37"},{"t":"신청 불가·각하 사유 5: 중재법에 따라 중재가 진행 중이거나 신청된 사건.","src":"약관법 시행령 제8조의4 제4항 제2호 | 기출 2024-37 | 기출 2025-37"},{"t":"법원에 소를 제기한 사건은 각하 사유로 규정되어 있지 않다. 소송이 진행 중이면 수소법원이 소송절차를 중지할 수 있고, 중지되지 않으면 협의회가 조정절차를 중지한다.","src":"약관법 제27조의3 | 기출 2024-37 | 기출 2025-37"},{"t":"다수의 고객이 공동으로 신청하면 3명 이내의 대표자를 선임할 수 있다. 대표자가 분쟁조정 신청 철회, 조정안 수락·거부를 하려면 다른 신청인의 서면 동의를 받아야 한다.","src":"약관법 시행령 제8조의5"},{"t":"신청서 보완이 필요하면 협의회 위원장이 상당한 기간을 정해 보완을 요구하여야 하며 보완 기간은 60일 기간에서 제외한다.","src":"약관법 시행령 제8조의6"}]},{"머리":"조정·종료(제27조의2·제27조의3·제28조)","줄":[{"t":"협의회는 분쟁당사자에게 스스로 조정하도록 권고하거나 조정안을 작성해 제시할 수 있다.","src":"약관법 제27조의2 제1항"},{"t":"협의회는 사실 확인을 위해 조사를 하거나 분쟁당사자에게 자료 제출이나 출석을 요구할 수 있다. 출석 요구는 출석 지정일 7일 전까지 알린다.","src":"약관법 제27조의2 제2항 | 약관법 시행령 제8조의7 | 기출 2023-34"},{"t":"각하 대상 사건(제27조 제1항 각 호)은 조정신청을 각하하여야 한다.","src":"약관법 제27조의2 제3항 | 기출 2023-34"},{"t":"조정절차 종료 사유 1: 분쟁당사자가 권고·조정안을 수락하거나 스스로 조정하는 등 조정이 성립된 경우.","src":"약관법 제27조의2 제4항 제1호"},{"t":"조정절차 종료 사유 2: 신청 또는 의뢰를 받은 날부터 60일(분쟁당사자 쌍방이 기간연장에 동의하면 90일)이 지나도 조정이 성립하지 않은 경우. (30일이 아니다)","src":"약관법 제27조의2 제4항 제2호 | 기출 2023-34"},{"t":"조정절차 종료 사유 3: 분쟁당사자의 일방이 조정을 거부하는 등 조정절차를 진행할 실익이 없는 경우.","src":"약관법 제27조의2 제4항 제3호 | 기출 2022-39"},{"t":"각하하거나 종료하면 공정거래위원회에 사유와 관계 서류를 서면으로 지체 없이 보고하고 분쟁당사자에게 통보한다. 분쟁조정 종료서에는 당사자 현황, 분쟁 경위, 조정의 쟁점, 각하·종료 사유(조정 성립 시 결과)를 적는다.","src":"약관법 제27조의2 제5항 | 약관법 시행령 제8조의9"},{"t":"조정 성립 시 조정에 참가한 위원과 분쟁당사자가 기명날인하거나 서명한 조정조서를 작성한다. 이 경우 분쟁당사자 간에 조정조서와 동일한 내용의 합의가 성립된 것으로 본다.","src":"약관법 제28조 제1항"},{"t":"분쟁당사자가 조정절차 개시 전에 스스로 조정하고 조정조서 작성을 요청하면 조정조서를 작성한다.","src":"약관법 제28조 제2항"},{"t":"분쟁당사자는 분쟁조정을 신청한 후 소를 제기하거나 중재·다른 조정을 신청하면 지체 없이 협의회에 알려야 한다.","src":"약관법 시행령 제8조의8 제1항"}]},{"머리":"집단분쟁조정(제28조의2, 시행령 제9조~제9조의6)","줄":[{"t":"의뢰·신청 주체: 공정거래위원회, 고객 또는 사업자. 조정이 성립된 사항과 같거나 비슷한 유형의 피해가 다수 고객에게 발생할 가능성이 크다고 판단한 경우로 대통령령으로 정하는 사건. 한국소비자원은 규정되어 있지 않다.","src":"약관법 제28조의2 제1항 | 기출 2024-36"},{"t":"대통령령 요건: 제17조 위반 약관 등으로 피해가 발생했고, 합의한 고객·중재 진행 중인 고객·소를 제기한 고객을 제외한 피해 고객이 20명 이상일 것.","src":"약관법 시행령 제9조"},{"t":"신청은 서면으로 한다. 협의회는 의결로 집단분쟁조정 절차를 개시할 수 있고, 분쟁조정된 사안 중 집단분쟁조정 신청에 필요한 사항을 공표하고 일정 기간 개시를 공고하여야 한다.","src":"약관법 제28조의2 제2항 | 약관법 시행령 제9조의2"},{"t":"개시 공고: 한국공정거래조정원 인터넷 홈페이지 및 전국을 보급지역으로 하는 일간신문에 게재. 공고기간은 14일 이상.","src":"약관법 시행령 제9조의3 | 기출 2025-34"},{"t":"집단분쟁조정의 기간은 공고가 종료된 날의 다음 날부터 기산한다. (공고 종료일 당일이 아니다)","src":"약관법 제28조의2 제7항 | 기출 2025-34"},{"t":"당사자 추가: 협의회는 집단분쟁조정의 당사자가 아닌 고객으로부터 당사자에 추가로 포함될 수 있도록 하는 신청을 받을 수 있다. 신청은 공고기간에 서면으로 하며, 협의회는 공고기간이 끝난 후 10일 이내에 참가 인정 여부를 서면으로 알린다.","src":"약관법 제28조의2 제3항 | 약관법 시행령 제9조의4 | 기출 2024-36 | 기출 2025-34"},{"t":"대표당사자: 협의회는 협의회의 의결로써 당사자 중에서 공동의 이익을 대표하기에 가장 적합한 1인 또는 수인을 대표당사자로 선임할 수 있다(위원장이 선임하는 것이 아니다).","src":"약관법 제28조의2 제4항 | 기출 2024-36 | 기출 2025-34"},{"t":"보상계획서: 사업자가 집단분쟁조정의 내용을 수락하면 협의회는 당사자가 아닌 피해 고객에 대한 보상계획서를 작성해 제출하도록 '권고'할 수 있다(명령 아님). 권고를 받은 사업자는 15일 이내에 수락 여부를 알려야 한다.","src":"약관법 제28조의2 제5항 | 약관법 시행령 제9조의5 | 기출 2024-36 | 기출 2025-34"},{"t":"집단분쟁조정 당사자인 다수 고객 중 일부가 법원에 소를 제기하면 절차를 중지하지 않고 소를 제기한 일부 고객을 절차에서 제외한다.","src":"약관법 제28조의2 제6항 | 약관법 시행령 제9조의6 | 기출 2022-39"},{"t":"한국공정거래조정원은 집단분쟁조정 대상 발굴, 조정에 의한 피해구제 사례 연구 등 활성화에 필요한 연구를 하며 결과를 인터넷 홈페이지에 공개한다.","src":"약관법 제28조의2 제9항 | 기출 2024-36"}]}],"함정":[{"x":"협의회의 전체회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 3분의 2의 찬성으로 의결한다.","o":"전체회의는 재적위원 과반수 출석, 출석위원 과반수 찬성으로 의결한다.","src":"약관법 제25조 제3항 | 기출 2021-39"},{"x":"약관 분쟁조정협의회는 집단분쟁조정의 당사자인 다수의 고객 중 일부의 고객이 법원에 소를 제기한 경우에는 그 분쟁조정절차를 중지한다.","o":"일부 고객이 소를 제기해도 절차를 중지하지 않고 그 고객을 절차에서 제외한다.","src":"약관법 제28조의2 제6항 | 기출 2022-39"},{"x":"조정을 신청 또는 의뢰받은 날부터 30일이 경과하여도 조정이 성립되지 아니한 경우 협의회는 조정절차를 종료하여야 한다.","o":"60일(분쟁당사자 쌍방이 연장에 동의하면 90일)이 지나도 조정이 성립하지 않으면 종료한다.","src":"약관법 제27조의2 제4항 제2호 | 기출 2023-34"},{"x":"한국소비자원은 협의회에 집단분쟁조정을 의뢰 또는 신청할 수 있다.","o":"집단분쟁조정은 공정거래위원회, 고객 또는 사업자가 의뢰·신청한다. 한국소비자원은 규정에 없다.","src":"약관법 제28조의2 제1항 | 기출 2024-36"},{"x":"협의회 위원장은 집단분쟁조정의 당사자가 아닌 고객의 그 분쟁조정의 참가 신청을 거절할 수 있다.","o":"협의회는 당사자가 아닌 고객으로부터 당사자 추가 신청을 받을 수 있다.","src":"약관법 제28조의2 제3항 | 기출 2025-34"},{"x":"협의회 위원장은 집단분쟁조정의 당사자 중에서 1인 또는 수인을 대표당사자로 선임 할 수 있다.","o":"대표당사자는 협의회의 의결로 선임할 수 있다(위원장이 선임하는 것이 아니다).","src":"약관법 제28조의2 제4항 | 기출 2025-34"},{"x":"협의회 위원장은 사업자가 협의회의 집단분쟁조정의 내용을 수락한 경우에는 집단 분쟁조정의 당사자가 아닌 자로서 피해를 입은 고객에 대한 보상계획서를 작성하여 협의회에 제출하도록 명령할 수 있다.","o":"보상계획서 제출은 '권고'할 수 있다(명령 아님).","src":"약관법 제28조의2 제5항 | 기출 2025-34"},{"x":"집단분쟁조정의 기간은 공고가 종료된 날부터 기산한다.","o":"공고가 종료된 날의 다음 날부터 기산한다.","src":"약관법 제28조의2 제7항 | 기출 2025-34"}]}};
